  app.get("/api/my-permissions", isAuthenticated, async (req, res) => {
    try {
      const currentUser = getCurrentUser(req);
      if (!currentUser) {
        return res.status(401).json({ error: "Not authenticated" });
      }
      
      // Admins have all permissions
      if (currentUser.role === "admin") {
        const allPermissions = SYSTEM_MODULES.map(module => ({
          module,
          actions: [...MODULE_ACTIONS],
        }));
        return res.json(allPermissions);
      }
      
      // Attendance clerk has ONLY attendance_check permissions
      if (currentUser.role === "attendance_clerk") {
        const attendancePermissions = [{
          module: "attendance_check",
          actions: ["view", "create", "edit"],
        }];

        return res.json(attendancePermissions);
      }
      
      // Use auth cache first, then fall back to route-level cache
      const { getCachedPermissionsForUser } = await import("./auth");
      const authCachedPerms = getCachedPermissionsForUser(currentUser.id);
      let permissions: any[] = (authCachedPerms && authCachedPerms.length > 0)
        ? authCachedPerms
        : (await getCachedPermissions(currentUser.id)) || [];

      // HR Manager: merge the server-side auto-granted HR modules into the
      // returned set so the frontend (canView/canEdit) matches what the backend
      // actually authorizes. Without this, the HR Hub opens but employees /
      // attendance / recruitment sections are hidden and render empty.
      if (currentUser.role === "hr_manager") {
        const merged = new Map<string, Set<string>>();
        for (const p of permissions) {
          merged.set(p.module, new Set(p.actions || []));
        }
        for (const m of HR_MANAGER_MODULES) {
          const set = merged.get(m) || new Set<string>();
          for (const a of MODULE_ACTIONS) set.add(a);
          merged.set(m, set);
        }
        permissions = Array.from(merged.entries()).map(([module, actions]) => ({
          module,
          actions: Array.from(actions),
        }));
      }

      res.json(permissions);
    } catch (error) {
      console.error("Error fetching my permissions:", error);
      res.status(500).json({ error: "Failed to fetch permissions" });
    }
  });

  // Branches - Returns all branches for admins, only assigned branch for non-admins
  app.get("/api/branches", isAuthenticated, async (req, res) => {
    try {
      const branches = await getCachedBranches();
      const user = req.currentUser;
      
      // SECURITY: Filter branches based on user role and branch access
      if (isUserAdmin(req)) {
        // Admins can see all branches
        res.json(branches);
      } else if (user) {
        // Get user's allowed branches from user_branch_access table
        const userBranchAccess = await storage.getUserBranchAccess(user.id);
        
        if (userBranchAccess.length > 0) {
          // User has specific branch access - filter by those branches
          const allowedBranchIds = userBranchAccess.map(ba => ba.branchId);
          const filteredBranches = branches.filter((b: any) => allowedBranchIds.includes(b.id));
          res.json(filteredBranches);
        } else if (user.branchId) {
          // Fallback to user's default branch from users table
          const filteredBranches = branches.filter((b: any) => b.id === user.branchId);
          res.json(filteredBranches);
        } else {
          // No branch access at all
          return res.json([]);
        }
      } else {
        return res.json([]);
      }
    } catch (error) {
      console.error("Error fetching branches:", error);
      res.status(500).json({ error: "Failed to fetch branches" });
    }
  });

