  app.get("/api/construction/daily-logs/:id", isAuthenticated, requirePermission("project_daily_logs", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) return res.status(400).json({ error: "Invalid ID" });
      const log = await storage.getDailyLog(id);
      if (!log) return res.status(404).json({ error: "اليومية غير موجودة" });
      const access = await checkProjectBranchAccess(req, log.projectId);
      if (!access.allowed) return res.status(403).json({ error: "غير مصرح" });

      // Photos query is on a long-existing table — let real errors bubble up.
      const photos = await storage.getDailyLogPhotos(id).catch((e) => {
        console.error("Error fetching daily log photos:", e);
        return [];
      });

      // Activities and expense-back-ref queries depend on migration 013 (new
      // table `daily_log_activities` + new column `project_expenses.daily_log_id`).
      // If that migration hasn't been applied yet on the target DB, degrade
      // gracefully instead of hard-failing the entire daily-log fetch (which
      // would render the page as "اليومية غير موجودة" to the user).
      const [activities, expenses] = await Promise.all([
        storage.getDailyLogActivities(id).catch((e) => {
          console.error("[daily-log] activities query failed (migration 013 missing?):", e?.message || e);
          return [];
        }),
        storage.getDailyLogExpenses(id).catch((e) => {
          console.error("[daily-log] expenses query failed (migration 013 missing?):", e?.message || e);
          return [];
        }),
      ]);
      res.json({ ...log, photos, activities, expenses });
    } catch (error) {
      console.error("Error fetching daily log:", error);
      res.status(500).json({ error: "فشل في جلب اليومية" });
    }
  });

  app.post("/api/construction/daily-logs", isAuthenticated, requirePermission("project_daily_logs", "create"), async (req, res) => {
    try {
      // Strip client-supplied branchId/createdBy to prevent spoofing; both come from server-side access check
      const { branchId: _ignored, createdBy: _alsoIgnored, ...clientPayload } = req.body || {};
      const validated = insertProjectDailyLogSchema.parse({
        ...clientPayload,
        createdBy: req.currentUser?.id,
      });
      const access = await checkProjectBranchAccess(req, validated.projectId);
      if (!access.allowed) return res.status(403).json({ error: "غير مصرح بإضافة يومية لهذا المشروع" });
      // Force branchId from project's actual branch (defense against spoofing)
      validated.branchId = access.branchId ?? null;
      // Normalize status to whitelist
      if (validated.status && !["draft", "submitted"].includes(validated.status)) {
        validated.status = "draft";
      }
      const created = await storage.createDailyLog(validated);
      res.status(201).json(created);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid data", details: error.errors });
      }
      console.error("Error creating daily log:", error);
      res.status(500).json({ error: "فشل في إنشاء اليومية" });
    }
  });

  app.patch("/api/construction/daily-logs/:id", isAuthenticated, requirePermission("project_daily_logs", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) return res.status(400).json({ error: "Invalid ID" });
      const existing = await storage.getDailyLog(id);
      if (!existing) return res.status(404).json({ error: "اليومية غير موجودة" });
      const access = await checkProjectBranchAccess(req, existing.projectId);
      if (!access.allowed) return res.status(403).json({ error: "غير مصرح" });
      // Strip immutable fields to prevent project/branch hijack
      const { projectId: _p, branchId: _b, createdBy: _c, id: _i, createdAt: _ca, updatedAt: _ua, ...editable } = req.body || {};
      const validated = insertProjectDailyLogSchema.partial().parse(editable);
      // Normalize status to whitelist
      if (validated.status !== undefined && !["draft", "submitted"].includes(validated.status as string)) {
        validated.status = "draft";
      }
      // Defense-in-depth: once a log is finalized (submitted), don't allow a
      // PATCH to silently downgrade it back to draft (e.g. a stale auto-save
      // tick on a slow connection). Only an explicit re-submission is allowed.
      if (
        (existing as any).status === "submitted" &&
        validated.status === "draft"
      ) {
        return res.status(409).json({ error: "لا يمكن إرجاع يومية معتمدة إلى مسودة" });
      }
      const updated = await storage.updateDailyLog(id, validated);
      res.json(updated);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid data", details: error.errors });
      }
      console.error("Error updating daily log:", error);
      res.status(500).json({ error: "فشل في تعديل اليومية" });
    }
  });

