  app.post("/api/operations-employees", isAuthenticated, requirePermission("operations", "create"), async (req, res) => {
    try {
      const { username, password, firstName, lastName, phone, email, branchId, jobTitle, role } = req.body;
      
      if (!username || !password) {
        return res.status(400).json({ error: "اسم المستخدم وكلمة المرور مطلوبان" });
      }
      
      if (username.length < 3 || username.length > 50) {
        return res.status(400).json({ error: "اسم المستخدم يجب أن يكون بين 3 و 50 حرفاً" });
      }
      
      if (password.length < 8) {
        return res.status(400).json({ error: "كلمة المرور يجب أن تكون 8 أحرف على الأقل" });
      }
      if (password.length > 128) {
        return res.status(400).json({ error: "كلمة المرور طويلة جداً" });
      }
      if (!/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password)) {
        return res.status(400).json({ error: "كلمة المرور يجب أن تحتوي على حروف كبيرة وصغيرة وأرقام" });
      }
      
      if (!branchId) {
        return res.status(400).json({ error: "يرجى اختيار الفرع" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بإضافة موظفين لهذا الفرع" });
        }
      }
      
      const existingUser = await storage.getUserByUsername(username);
      if (existingUser) {
        return res.status(400).json({ error: "اسم المستخدم مسجل مسبقاً" });
      }
      
      // SECURITY: Only admins may assign privileged roles via this endpoint.
      // Non-admins with operations:create can only create regular "employee" accounts.
      const OP_PRIVILEGED_ROLES = new Set(["admin", "hr_manager", "financial_accountant", "attendance_clerk"]);
      const opRequestedRole = (role as string | undefined) || "employee";
      if (OP_PRIVILEGED_ROLES.has(opRequestedRole) && !isUserAdmin(req)) {
        return res.status(403).json({ error: "فقط المسؤولين يمكنهم منح هذا الدور" });
      }
      if (!["admin", "hr_manager", "financial_accountant", "employee", "viewer", "attendance_clerk"].includes(opRequestedRole)) {
        return res.status(400).json({ error: "دور غير صالح" });
      }
      
      const user = await storage.createUser({
        username,
        password,
        firstName,
        lastName,
        phone,
        email,
        branchId,
        jobTitle,
        role: opRequestedRole,
        isActive: "active",
      });
      
      // Apply job role permissions automatically based on job title
      if (jobTitle && req.currentUser && JOB_TITLES.includes(jobTitle as typeof JOB_TITLES[number])) {
        await storage.applyJobRolePermissions(user.id, jobTitle, req.currentUser.id);
      }
      
      const { password: _, ...safeUser } = user;
      res.status(201).json(safeUser);
    } catch (error) {
      console.error("Error creating operations employee:", error);
      res.status(500).json({ error: "Failed to create operations employee" });
    }
  });

  // Update operations employee
