  // Enhanced P&L Summary - ملخص الأرباح والخسائر المحسن
  app.get("/api/pnl/enhanced-summary", isAuthenticated, requirePermission("pnl", "view"), async (req, res) => {
    const __t0 = Date.now();
    try {
      const { branchId, year, month, asOfDate } = req.query;
      const yearNum = parseInt(year as string) || new Date().getFullYear();
      const monthNum = parseInt(month as string) || new Date().getMonth() + 1;

      // === Pro-rata "حتى تاريخ" ====================================
      // إذا مرّر العميل asOfDate (YYYY-MM-DD) داخل نفس السنة/الشهر:
      //   - نَحْسب المبيعات الفعلية حتى ذلك اليوم فقط.
      //   - نُقَسِّم المصاريف الشهرية بالتناسب: monthly × elapsedDays / 30
      //     (المستخدم اختار قسمة ثابتة على 30 يوم).
      //   - نُضيف "توقع لنهاية الشهر" بناءً على المعدّل اليومي.
      // بدون asOfDate → كل شيء كامل (سلوك الشهر الكامل كما كان).
      const isValidIsoDate = (s: string) => /^\d{4}-\d{2}-\d{2}$/.test(s);
      const BILLING_DAYS = 30; // قسمة ثابتة على 30 يوم بناء على تفضيل المستخدم
      const daysInActualMonth = new Date(yearNum, monthNum, 0).getDate();
      let asOfStr: string | null = null;
      let elapsedDays = daysInActualMonth; // افتراضياً الشهر كامل
      let isPartial = false;
      if (typeof asOfDate === 'string' && isValidIsoDate(asOfDate)) {
        // تفسير سلسلة YYYY-MM-DD مباشرةً دون الاعتماد على المنطقة الزمنية للخادم
        const [yStr, mStr, dStr] = asOfDate.split('-');
        const yy = parseInt(yStr, 10);
        const mm = parseInt(mStr, 10);
        const dd = parseInt(dStr, 10);
        if (yy === yearNum && mm === monthNum && dd >= 1 && dd <= daysInActualMonth) {
          asOfStr = asOfDate;
          elapsedDays = dd;
          isPartial = elapsedDays < daysInActualMonth;
        }
      }
      // معامل التناسب للمصاريف (مقصور بحد أقصى 1 — لو اختار يوم 31 مع تقسيم 30)
      const prorateFactor = Math.min(elapsedDays, BILLING_DAYS) / BILLING_DAYS;
      // معامل التوقع للمبيعات إلى نهاية الشهر (المعدل اليومي × 30)
      const projectionFactor = elapsedDays > 0 ? BILLING_DAYS / elapsedDays : 1;

      const branchFilter = getEffectiveBranchFilter(req, branchId as string | undefined);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      let branchIds: string[] = [];
      if (branchFilter.singleBranchId) {
        branchIds = [branchFilter.singleBranchId];
      } else if (branchFilter.branchIds) {
        branchIds = branchFilter.branchIds;
      } else {
        const branches = await storage.getAllBranches();
        branchIds = branches.map(b => b.id);
      }
      
      // Use cached getAllBranches lookup instead of N separate getBranch() calls
      const allBranchesForLookup = await storage.getAllBranches();
      const branchMap = new Map(allBranchesForLookup.map(b => [b.id, b]));

      // Compute the previous month for deltas. Wraps year boundary.
      const prevMonthNum = monthNum === 1 ? 12 : monthNum - 1;
      const prevYearNum = monthNum === 1 ? yearNum - 1 : yearNum;

      // Process branches in small batches to respect the DB pool limit
      // (Supabase pool max=15; each branch issues 4 parallel queries → batch of 3 = 12 concurrent queries, safely under the limit).
      const BRANCH_BATCH_SIZE = 3;
      const processBranch = async (bId: string) => {
        const branch = branchMap.get(bId);
        if (!branch) return null;

        const [journalsResult, settings, inputs, prevInputs, allBranchEmps, periodRent, prevPeriodRent, recurringList, prevRecurringList] = await Promise.all([
          storage.getCashierJournalsFiltered({ branchId: bId }),
          storage.getPnlBranchSettings(bId),
          storage.getPnlMonthlyInputs(bId, yearNum, monthNum),
          storage.getPnlMonthlyInputs(bId, prevYearNum, prevMonthNum),
          storage.getBranchEmployeesByBranch(bId),
          storage.getRentForPeriod(bId, yearNum, monthNum),
          storage.getRentForPeriod(bId, prevYearNum, prevMonthNum),
          storage.getRecurringExpensesForPeriod(bId, yearNum, monthNum),
          storage.getRecurringExpensesForPeriod(bId, prevYearNum, prevMonthNum),
        ]);

        // فلترة اليوميات المعتمدة فقط (posted أو approved)
        const approvedJournals = journalsResult.journals.filter((j: any) =>
          j.status === 'posted' || j.status === 'approved'
        );

        // Filter by date range from approved journals
        // عند تفعيل asOfDate نَقصُر مبيعات الشهر على الأيام حتى ذلك التاريخ شاملاً.
        // نُفسِّر تاريخ القيد كسلسلة YYYY-MM-DD مباشرةً لتجنّب اختلاف المناطق الزمنية.
        const parseJDate = (val: any): { y: number; m: number; d: number } | null => {
          if (!val) return null;
          const s = typeof val === 'string' ? val : (val instanceof Date ? val.toISOString() : String(val));
          const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
          if (!m) return null;
          return { y: parseInt(m[1], 10), m: parseInt(m[2], 10), d: parseInt(m[3], 10) };
        };
        const monthJournals = approvedJournals.filter((j: any) => {
          const p = parseJDate(j.journalDate);
          if (!p) return false;
          if (p.y !== yearNum || p.m !== monthNum) return false;
          if (isPartial && p.d > elapsedDays) return false;
          return true;
        });
        const prevMonthJournals = approvedJournals.filter((j: any) => {
          const p = parseJDate(j.journalDate);
          if (!p) return false;
          return p.y === prevYearNum && p.m === prevMonthNum;
        });

        const grossSales = monthJournals.reduce((sum: number, j: any) => sum + (j.totalSales || 0), 0);
        const prevGrossSales = prevMonthJournals.reduce((sum: number, j: any) => sum + (j.totalSales || 0), 0);

        // Build a daily revenue series for the requested month. The frontend
        // uses this to render the "Revenue Breakdown" stacked/area chart.
        const daysInMonth = new Date(yearNum, monthNum, 0).getDate();
        const dailyMap = new Map<number, { gross: number; transactions: number }>();
        for (const j of monthJournals) {
          const p = parseJDate(j.journalDate);
          if (!p) continue;
          const day = p.d;
          const cur = dailyMap.get(day) || { gross: 0, transactions: 0 };
          cur.gross += j.totalSales || 0;
          cur.transactions += j.transactionCount || 0;
          dailyMap.set(day, cur);
        }
        const dailySeries = Array.from({ length: daysInMonth }, (_, i) => {
          const d = i + 1;
          const v = dailyMap.get(d) || { gross: 0, transactions: 0 };
          return {
            day: d,
            date: `${yearNum}-${String(monthNum).padStart(2, '0')}-${String(d).padStart(2, '0')}`,
            gross: v.gross,
            net: v.gross / 1.15,
            vat: v.gross - v.gross / 1.15,
            transactions: v.transactions,
          };
        });

        // VAT (15%) - صافي المبيعات = الإجمالي ÷ 1.15
        const netSales = grossSales / 1.15;
        const vatAmount = grossSales - netSales;

        // v2: rent comes from pnl_rent_history (effective-date lookup) and
        // recurring expenses are auto-summed per period. settings.monthlyRent
        // is kept only as a fallback inside getRentForPeriod.
        // === Pro-rata: كل المصاريف الشهرية تُضرب في prorateFactor عند تفعيل asOfDate ===
        // (prorateFactor = 1 في حالة الشهر الكامل، فلا يتأثر السلوك القديم).
        const pf = prorateFactor;
        const monthlyRent = (periodRent || 0) * pf;
        const electricityCost = (inputs?.electricityCost || 0) * pf;
        const waterCost = (inputs?.waterCost || 0) * pf;
        const utilitiesOther = (inputs?.utilitiesOther || 0) * pf;
        // COGS is now a fixed ratio of net sales (admin-configurable, default
        // 30%, stored in pnl_global_settings and cached in memory). يتبع تلقائياً
        // المبيعات الفعلية حتى التاريخ المحدد دون الحاجة لضرب prorate.
        const cogsRatio = await storage.getCogsRatio();
        const cogsCost = Math.round(netSales * cogsRatio);
        const maintenanceCost = (inputs?.maintenanceCost || 0) * pf;
        const marketingCost = (inputs?.marketingCost || 0) * pf;
        const suppliesCost = (inputs?.suppliesCost || 0) * pf;
        const otherCosts = (inputs?.otherCosts || 0) * pf;
        // v2 new expense columns (manual monthly entry) — prorated
        const internetCost = (inputs?.internetCost || 0) * pf;
        const governmentFees = (inputs?.governmentFees || 0) * pf;
        const insuranceCost = (inputs?.insuranceCost || 0) * pf;
        const subscriptionsCost = (inputs?.subscriptionsCost || 0) * pf;
        const securityCost = (inputs?.securityCost || 0) * pf;
        const bankFees = (inputs?.bankFees || 0) * pf;
        const fuelCost = (inputs?.fuelCost || 0) * pf;
        const recurringTotal = recurringList.reduce((s, r) => s + (r.monthlyAmount || 0), 0) * pf;
        const extraGeneral = internetCost + governmentFees + insuranceCost
          + subscriptionsCost + securityCost + bankFees + fuelCost;

        const employees = allBranchEmps.filter((e: any) => e.status === 'active');
        let totalSalaries = 0;
        let totalGosi = 0; // Saudi GOSI 12%
        let totalNonSaudiCosts = 0; // Expat levy (المقابل المالي شامل رخصة العمل) 800, Residency 54, Insurance 2%
        
        // قائمة الجنسيات السعودية (بالعربية والإنجليزية)
        const saudiNationalities = ['Saudi', 'saudi', 'سعودي', 'سعودية', 'Saudi Arabia', 'SA'];

        // Per-employee breakdown for the new "Active Employees" panel on the
        // dashboard. Includes the same payroll calculation as the totals so
        // the table and aggregate always reconcile.
        const employeesList: Array<{
          id: any;
          name: string;
          position: string | null;
          nationality: string | null;
          isSaudi: boolean;
          baseSalary: number;
          housingAllowance: number;
          transportAllowance: number;
          totalCompensation: number;
          gosi: number;
          nonSaudiOverhead: number;
          totalCost: number;
        }> = [];

        for (const emp of employees) {
          // استخدام أسماء الأعمدة الصحيحة من قاعدة البيانات
          const baseSalary = Number((emp as any).salary) || 0;
          const housingAllowance = Number((emp as any).housingAllowance ?? (emp as any).housing_allowance) || 0;
          const transportAllowance = Number((emp as any).transportAllowance ?? (emp as any).transport_allowance) || 0;
          const totalCompensation = baseSalary + housingAllowance + transportAllowance;
          
          totalSalaries += totalCompensation;
          
          const nationality = ((emp as any).nationality || '').trim();
          const isSaudi = saudiNationalities.some(n => 
            nationality.toLowerCase().includes(n.toLowerCase()) || n.toLowerCase().includes(nationality.toLowerCase())
          );
          
          let empGosi = 0;
          let empNonSaudi = 0;
          if (isSaudi) {
            const gosiBase = baseSalary + housingAllowance;
            empGosi = gosiBase * 0.12;
            totalGosi += empGosi;
          } else {
            // المقابل المالي (Expat Levy) شامل رسوم رخصة العمل = 9,600 ر.س
            // سنوياً = 800 شهرياً. منذ إصلاحات 2017-2018 لم تعد هناك رسوم
            // منفصلة لرخصة العمل تُسدد شهرياً بجانب المقابل المالي.
            const expatLevyMonthly = 800;       // المقابل المالي (شامل رخصة العمل)
            const residencyMonthly = 54;        // رسوم الإقامة الشهرية
            const insuranceRate = 0.02;         // تأمين طبي تقريبي 2% من الراتب
            empNonSaudi = expatLevyMonthly + residencyMonthly + (totalCompensation * insuranceRate);
            totalNonSaudiCosts += empNonSaudi;
          }

          employeesList.push({
            id: (emp as any).id,
            name: (emp as any).fullName || (emp as any).name || (emp as any).employeeName || '—',
            position: (emp as any).position || (emp as any).jobTitle || null,
            nationality: nationality || null,
            isSaudi,
            baseSalary,
            housingAllowance,
            transportAllowance,
            totalCompensation,
            gosi: empGosi,
            nonSaudiOverhead: empNonSaudi,
            totalCost: totalCompensation + empGosi + empNonSaudi,
          });
        }
        // Largest cost first — easier to spot the top contributors.
        employeesList.sort((a, b) => b.totalCost - a.totalCost);

        // ملاحظة: قيم employeesList تبقى شهرية كاملة (للعرض) — لكن الإجمالي
        // المستخدم في حساب المصاريف يتم تناسبه مع الفترة.
        const totalEmployeeCostsFull = totalSalaries + totalGosi + totalNonSaudiCosts;
        const totalEmployeeCosts = totalEmployeeCostsFull * pf;

        // 7. Calculate totals
        const totalUtilities = electricityCost + waterCost + utilitiesOther;
        const totalOperatingCosts = totalEmployeeCosts + monthlyRent + totalUtilities
          + maintenanceCost + marketingCost + suppliesCost + otherCosts
          + extraGeneral + recurringTotal;

        // 8. Calculate profit
        const grossProfit = netSales - cogsCost;
        const operatingProfit = grossProfit - totalOperatingCosts;
        const netProfit = operatingProfit;

        // 9. Calculate percentages
        const grossMargin = netSales > 0 ? (grossProfit / netSales) * 100 : 0;
        const netMargin = netSales > 0 ? (netProfit / netSales) * 100 : 0;

        // === توقع لنهاية الشهر (Projection) ====================================
        // المعدّل اليومي للمبيعات الفعلية × 30 يوم → مبيعات متوقعة.
        // المصاريف المتوقعة = نسخة الشهر الكامل (قبل التناسب) لأن البنود الشهرية
        // ستُسجَّل بالكامل عند نهاية الشهر بصرف النظر عن التاريخ الحالي.
        const projGrossSales = grossSales * projectionFactor;
        const projNetSales = projGrossSales / 1.15;
        const projVat = projGrossSales - projNetSales;
        const projCogs = Math.round(projNetSales * cogsRatio);
        const projGrossProfit = projNetSales - projCogs;
        const fullMonthOpex = totalEmployeeCostsFull + (periodRent || 0)
          + (inputs?.electricityCost || 0) + (inputs?.waterCost || 0) + (inputs?.utilitiesOther || 0)
          + (inputs?.maintenanceCost || 0) + (inputs?.marketingCost || 0)
          + (inputs?.suppliesCost || 0) + (inputs?.otherCosts || 0)
          + (inputs?.internetCost || 0) + (inputs?.governmentFees || 0)
          + (inputs?.insuranceCost || 0) + (inputs?.subscriptionsCost || 0)
          + (inputs?.securityCost || 0) + (inputs?.bankFees || 0) + (inputs?.fuelCost || 0)
          + recurringList.reduce((s, r) => s + (r.monthlyAmount || 0), 0);
        const projOperatingProfit = projGrossProfit - fullMonthOpex;
        const projNetProfit = projOperatingProfit;
        const projNetMargin = projNetSales > 0 ? (projNetProfit / projNetSales) * 100 : 0;
        
        return {
          branchId: bId,
          branchName: branch.name,
          branchNameEn: branch.name, // Use Arabic name for now
          year: yearNum,
          month: monthNum,

          // Sales
          grossSales,
          vatAmount,
          netSales,

          // COGS
          cogsCost,
          grossProfit,
          grossMargin,

          // Employee costs breakdown
          // ملاحظة: في الوضع الجزئي نُطبّق نفس معامل التناسب (pf) على
          // المكوّنات الفرعية حتى تتطابق مع الإجمالي ولا يحدث تباين في
          // العرض. القيم الشهرية الكاملة متاحة في employeesList للمرجع.
          employeeCosts: {
            salaries: totalSalaries * pf,
            gosi: totalGosi * pf,
            nonSaudiCosts: totalNonSaudiCosts * pf,
            total: totalEmployeeCosts,
            // مرجع للقيم الشهرية الكاملة (للتدقيق والعرض المقارن)
            salariesFull: totalSalaries,
            gosiFull: totalGosi,
            nonSaudiCostsFull: totalNonSaudiCosts,
            totalFull: totalEmployeeCostsFull,
          },

          // Fixed costs
          rent: monthlyRent,

          // Variable costs
          utilities: {
            electricity: electricityCost,
            water: waterCost,
            other: utilitiesOther,
            total: totalUtilities
          },

          // Other operating costs
          operatingCosts: {
            maintenance: maintenanceCost,
            marketing: marketingCost,
            supplies: suppliesCost,
            other: otherCosts
          },

          // v2: extra general expenses (manual monthly)
          generalExpenses: {
            internet: internetCost,
            government: governmentFees,
            insurance: insuranceCost,
            subscriptions: subscriptionsCost,
            security: securityCost,
            bankFees,
            fuel: fuelCost,
            total: extraGeneral,
          },

          // v2: recurring expenses auto-applied for this period
          recurringExpenses: {
            total: recurringTotal,
            items: recurringList.map(r => ({
              id: r.id,
              category: r.category,
              name: r.name,
              monthlyAmount: r.monthlyAmount,
              vendor: r.vendor,
            })),
          },

          totalOperatingCosts,
          operatingProfit,
          netProfit,
          netMargin,

          // Daily revenue series for the requested month (charts)
          dailySeries,

          // Per-employee payroll breakdown (Active Employees panel)
          employeesList,

          // Useful operating ratios (computed once on the server so all
          // clients agree on the same denominators)
          ratios: {
            salaryToSales: netSales > 0 ? (totalEmployeeCosts / netSales) * 100 : 0,
            rentToSales: netSales > 0 ? (monthlyRent / netSales) * 100 : 0,
            cogsToSales: netSales > 0 ? (cogsCost / netSales) * 100 : 0,
            utilitiesToSales: netSales > 0 ? (totalUtilities / netSales) * 100 : 0,
            opexToSales: netSales > 0 ? (totalOperatingCosts / netSales) * 100 : 0,
            grossMargin,
            netMargin,
          },

          // Previous-month comparison block. Uses prev-month sales + prev-month
          // monthly_inputs but keeps the *current* payroll as a stable baseline
          // (payroll changes month-to-month are tracked separately via the
          // monthly closing flow, not via active-employee snapshots).
          previousMonth: (() => {
            const prevElectricity = prevInputs?.electricityCost || 0;
            const prevWater = prevInputs?.waterCost || 0;
            const prevUtilsOther = prevInputs?.utilitiesOther || 0;
            const prevMaint = prevInputs?.maintenanceCost || 0;
            const prevMarketing = prevInputs?.marketingCost || 0;
            const prevSupplies = prevInputs?.suppliesCost || 0;
            const prevOther = prevInputs?.otherCosts || 0;
            const prevExtra = (prevInputs?.internetCost || 0) + (prevInputs?.governmentFees || 0)
              + (prevInputs?.insuranceCost || 0) + (prevInputs?.subscriptionsCost || 0)
              + (prevInputs?.securityCost || 0) + (prevInputs?.bankFees || 0)
              + (prevInputs?.fuelCost || 0);
            const prevRecurringTotal = prevRecurringList.reduce((s, r) => s + (r.monthlyAmount || 0), 0);
            const prevNetSales = prevGrossSales / 1.15;
            // Same admin-configurable COGS ratio for previous-period comparison.
            const prevCogs = Math.round(prevNetSales * cogsRatio);
            // نستخدم رواتب الشهر الكامل (totalEmployeeCostsFull) كأساس مرجعي
            // للمقارنة مع الشهر السابق — لتجنّب تشويش الـ delta عند تفعيل
            // "حتى تاريخ" (وإلا سيظهر تحسّن وهمي بسبب تناسب رواتب الفترة الحالية).
            const prevTotalOpex = totalEmployeeCostsFull + (prevPeriodRent || 0)
              + prevElectricity + prevWater + prevUtilsOther
              + prevMaint + prevMarketing + prevSupplies + prevOther
              + prevExtra + prevRecurringTotal;
            const prevGrossProfit = prevNetSales - prevCogs;
            const prevNetProfit = prevGrossProfit - prevTotalOpex;
            // Signed-safe delta: works when previous value is negative (loss → profit)
            const delta = (current: number, prev: number) => {
              if (prev === 0) return current === 0 ? 0 : current > 0 ? 100 : -100;
              return ((current - prev) / Math.abs(prev)) * 100;
            };
            return {
              year: prevYearNum,
              month: prevMonthNum,
              grossSales: prevGrossSales,
              netSales: prevNetSales,
              netProfit: prevNetProfit,
              // المقارنة على صافي المبيعات (بعد خصم الضريبة)
              revenueChangePct: delta(netSales, prevNetSales),
              profitChangePct: delta(netProfit, prevNetProfit),
            };
          })(),

          // === معلومات الفترة "حتى تاريخ" ===
          asOf: {
            date: asOfStr,                  // null إذا كان الشهر الكامل
            elapsedDays,                    // الأيام المنقضية المحسوبة
            daysInMonth: daysInActualMonth, // عدد أيام الشهر الفعلي (28/29/30/31)
            billingDays: BILLING_DAYS,      // الأساس المستخدم في التناسب (30)
            prorateFactor,                  // ضرب المصاريف
            isPartial,                      // true إذا كان عرضاً جزئياً
          },

          // === توقع لنهاية الشهر (مبني على المعدّل اليومي للمبيعات
          //     + الالتزامات الشهرية الكاملة للمصاريف) ===
          projection: {
            grossSales: projGrossSales,
            netSales: projNetSales,
            vatAmount: projVat,
            cogsCost: projCogs,
            grossProfit: projGrossProfit,
            totalOperatingCosts: fullMonthOpex,
            operatingProfit: projOperatingProfit,
            netProfit: projNetProfit,
            netMargin: projNetMargin,
          },

          // Metadata
          journalCount: monthJournals.length,
          employeeCount: employees.length,
          hasMonthlyInputs: !!inputs
        };
      };

      const branchResults: Array<Awaited<ReturnType<typeof processBranch>>> = [];
      for (let i = 0; i < branchIds.length; i += BRANCH_BATCH_SIZE) {
        const batch = branchIds.slice(i, i + BRANCH_BATCH_SIZE);
        const batchResults = await Promise.all(batch.map(processBranch));
        branchResults.push(...batchResults);
      }

      const results = branchResults.filter((r): r is NonNullable<typeof r> => r !== null);
      
      // Calculate company-wide totals if multiple branches
      if (results.length > 1) {
        const totals = {
          branchId: 'all',
          branchName: 'جميع الفروع',
          branchNameEn: 'All Branches',
          year: yearNum,
          month: monthNum,
          grossSales: results.reduce((s, r) => s + r.grossSales, 0),
          vatAmount: results.reduce((s, r) => s + r.vatAmount, 0),
          netSales: results.reduce((s, r) => s + r.netSales, 0),
          cogsCost: results.reduce((s, r) => s + r.cogsCost, 0),
          grossProfit: results.reduce((s, r) => s + r.grossProfit, 0),
          grossMargin: 0,
          employeeCosts: {
            salaries: results.reduce((s, r) => s + r.employeeCosts.salaries, 0),
            gosi: results.reduce((s, r) => s + r.employeeCosts.gosi, 0),
            nonSaudiCosts: results.reduce((s, r) => s + r.employeeCosts.nonSaudiCosts, 0),
            total: results.reduce((s, r) => s + r.employeeCosts.total, 0)
          },
          rent: results.reduce((s, r) => s + r.rent, 0),
          utilities: {
            electricity: results.reduce((s, r) => s + r.utilities.electricity, 0),
            water: results.reduce((s, r) => s + r.utilities.water, 0),
            other: results.reduce((s, r) => s + r.utilities.other, 0),
            total: results.reduce((s, r) => s + r.utilities.total, 0)
          },
          operatingCosts: {
            maintenance: results.reduce((s, r) => s + r.operatingCosts.maintenance, 0),
            marketing: results.reduce((s, r) => s + r.operatingCosts.marketing, 0),
            supplies: results.reduce((s, r) => s + r.operatingCosts.supplies, 0),
            other: results.reduce((s, r) => s + r.operatingCosts.other, 0)
          },
          generalExpenses: {
            internet: results.reduce((s, r) => s + (r.generalExpenses?.internet || 0), 0),
            government: results.reduce((s, r) => s + (r.generalExpenses?.government || 0), 0),
            insurance: results.reduce((s, r) => s + (r.generalExpenses?.insurance || 0), 0),
            subscriptions: results.reduce((s, r) => s + (r.generalExpenses?.subscriptions || 0), 0),
            security: results.reduce((s, r) => s + (r.generalExpenses?.security || 0), 0),
            bankFees: results.reduce((s, r) => s + (r.generalExpenses?.bankFees || 0), 0),
            fuel: results.reduce((s, r) => s + (r.generalExpenses?.fuel || 0), 0),
            total: results.reduce((s, r) => s + (r.generalExpenses?.total || 0), 0),
          },
          recurringExpenses: {
            total: results.reduce((s, r) => s + (r.recurringExpenses?.total || 0), 0),
            items: results.flatMap(r =>
              (r.recurringExpenses?.items || []).map(it => ({ ...it, branchId: r.branchId, branchName: r.branchName }))
            ),
          },
          totalOperatingCosts: results.reduce((s, r) => s + r.totalOperatingCosts, 0),
          operatingProfit: results.reduce((s, r) => s + r.operatingProfit, 0),
          netProfit: results.reduce((s, r) => s + r.netProfit, 0),
          netMargin: 0,
          journalCount: results.reduce((s, r) => s + r.journalCount, 0),
          employeeCount: results.reduce((s, r) => s + r.employeeCount, 0),
          hasMonthlyInputs: results.some(r => r.hasMonthlyInputs),

          // Daily series merged across all branches (one entry per day with
          // summed gross/net/vat/transactions). Lengths are identical because
          // every branch builds the same daysInMonth array.
          dailySeries: (() => {
            const days = results[0]?.dailySeries?.length || 0;
            return Array.from({ length: days }, (_, i) => {
              const sample = results[0].dailySeries[i];
              const gross = results.reduce((s, r) => s + (r.dailySeries[i]?.gross || 0), 0);
              const transactions = results.reduce((s, r) => s + (r.dailySeries[i]?.transactions || 0), 0);
              return {
                day: sample.day,
                date: sample.date,
                gross,
                net: gross / 1.15,
                vat: gross - gross / 1.15,
                transactions,
              };
            });
          })(),

          // Flatten all branches' employees so the dashboard can show one big
          // ranked table when "all branches" is selected. Each entry carries
          // its branch label for grouping.
          employeesList: results.flatMap(r =>
            r.employeesList.map(e => ({ ...e, branchId: r.branchId, branchName: r.branchName }))
          ).sort((a, b) => b.totalCost - a.totalCost),

          ratios: {
            salaryToSales: 0, rentToSales: 0, cogsToSales: 0,
            utilitiesToSales: 0, opexToSales: 0, grossMargin: 0, netMargin: 0,
          },

          previousMonth: {
            year: results[0]?.previousMonth.year ?? prevYearNum,
            month: results[0]?.previousMonth.month ?? prevMonthNum,
            grossSales: results.reduce((s, r) => s + (r.previousMonth?.grossSales || 0), 0),
            netSales: results.reduce((s, r) => s + (r.previousMonth?.netSales || 0), 0),
            netProfit: results.reduce((s, r) => s + (r.previousMonth?.netProfit || 0), 0),
            revenueChangePct: 0,
            profitChangePct: 0,
          },

          // === فترة "حتى تاريخ" — متطابقة عبر كل الفروع ===
          asOf: {
            date: asOfStr,
            elapsedDays,
            daysInMonth: daysInActualMonth,
            billingDays: BILLING_DAYS,
            prorateFactor,
            isPartial,
          },

          // === توقع نهاية الشهر — تجميع الفروع ===
          projection: {
            grossSales: results.reduce((s, r) => s + (r.projection?.grossSales || 0), 0),
            netSales: results.reduce((s, r) => s + (r.projection?.netSales || 0), 0),
            vatAmount: results.reduce((s, r) => s + (r.projection?.vatAmount || 0), 0),
            cogsCost: results.reduce((s, r) => s + (r.projection?.cogsCost || 0), 0),
            grossProfit: results.reduce((s, r) => s + (r.projection?.grossProfit || 0), 0),
            totalOperatingCosts: results.reduce((s, r) => s + (r.projection?.totalOperatingCosts || 0), 0),
            operatingProfit: results.reduce((s, r) => s + (r.projection?.operatingProfit || 0), 0),
            netProfit: results.reduce((s, r) => s + (r.projection?.netProfit || 0), 0),
            netMargin: 0,
          },
        };
        
        totals.grossMargin = totals.netSales > 0 ? (totals.grossProfit / totals.netSales) * 100 : 0;
        totals.netMargin = totals.netSales > 0 ? (totals.netProfit / totals.netSales) * 100 : 0;
        totals.projection.netMargin = totals.projection.netSales > 0
          ? (totals.projection.netProfit / totals.projection.netSales) * 100 : 0;

        const ns = totals.netSales || 0;
        totals.ratios = {
          salaryToSales: ns > 0 ? (totals.employeeCosts.total / ns) * 100 : 0,
          rentToSales: ns > 0 ? (totals.rent / ns) * 100 : 0,
          cogsToSales: ns > 0 ? (totals.cogsCost / ns) * 100 : 0,
          utilitiesToSales: ns > 0 ? (totals.utilities.total / ns) * 100 : 0,
          opexToSales: ns > 0 ? (totals.totalOperatingCosts / ns) * 100 : 0,
          grossMargin: totals.grossMargin,
          netMargin: totals.netMargin,
        };

        // Signed-safe MoM deltas — identical formula to the per-branch path
        // so single vs all-branches views agree even when previous profit
        // was negative.
        const pmDelta = (current: number, prev: number) => {
          if (prev === 0) return current === 0 ? 0 : current > 0 ? 100 : -100;
          return ((current - prev) / Math.abs(prev)) * 100;
        };
        // المقارنة على صافي المبيعات (بعد خصم ضريبة القيمة المضافة)
        totals.previousMonth.revenueChangePct = pmDelta(totals.netSales, totals.previousMonth.netSales);
        totals.previousMonth.profitChangePct = pmDelta(totals.netProfit, totals.previousMonth.netProfit);

        console.log(`[perf] /api/pnl/enhanced-summary (multi) branches=${results.length} took ${Date.now() - __t0}ms`);
        return res.json({ branches: results, totals });
      }

      console.log(`[perf] /api/pnl/enhanced-summary (single) branches=${results.length} took ${Date.now() - __t0}ms`);
      res.json({ branches: results, totals: results[0] || null });
    } catch (error) {
      console.error("Error getting enhanced P&L summary:", error);
      res.status(500).json({ error: "Failed to get enhanced P&L summary" });
    }
  });

  // ==================== P&L v2 — Rent History ====================
  // Returns the full rent history for a branch (newest effective date first).
  app.get("/api/pnl/rent-history/:branchId", isAuthenticated, requirePermission("pnl", "view"), async (req, res) => {
    try {
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, req.params.branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      }
      const rows = await storage.listRentHistory(req.params.branchId);
      res.json(rows);
    } catch (error) {
      console.error("Error listing rent history:", error);
      res.status(500).json({ error: "Failed to list rent history" });
    }
  });

  app.post("/api/pnl/rent-history", isAuthenticated, requirePermission("pnl", "edit"), async (req, res) => {
    try {
      const body = req.body || {};
      if (!body.branchId || !body.effectiveFrom || body.monthlyAmount == null) {
        return res.status(400).json({ error: "branchId, effectiveFrom, monthlyAmount مطلوبة" });
      }
      if (Number(body.monthlyAmount) < 0) {
        return res.status(400).json({ error: "قيمة الإيجار يجب أن تكون صفر أو أكبر" });
      }
      if (body.effectiveTo && String(body.effectiveTo) < String(body.effectiveFrom)) {
        return res.status(400).json({ error: "تاريخ انتهاء الصلاحية يجب أن يكون بعد تاريخ البداية" });
      }
      // For UPDATE: trust the stored record's branchId and verify the user can
      // access it (prevents IDOR where attacker submits a different branchId
      // for someone else's record). Also verify the *new* branchId in case the
      // record is being moved.
      if (body.id) {
        const existing = await storage.getRentHistoryEntryById(body.id);
        if (!existing) return res.status(404).json({ error: "السجل غير موجود" });
        if (!isUserAdmin(req)) {
          const okOld = await canAccessBranch(req, existing.branchId);
          const okNew = await canAccessBranch(req, body.branchId);
          if (!okOld || !okNew) return res.status(403).json({ error: "غير مصرح بتعديل هذا الفرع" });
        }
      } else if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, body.branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بتعديل هذا الفرع" });
      }
      const saved = await storage.upsertRentHistoryEntry({
        ...body,
        createdBy: (req as any).user?.id,
      });
      res.json(saved);
    } catch (error: any) {
      console.error("Error saving rent history entry:", error?.message, error?.code, error?.detail);
      const msg = error?.message || "Failed to save rent history entry";
      res.status(500).json({ error: msg, code: error?.code, detail: error?.detail });
    }
  });

