  // ==================== P&L v2 — Copy monthly inputs from another month ====================
  // Body: { branchId, fromYear, fromMonth, toYear, toMonth, overwrite? }
  // If toYear/toMonth already has data and overwrite=false → 409.
  app.post("/api/pnl/copy-monthly-inputs", isAuthenticated, requirePermission("pnl", "edit"), async (req, res) => {
    try {
      const { branchId, fromYear, fromMonth, toYear, toMonth, overwrite } = req.body || {};
      if (!branchId || !fromYear || !fromMonth || !toYear || !toMonth) {
        return res.status(400).json({ error: "branchId و from/to year+month مطلوبة" });
      }
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بتعديل هذا الفرع" });
      }
      const source = await storage.getPnlMonthlyInputs(branchId, fromYear, fromMonth);
      if (!source) return res.status(404).json({ error: "لا توجد بيانات في الشهر المصدر" });
      const target = await storage.getPnlMonthlyInputs(branchId, toYear, toMonth);
      if (target && !overwrite) {
        return res.status(409).json({ error: "يوجد بيانات بالفعل في الشهر الهدف", existing: true });
      }
      const { id, createdAt, updatedAt, year, month, ...rest } = source as any;
      // منع ازدواج الحساب عند النسخ: نُصفّر الحقول التي تأتي من المصاريف المتكررة.
      const saved = await storage.upsertPnlMonthlyInputs({
        ...rest,
        subscriptionsCost: 0,
        insuranceCost: 0,
        branchId,
        year: toYear,
        month: toMonth,
        createdBy: (req as any).user?.id,
      });
      res.json(saved);
    } catch (error) {
      console.error("Error copying monthly inputs:", error);
      res.status(500).json({ error: "Failed to copy monthly inputs" });
    }
  });

  // ==================== P&L v2 — Expense Ledger ====================
  // Lightweight read-only ledger: returns one row per (branch × month) for the
  // requested year (or range) so the dashboard can render a sortable table.
  app.get("/api/pnl/expense-ledger", isAuthenticated, requirePermission("pnl", "view"), async (req, res) => {
    try {
      const { branchId, year } = req.query;
      const yearNum = parseInt(year as string) || new Date().getFullYear();
      const branchFilter = getEffectiveBranchFilter(req, branchId as string | undefined);
      if (!branchFilter.hasAccess) return res.status(403).json({ error: "غير مصرح" });

      let branchIds: string[] = [];
      if (branchFilter.singleBranchId) branchIds = [branchFilter.singleBranchId];
      else if (branchFilter.branchIds) branchIds = branchFilter.branchIds;
      else {
        const all = await storage.getAllBranches();
        branchIds = all.map(b => b.id);
      }
      const branchMap = new Map((await storage.getAllBranches()).map(b => [b.id, b]));

      // Admin-configurable COGS ratio (cached). Fetched once per request.
      const cogsRatio = await storage.getCogsRatio();

      const rows: any[] = [];
      // Batch to respect the DB pool.
      const BATCH = 3;
      for (let i = 0; i < branchIds.length; i += BATCH) {
        const batch = branchIds.slice(i, i + BATCH);
        await Promise.all(batch.map(async (bId) => {
          const branch = branchMap.get(bId);
          if (!branch) return;
          for (let m = 1; m <= 12; m++) {
            const [inputs, rent, recurring] = await Promise.all([
              storage.getPnlMonthlyInputs(bId, yearNum, m),
              storage.getRentForPeriod(bId, yearNum, m),
              storage.getRecurringExpensesForPeriod(bId, yearNum, m),
            ]);
            // Per-month gross sales → net sales → cogs (30% rule).
            // Single SQL call scoped to this month so the ledger remains
            // accurate without depending on monthly_inputs.cogsCost.
            const monthStart = new Date(yearNum, m - 1, 1).toISOString().slice(0, 10);
            const monthEnd = new Date(yearNum, m, 0).toISOString().slice(0, 10);
            const { journals: monthJournals } = await storage.getCashierJournalsFiltered({
              branchId: bId,
              startDate: monthStart,
              endDate: monthEnd,
              status: 'approved',
            } as any);
            const grossSales = (monthJournals || []).reduce((s: number, j: any) => s + (j.totalSales || 0), 0);
            const netSales = grossSales / 1.15;
            const cogs = Math.round(netSales * cogsRatio);

            if (!inputs && !rent && recurring.length === 0 && grossSales === 0) continue;
            const i2 = inputs || ({} as any);
            const recurringTotal = recurring.reduce((s, r) => s + (r.monthlyAmount || 0), 0);
            const utilities = (i2.electricityCost || 0) + (i2.waterCost || 0) + (i2.utilitiesOther || 0);
            const general = (i2.internetCost || 0) + (i2.governmentFees || 0)
              + (i2.insuranceCost || 0) + (i2.subscriptionsCost || 0)
              + (i2.securityCost || 0) + (i2.bankFees || 0) + (i2.fuelCost || 0);
            const operating = (i2.maintenanceCost || 0) + (i2.marketingCost || 0)
              + (i2.suppliesCost || 0) + (i2.otherCosts || 0);
            rows.push({
              branchId: bId,
              branchName: branch.name,
              year: yearNum,
              month: m,
              rent,
              cogs,
              utilities,
              general,
              operating,
              recurring: recurringTotal,
              total: cogs + rent + utilities + general + operating + recurringTotal,
              hasInputs: !!inputs,
            });
          }
        }));
      }
      res.json(rows);
    } catch (error) {
      console.error("Error building expense ledger:", error);
      res.status(500).json({ error: "Failed to build expense ledger" });
    }
  });

  // ==================== Branch Daily Closures Module ====================

  // Get all branch daily closures
  app.get("/api/branch-daily-closures", isAuthenticated, requirePermission("daily_closures", "view"), async (req, res) => {
    try {
      const { branchId, startDate, endDate, status, page, limit: limitParam, search, discrepancy } = req.query;
      
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      // SECURITY: Pagination to prevent DoS from large result sets
      const pageNum = Math.max(1, parseInt(page as string, 10) || 1);
      const pageSize = Math.min(100, Math.max(1, parseInt(limitParam as string, 10) || 25));
      const offset = (pageNum - 1) * pageSize;
      
      let conditions: SQL[] = [];
      if (branchFilter.singleBranchId) {
        conditions.push(eq(branchDailyClosures.branchId, branchFilter.singleBranchId));
      } else if (branchFilter.branchIds) {
        conditions.push(inArray(branchDailyClosures.branchId, branchFilter.branchIds));
      }
      if (status && status !== 'all') {
        conditions.push(eq(branchDailyClosures.status, status as string));
      }
      if (startDate && typeof startDate === 'string') {
        conditions.push(gte(branchDailyClosures.closureDate, startDate));
      }
      if (endDate && typeof endDate === 'string') {
        conditions.push(lte(branchDailyClosures.closureDate, endDate));
      }
      if (discrepancy && discrepancy !== 'all') {
        conditions.push(eq(branchDailyClosures.cashDiscrepancyStatus, discrepancy as string));
      }
      if (search && typeof search === 'string' && search.trim()) {
        const term = search.trim();
        conditions.push(
          or(
            sql`${branchDailyClosures.closureDate}::text ILIKE ${'%' + term + '%'}`,
            sql`${branchDailyClosures.branchId} IN (SELECT id FROM branches WHERE name ILIKE ${'%' + term + '%'})`,
          )!
        );
      }
      
      const whereClause = conditions.length > 0 ? and(...conditions) : undefined;
      
      const [countResult] = await db.select({ count: sql<number>`count(*)::int` })
        .from(branchDailyClosures)
        .where(whereClause);
      
      const totalCount = countResult?.count || 0;
      
      const closures = await db.select()
        .from(branchDailyClosures)
        .where(whereClause)
        .orderBy(desc(branchDailyClosures.closureDate), desc(branchDailyClosures.createdAt))
        .limit(pageSize)
        .offset(offset);
      
      const allFiltered = await db.select({
        totalSales: sql<number>`COALESCE(SUM(${branchDailyClosures.totalSales}), 0)::numeric`,
        cashTotal: sql<number>`COALESCE(SUM(${branchDailyClosures.cashTotal}), 0)::numeric`,
        networkTotal: sql<number>`COALESCE(SUM(${branchDailyClosures.networkTotal}), 0)::numeric`,
        totalCashDiscrepancy: sql<number>`COALESCE(SUM(${branchDailyClosures.totalCashDiscrepancy}), 0)::numeric`,
        totalBankDiscrepancy: sql<number>`COALESCE(SUM(${branchDailyClosures.totalBankDiscrepancy}), 0)::numeric`,
        totalCustomerCount: sql<number>`COALESCE(SUM(${branchDailyClosures.totalCustomerCount}), 0)::int`,
        journalsCount: sql<number>`COALESCE(SUM(${branchDailyClosures.journalsCount}), 0)::int`,
      }).from(branchDailyClosures).where(whereClause);
      
      res.json({
        closures,
        pagination: {
          page: pageNum,
          limit: pageSize,
          total: totalCount,
          totalPages: Math.ceil(totalCount / pageSize),
        },
        totals: allFiltered[0] || {
          totalSales: 0, cashTotal: 0, networkTotal: 0,
          totalCashDiscrepancy: 0, totalBankDiscrepancy: 0,
          totalCustomerCount: 0, journalsCount: 0,
        },
      });
    } catch (error) {
      console.error("Error fetching branch daily closures:", error);
      res.status(500).json({ error: "Failed to fetch branch daily closures" });
    }
  });

  // Get journals for a specific date and branch (for creating closure)
  // IMPORTANT: This must be defined BEFORE /:id to avoid "journals-preview" being matched as an ID
  app.get("/api/branch-daily-closures/journals-preview", isAuthenticated, requirePermission("daily_closures", "view"), async (req, res) => {
    try {
      const { branchId, date } = req.query;
      
      if (!date) {
        return res.status(400).json({ error: "Date is required" });
      }
      
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      if (!effectiveBranchId) {
        return res.status(400).json({ error: "Branch ID is required" });
      }
      
      // Check if closure already exists for this date/branch
      const [existingClosure] = await db.select()
        .from(branchDailyClosures)
        .where(
          and(
            eq(branchDailyClosures.branchId, effectiveBranchId),
            eq(branchDailyClosures.closureDate, date as string),
          )
        );
      
      // Get all journals for that date and branch
      const journals = await db.select()
        .from(cashierSalesJournals)
        .where(
          and(
            eq(cashierSalesJournals.branchId, effectiveBranchId as string),
            eq(cashierSalesJournals.journalDate, date as string),
          )
        );
      
      // Get payment breakdowns for all journals
      const journalIds = journals.map(j => j.id);
      const paymentBreakdowns = journalIds.length > 0 
        ? await db.select()
            .from(cashierPaymentBreakdowns)
            .where(inArray(cashierPaymentBreakdowns.journalId, journalIds))
        : [];
      
      // Attach payment breakdowns to journals
      const journalsWithPayments = journals.map(journal => ({
        ...journal,
        paymentBreakdowns: paymentBreakdowns.filter(pb => pb.journalId === journal.id),
      }));
      
      // Calculate aggregated totals
      const totals = {
        totalSales: journals.reduce((sum, j) => sum + (j.totalSales || 0), 0),
        cashTotal: journals.reduce((sum, j) => sum + (j.cashTotal || 0), 0),
        networkTotal: journals.reduce((sum, j) => sum + (j.networkTotal || 0), 0),
        deliveryTotal: journals.reduce((sum, j) => sum + (j.deliveryTotal || 0), 0),
        totalOpeningBalance: journals.reduce((sum, j) => sum + (j.openingBalance || 0), 0),
        totalExpectedCash: journals.reduce((sum, j) => {
          const expected = j.expectedCash || ((j.openingBalance || 0) + (j.cashTotal || 0));
          return sum + expected;
        }, 0),
        totalActualCash: journals.reduce((sum, j) => sum + (j.actualCashDrawer || 0), 0),
        totalCustomerCount: journals.reduce((sum, j) => sum + (j.customerCount || 0), 0),
        totalTransactionCount: journals.reduce((sum, j) => sum + (j.transactionCount || 0), 0),
        totalBankPosAmount: journals.reduce((sum, j) => sum + (j.totalBankPosAmount || 0), 0),
        totalBankTerminalAmount: journals.reduce((sum, j) => sum + (j.totalBankTerminalAmount || 0), 0),
        journalsCount: journals.length,
      };
      // Compute totalCashDiscrepancy after totals are set
      (totals as any).totalCashDiscrepancy = totals.totalActualCash - totals.totalExpectedCash;
      
      // Aggregate payment methods (compute bankDiscrepancy dynamically as terminalAmount - posAmount)
      const cardMethods = ['mada', 'visa', 'mastercard', 'amex', 'card_other', 'card', 'apple_pay', 'stc_pay'];
      const paymentMethodTotals: Record<string, {
        totalAmount: number;
        totalPosAmount: number;
        totalTerminalAmount: number;
        totalBankDiscrepancy: number;
        totalTransactionCount: number;
        totalTerminalTransactionCount: number;
      }> = {};
      
      for (const pb of paymentBreakdowns) {
        const method = pb.paymentMethod;
        if (!paymentMethodTotals[method]) {
          paymentMethodTotals[method] = {
            totalAmount: 0,
            totalPosAmount: 0,
            totalTerminalAmount: 0,
            totalBankDiscrepancy: 0,
            totalTransactionCount: 0,
            totalTerminalTransactionCount: 0,
          };
        }
        const posAmt = pb.posAmount || pb.amount || 0;
        const termAmt = pb.terminalAmount || 0;
        paymentMethodTotals[method].totalAmount += pb.amount || 0;
        paymentMethodTotals[method].totalPosAmount += posAmt;
        paymentMethodTotals[method].totalTerminalAmount += termAmt;
        paymentMethodTotals[method].totalBankDiscrepancy += (termAmt - posAmt);
        paymentMethodTotals[method].totalTransactionCount += pb.transactionCount || 0;
        paymentMethodTotals[method].totalTerminalTransactionCount += pb.terminalTransactionCount || 0;
      }
      
      // Compute totalBankDiscrepancy from card methods only (consistent with frontend)
      // If no payment breakdowns exist, fall back to journal-level bank discrepancy totals
      const computedTotalBankDiscrepancy = paymentBreakdowns.length > 0
        ? Object.entries(paymentMethodTotals)
            .filter(([method]) => cardMethods.includes(method))
            .reduce((sum, [, data]) => sum + data.totalBankDiscrepancy, 0)
        : journals.reduce((sum, j) => sum + (j.bankDiscrepancyTotal || 0), 0);
      (totals as any).totalBankDiscrepancy = computedTotalBankDiscrepancy;
      
      res.json({
        existingClosure,
        journals: journalsWithPayments,
        totals,
        paymentMethodTotals,
      });
    } catch (error) {
      console.error("Error fetching journals preview:", error);
      res.status(500).json({ error: "Failed to fetch journals preview" });
    }
  });

  // Get single branch daily closure with details
  app.get("/api/branch-daily-closures/:id", isAuthenticated, requirePermission("daily_closures", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      
      if (isNaN(id)) {
        return res.status(400).json({ error: "معرف غير صالح" });
      }
      
      const [closure] = await db.select()
        .from(branchDailyClosures)
        .where(eq(branchDailyClosures.id, id));
      
      if (!closure) {
        return res.status(404).json({ error: "Closure not found" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        if (!closure.branchId) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الإغلاق" });
        }
        const hasAccess = await canAccessBranch(req, closure.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الإغلاق" });
        }
      }
      
      // Get payment breakdowns
      const payments = await db.select()
        .from(branchDailyClosurePayments)
        .where(eq(branchDailyClosurePayments.closureId, id));
      
      // Get linked journals
      const linkedJournals = await db.select({
        journal: cashierSalesJournals,
      })
        .from(branchDailyClosureJournals)
        .innerJoin(cashierSalesJournals, eq(branchDailyClosureJournals.journalId, cashierSalesJournals.id))
        .where(eq(branchDailyClosureJournals.closureId, id));
      
      const journalsList = linkedJournals.map((lj: any) => lj.journal);
      const journalIds = journalsList.map((j: any) => j.id);
      
      const journalPaymentBreakdowns = journalIds.length > 0
        ? await db.select()
            .from(cashierPaymentBreakdowns)
            .where(inArray(cashierPaymentBreakdowns.journalId, journalIds))
        : [];
      
      const detailCardMethods = ['mada', 'visa', 'mastercard', 'amex', 'card_other', 'card', 'apple_pay', 'stc_pay'];
      
      const journalsWithComputedDisc = journalsList.map((j: any) => {
        const jBreakdowns = journalPaymentBreakdowns.filter(pb => pb.journalId === j.id);
        
        if (jBreakdowns.length > 0) {
          const cardBreakdowns = jBreakdowns.filter(pb => detailCardMethods.includes(pb.paymentMethod));
          const computedTerminalTotal = cardBreakdowns.reduce((sum, pb) => sum + (pb.terminalAmount || 0), 0);
          const computedPosTotal = cardBreakdowns.reduce((sum, pb) => sum + (pb.posAmount || pb.amount || 0), 0);
          const computedBankDisc = computedTerminalTotal - computedPosTotal;
          
          return {
            ...j,
            computedBankDiscrepancy: computedBankDisc,
            computedBankTerminalTotal: computedTerminalTotal,
            computedBankPosTotal: computedPosTotal,
          };
        }
        
        return {
          ...j,
          computedBankDiscrepancy: j.bankDiscrepancyTotal || 0,
          computedBankTerminalTotal: j.totalBankTerminalAmount || 0,
          computedBankPosTotal: j.totalBankPosAmount || 0,
        };
      });
      
      res.json({
        ...closure,
        payments,
        journals: journalsWithComputedDisc,
      });
    } catch (error) {
      console.error("Error fetching branch daily closure:", error);
      res.status(500).json({ error: "Failed to fetch branch daily closure" });
    }
  });

  // Create branch daily closure
  app.post("/api/branch-daily-closures", isAuthenticated, requirePermission("daily_closures", "create"), async (req, res) => {
      const user = getCurrentUser(req);
      const { branchId, closureDate, journalIds, notes } = req.body;
      
      if (!branchId || !closureDate || !journalIds || journalIds.length === 0) {
        return res.status(400).json({ error: "Branch ID, date, and journal IDs are required" });
      }
      
      // SECURITY: Validate and sanitize notes field
      if (notes !== undefined && notes !== null) {
        if (typeof notes !== 'string' || notes.length > 1000) {
          return res.status(400).json({ error: "الملاحظات غير صالحة أو تتجاوز الحد المسموح" });
        }
      }
      
      // SECURITY: Validate date format and prevent future dates
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      if (!dateRegex.test(closureDate)) {
        return res.status(400).json({ error: "تنسيق التاريخ غير صالح" });
      }
      const closureDateObj = new Date(closureDate + 'T00:00:00');
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (closureDateObj > today) {
        return res.status(400).json({ error: "لا يمكن إنشاء إغلاق لتاريخ مستقبلي" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
        }
      }
      
      // SECURITY: Validate journalIds are integers and limit array size
      if (!Array.isArray(journalIds) || journalIds.some((id: any) => typeof id !== 'number' || isNaN(id))) {
        return res.status(400).json({ error: "معرفات اليوميات غير صالحة" });
      }
      if (journalIds.length > 50) {
        return res.status(400).json({ error: "عدد اليوميات يتجاوز الحد المسموح" });
      }
      
      // Pre-check existence/ownership outside tx (cheap; final checks happen inside tx under lock).
      const preJournals = await db.select()
        .from(cashierSalesJournals)
        .where(inArray(cashierSalesJournals.id, journalIds));
      if (preJournals.length !== journalIds.length) {
        return res.status(400).json({ error: "بعض اليوميات المحددة غير موجودة" });
      }
      const preInvalid = preJournals.filter(j => j.branchId !== branchId || j.journalDate !== closureDate);
      if (preInvalid.length > 0) {
        return res.status(403).json({ error: "بعض اليوميات لا تنتمي لهذا الفرع أو التاريخ المحدد" });
      }

    try {
      // SNAPSHOT-SAFE: all reads + computation + inserts happen in one tx with row locks
      // on the selected journals (FOR UPDATE) so no concurrent edit/post/unpost can race
      // and make the closure snapshot drift.
      const newClosure = await db.transaction(async (tx) => {
        // Lock the selected journal rows; concurrent PATCH/DELETE/UNPOST will queue behind us.
        const lockedRows = await tx.execute(
          sql`SELECT * FROM ${cashierSalesJournals} WHERE id IN (${sql.join(journalIds.map((id: number) => sql`${id}`), sql`, `)}) FOR UPDATE`
        );
        const journals: any[] = (lockedRows as any).rows ?? (Array.isArray(lockedRows) ? lockedRows as any : []);
        if (journals.length !== journalIds.length) {
          throw new Error("__JOURNALS_MISSING__");
        }
        const invalid = journals.filter(j => j.branch_id !== branchId || j.journal_date !== closureDate);
        if (invalid.length > 0) throw new Error("__JOURNALS_WRONG_SCOPE__");
        // Re-check links inside tx
        const linksInTx = await tx.select()
          .from(branchDailyClosureJournals)
          .where(inArray(branchDailyClosureJournals.journalId, journalIds));
        if (linksInTx.length > 0) throw new Error("__JOURNALS_ALREADY_LINKED__");
        // Re-check no closure exists for branch+date
        const [existingClosureTx] = await tx.select()
          .from(branchDailyClosures)
          .where(and(eq(branchDailyClosures.branchId, branchId), eq(branchDailyClosures.closureDate, closureDate)));
        if (existingClosureTx) throw new Error("__CLOSURE_EXISTS__");
        // Read breakdowns + recompute totals INSIDE the tx using the locked snapshot
        const paymentBreakdowns = await tx.select()
          .from(cashierPaymentBreakdowns)
          .where(inArray(cashierPaymentBreakdowns.journalId, journalIds));
        // Map snake_case row → expected camelCase fields used below
        const journalsNorm = journals.map((j: any) => ({
          id: j.id,
          branchId: j.branch_id,
          journalDate: j.journal_date,
          totalSales: Number(j.total_sales) || 0,
          cashTotal: Number(j.cash_total) || 0,
          networkTotal: Number(j.network_total) || 0,
          deliveryTotal: Number(j.delivery_total) || 0,
          openingBalance: Number(j.opening_balance) || 0,
          expectedCash: j.expected_cash != null ? Number(j.expected_cash) : null,
          actualCashDrawer: Number(j.actual_cash_drawer) || 0,
          totalBankPosAmount: Number(j.total_bank_pos_amount) || 0,
          totalBankTerminalAmount: Number(j.total_bank_terminal_amount) || 0,
          bankDiscrepancyTotal: Number(j.bank_discrepancy_total) || 0,
          customerCount: Number(j.customer_count) || 0,
          transactionCount: Number(j.transaction_count) || 0,
        }));
        const totalSalesTx = journalsNorm.reduce((s, j) => s + j.totalSales, 0);
        const cashTotalTx = journalsNorm.reduce((s, j) => s + j.cashTotal, 0);
        const networkTotalTx = journalsNorm.reduce((s, j) => s + j.networkTotal, 0);
        const deliveryTotalTx = journalsNorm.reduce((s, j) => s + j.deliveryTotal, 0);
        const totalExpectedCashTx = journalsNorm.reduce((s, j) => s + ((j.expectedCash ?? (j.openingBalance + j.cashTotal))), 0);
        const totalActualCashTx = journalsNorm.reduce((s, j) => s + j.actualCashDrawer, 0);
        const totalCashDiscrepancyTx = totalActualCashTx - totalExpectedCashTx;
        const cashDiscrepancyStatusTx = totalCashDiscrepancyTx > 0.5 ? 'surplus' : totalCashDiscrepancyTx < -0.5 ? 'shortage' : 'balanced';
        const pmTotals: Record<string, any> = {};
        for (const pb of paymentBreakdowns) {
          const m = pb.paymentMethod;
          if (!pmTotals[m]) pmTotals[m] = { totalAmount: 0, totalPosAmount: 0, totalTerminalAmount: 0, totalBankDiscrepancy: 0, totalTransactionCount: 0, totalTerminalTransactionCount: 0 };
          const posAmt = pb.posAmount || pb.amount || 0;
          const termAmt = pb.terminalAmount || 0;
          pmTotals[m].totalAmount += pb.amount || 0;
          pmTotals[m].totalPosAmount += posAmt;
          pmTotals[m].totalTerminalAmount += termAmt;
          pmTotals[m].totalBankDiscrepancy += (termAmt - posAmt);
          pmTotals[m].totalTransactionCount += pb.transactionCount || 0;
          pmTotals[m].totalTerminalTransactionCount += pb.terminalTransactionCount || 0;
        }
        const closureCardMethodsTx = ['mada','visa','mastercard','amex','card_other','card','apple_pay','stc_pay'];
        const totalBankDiscrepancyTx = paymentBreakdowns.length > 0
          ? Object.entries(pmTotals).filter(([m]) => closureCardMethodsTx.includes(m)).reduce((s, [, d]) => s + (d as any).totalBankDiscrepancy, 0)
          : journalsNorm.reduce((s, j) => s + j.bankDiscrepancyTotal, 0);
        const bankDiscrepancyStatusTx = totalBankDiscrepancyTx > 0.5 ? 'surplus' : totalBankDiscrepancyTx < -0.5 ? 'shortage' : 'balanced';
        const totalCustomerCountTx = journalsNorm.reduce((s, j) => s + j.customerCount, 0);

        const [closure] = await tx.insert(branchDailyClosures).values({
          branchId,
          closureDate,
          totalSales: totalSalesTx,
          cashTotal: cashTotalTx,
          networkTotal: networkTotalTx,
          deliveryTotal: deliveryTotalTx,
          totalOpeningBalance: journalsNorm.reduce((s, j) => s + j.openingBalance, 0),
          totalExpectedCash: totalExpectedCashTx,
          totalActualCash: totalActualCashTx,
          totalCashDiscrepancy: totalCashDiscrepancyTx,
          cashDiscrepancyStatus: cashDiscrepancyStatusTx,
          totalBankPosAmount: journalsNorm.reduce((s, j) => s + j.totalBankPosAmount, 0),
          totalBankTerminalAmount: journalsNorm.reduce((s, j) => s + j.totalBankTerminalAmount, 0),
          totalBankDiscrepancy: totalBankDiscrepancyTx,
          bankDiscrepancyStatus: bankDiscrepancyStatusTx,
          totalCustomerCount: totalCustomerCountTx,
          totalTransactionCount: journalsNorm.reduce((s, j) => s + j.transactionCount, 0),
          averageTicket: totalSalesTx / Math.max(totalCustomerCountTx, 1),
          journalsCount: journalsNorm.length,
          status: 'open',
          notes,
          createdBy: user.id,
        }).returning();

        for (const journalId of journalIds) {
          await tx.insert(branchDailyClosureJournals).values({ closureId: closure.id, journalId });
        }
        for (const [method, totals] of Object.entries(pmTotals)) {
          const t = totals as any;
          const discType = t.totalBankDiscrepancy > 0.5 ? 'surplus' : t.totalBankDiscrepancy < -0.5 ? 'shortage' : 'balanced';
          await tx.insert(branchDailyClosurePayments).values({
            closureId: closure.id,
            paymentMethod: method,
            totalAmount: t.totalAmount,
            totalPosAmount: t.totalPosAmount,
            totalTerminalAmount: t.totalTerminalAmount,
            totalBankDiscrepancy: t.totalBankDiscrepancy,
            bankDiscrepancyType: discType,
            totalTransactionCount: t.totalTransactionCount,
            totalTerminalTransactionCount: t.totalTerminalTransactionCount,
          });
        }
        return closure;
      });
      res.json(newClosure);
      return;
    } catch (txErr: any) {
      const msg = txErr?.message || '';
      if (msg === "__JOURNALS_MISSING__") return res.status(400).json({ error: "بعض اليوميات المحددة غير موجودة" });
      if (msg === "__JOURNALS_WRONG_SCOPE__") return res.status(403).json({ error: "بعض اليوميات لا تنتمي لهذا الفرع أو التاريخ المحدد" });
      if (msg === "__JOURNALS_ALREADY_LINKED__") return res.status(409).json({ error: "بعض اليوميات مرتبطة بإغلاق يومي آخر بالفعل" });
      if (msg === "__CLOSURE_EXISTS__") return res.status(409).json({ error: "يوجد إغلاق يومي لهذا التاريخ بالفعل" });
      if (txErr?.code === '23505') return res.status(409).json({ error: "تعارض أثناء إنشاء الإغلاق اليومي. أعد المحاولة." });
      console.error("Error creating branch daily closure (tx):", txErr);
      return res.status(500).json({ error: "فشل في إنشاء الإغلاق اليومي" });
    }
  });

  // Close (finalize) branch daily closure
  app.post("/api/branch-daily-closures/:id/close", isAuthenticated, requirePermission("daily_closures", "approve"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      
      if (isNaN(id)) {
        return res.status(400).json({ error: "معرف غير صالح" });
      }
      
      const user = getCurrentUser(req);
      
      const [closure] = await db.select()
        .from(branchDailyClosures)
        .where(eq(branchDailyClosures.id, id));
      
      if (!closure) {
        return res.status(404).json({ error: "Closure not found" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, closure.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
        }
      }
      
      if (closure.status === 'closed') {
        return res.status(400).json({ error: "اليومية مغلقة بالفعل" });
      }
      
      // SECURITY: Separation of duties - creator cannot approve their own closure
      if (closure.createdBy === user.id && !isUserAdmin(req)) {
        return res.status(403).json({ error: "لا يمكن اعتماد إغلاق قمت بإنشائه بنفسك" });
      }
      
      // SECURITY: Atomic update with status check to prevent TOCTOU race condition
      const [updated] = await db.update(branchDailyClosures)
        .set({
          status: 'closed',
          closedBy: user.id,
          closedAt: new Date(),
          updatedAt: new Date(),
        })
        .where(and(eq(branchDailyClosures.id, id), eq(branchDailyClosures.status, 'open')))
        .returning();
      
      if (!updated) {
        return res.status(409).json({ error: "تم إغلاق هذا البيان من قبل مستخدم آخر" });
      }
      
      res.json(updated);
    } catch (error) {
      console.error("Error closing branch daily closure:", error);
      res.status(500).json({ error: "Failed to close branch daily closure" });
    }
  });

  // Delete branch daily closure (only if open, admin only)
  app.delete("/api/branch-daily-closures/:id", isAuthenticated, requirePermission("daily_closures", "delete"), async (req, res) => {
    try {
      // SECURITY: Only admins can delete closures
      if (!isUserAdmin(req)) {
        return res.status(403).json({ error: "غير مصرح - الحذف متاح للمدير العام فقط" });
      }
      
      const id = parseInt(req.params.id, 10);
      
      if (isNaN(id)) {
        return res.status(400).json({ error: "معرف غير صالح" });
      }
      
      const [closure] = await db.select()
        .from(branchDailyClosures)
        .where(eq(branchDailyClosures.id, id));
      
      if (!closure) {
        return res.status(404).json({ error: "Closure not found" });
      }
      
      if (closure.status === 'closed') {
        return res.status(400).json({ error: "لا يمكن حذف يومية مغلقة" });
      }
      
      await db.delete(branchDailyClosures)
        .where(eq(branchDailyClosures.id, id));
      
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting branch daily closure:", error);
      res.status(500).json({ error: "Failed to delete branch daily closure" });
    }
  });

  // ==================== End Branch Daily Closures Module ====================

  // Comprehensive Operations Reports Dashboard
  app.get("/api/operations/reports", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const { branchId, startDate, endDate } = req.query;
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const report = await storage.getOperationsReport({
        branchId: branchFilter.singleBranchId || undefined,
        branchIds: branchFilter.branchIds || undefined,
        startDate: startDate as string | undefined,
        endDate: endDate as string | undefined,
      });
      
      res.json(report);
    } catch (error) {
      console.error("Error fetching operations reports:", error);
      res.status(500).json({ error: "Failed to fetch operations reports" });
    }
  });

  // ============================================================
  // CONSOLIDATED Operations Reports Bundle - Single API call replaces 10+ individual calls
  // ============================================================
  app.get("/api/operations/reports-bundle", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const { branchId, startDate, endDate, sections, cashierId, status, discrepancyStatus } = req.query;
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }

      const requestedSections = sections ? (sections as string).split(",") : ["report", "cashierJournals", "cashiers"];
      const effectiveBranchId = branchFilter.singleBranchId;
      const result: Record<string, any> = {};

      const needsJournals = requestedSections.includes("cashierJournals") || requestedSections.includes("paymentBreakdowns");
      const canViewAll = needsJournals || requestedSections.includes("cashiers") ? await canUserViewAllCashiers(req) : true;
      const currentUser = !canViewAll ? getCurrentUser(req) : null;

      let sharedJournals: any[] | null = null;
      const getFilteredJournals = async () => {
        if (sharedJournals !== null) return sharedJournals;
        const dbFilters: any = {};
        if (effectiveBranchId) {
          dbFilters.branchId = effectiveBranchId;
        } else if (branchFilter.branchIds) {
          dbFilters.branchIds = branchFilter.branchIds;
        }
        if (startDate && typeof startDate === 'string') dbFilters.startDate = startDate;
        if (endDate && typeof endDate === 'string') dbFilters.endDate = endDate;
        // Non-privileged users are pinned to their own cashier id; managers
        // may pass an explicit cashierId filter.
        if (!canViewAll && currentUser) {
          dbFilters.cashierId = String(currentUser.id);
        } else if (cashierId && typeof cashierId === 'string') {
          dbFilters.cashierId = cashierId;
        }
        if (status && typeof status === 'string') dbFilters.status = status;
        if (discrepancyStatus && typeof discrepancyStatus === 'string') dbFilters.discrepancyStatus = discrepancyStatus;
        const { journals } = await storage.getCashierJournalsFiltered(dbFilters);
        sharedJournals = journals;
        return journals;
      };

      const promises: Promise<void>[] = [];

      if (requestedSections.includes("report")) {
        promises.push(
          storage.getOperationsReport({
            branchId: effectiveBranchId || undefined,
            branchIds: branchFilter.branchIds || undefined,
            startDate: startDate as string | undefined,
            endDate: endDate as string | undefined,
          }).then(r => { result.report = r; })
        );
      }

      if (requestedSections.includes("cashierJournals")) {
        promises.push(
          getFilteredJournals().then(journals => { result.cashierJournals = journals; })
        );
      }

      if (requestedSections.includes("cashiers")) {
        promises.push(
          (async () => {
            if (!canViewAll && currentUser) {
              result.cashiers = [{ id: currentUser.id, username: currentUser.username, firstName: currentUser.firstName || null, lastName: currentUser.lastName || null }];
              return;
            }
            result.cashiers = await storage.getUsersByBranch(effectiveBranchId || undefined, branchFilter.branchIds || undefined);
          })()
        );
      }

      if (requestedSections.includes("paymentBreakdowns")) {
        promises.push(
          (async () => {
            const journals = await getFilteredJournals();
            const journalIds = journals.map((j: any) => j.id);
            if (journalIds.length === 0) {
              result.paymentBreakdowns = [];
              return;
            }
            const journalMap = new Map(journals.map((j: any) => [j.id, j]));
            const allBreakdowns = await storage.getPaymentBreakdownsByJournalIds(journalIds);
            result.paymentBreakdowns = allBreakdowns.map((b: any) => {
              const journal = journalMap.get(b.journalId);
              return { ...b, branchId: journal?.branchId, journalDate: journal?.journalDate };
            });
          })()
        );
      }

      await Promise.all(promises);
      res.json(result);
    } catch (error) {
      console.error("Error fetching operations reports bundle:", error);
      res.status(500).json({ error: "Failed to fetch operations reports bundle" });
    }
  });

  // Branch Overview Report - Asset Readiness, Inventory, Maintenance
  app.get("/api/reports/branch-overview", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const { branchId } = req.query;
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      const allBranches = await storage.getAllBranches();
      // Filter branches list based on access
      const branches = branchFilter.branchIds 
        ? allBranches.filter(b => branchFilter.branchIds!.includes(b.id))
        : allBranches;
      const allItems = effectiveBranchId 
        ? await storage.getInventoryItemsByBranch(effectiveBranchId)
        : await storage.getAllInventoryItems();
      
      const branchOverviews = [];
      const branchList = effectiveBranchId 
        ? branches.filter(b => b.id === effectiveBranchId)
        : branches;

      for (const branch of branchList) {
        const branchItems = allItems.filter(item => item.branchId === branch.id);
        
        const goodItems = branchItems.filter(i => i.status === 'good').length;
        const maintenanceItems = branchItems.filter(i => i.status === 'maintenance').length;
        const damagedItems = branchItems.filter(i => i.status === 'damaged').length;
        const missingItems = branchItems.filter(i => i.status === 'missing').length;
        const totalItems = branchItems.length;
        
        const assetReadinessPercent = totalItems > 0 ? (goodItems / totalItems) * 100 : 100;
        
        const now = new Date();
        const overdueInspection = branchItems.filter(i => {
          if (!i.nextInspectionDate) return false;
          return new Date(i.nextInspectionDate) < now;
        }).length;
        
        const upcomingInspection = branchItems.filter(i => {
          if (!i.nextInspectionDate) return false;
          const inspDate = new Date(i.nextInspectionDate);
          const weekFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
          return inspDate >= now && inspDate <= weekFromNow;
        }).length;
        
        const lowQuantityItems = branchItems.filter(i => i.quantity <= 5).length;
        const totalQuantity = branchItems.reduce((sum, i) => sum + i.quantity, 0);
        const totalValue = branchItems.reduce((sum, i) => sum + ((i.price || 0) * i.quantity), 0);
        
        const categoryBreakdown: Record<string, { count: number; value: number }> = {};
        for (const item of branchItems) {
          const cat = item.category || 'غير مصنف';
          if (!categoryBreakdown[cat]) {
            categoryBreakdown[cat] = { count: 0, value: 0 };
          }
          categoryBreakdown[cat].count += item.quantity;
          categoryBreakdown[cat].value += (item.price || 0) * item.quantity;
        }

        branchOverviews.push({
          branchId: branch.id,
          branchName: branch.name,
          assetReadiness: {
            total: totalItems,
            good: goodItems,
            maintenance: maintenanceItems,
            damaged: damagedItems,
            missing: missingItems,
            readinessPercent: assetReadinessPercent,
          },
          inventory: {
            totalItems,
            totalQuantity,
            totalValue,
            lowQuantityItems,
            categoryBreakdown: Object.entries(categoryBreakdown).map(([category, data]) => ({
              category,
              count: data.count,
              value: data.value,
            })),
          },
          maintenance: {
            itemsNeedingMaintenance: maintenanceItems + damagedItems,
            overdueInspection,
            upcomingInspection,
          },
          operationalStatus: assetReadinessPercent >= 90 ? 'excellent' : assetReadinessPercent >= 75 ? 'good' : assetReadinessPercent >= 50 ? 'needs_attention' : 'critical',
        });
      }

      const summary = {
        totalBranches: branchOverviews.length,
        totalAssets: branchOverviews.reduce((sum, b) => sum + b.assetReadiness.total, 0),
        totalGoodAssets: branchOverviews.reduce((sum, b) => sum + b.assetReadiness.good, 0),
        totalMaintenanceNeeded: branchOverviews.reduce((sum, b) => sum + b.maintenance.itemsNeedingMaintenance, 0),
        totalOverdueInspection: branchOverviews.reduce((sum, b) => sum + b.maintenance.overdueInspection, 0),
        totalInventoryValue: branchOverviews.reduce((sum, b) => sum + b.inventory.totalValue, 0),
        overallReadinessPercent: branchOverviews.length > 0 
          ? branchOverviews.reduce((sum, b) => sum + b.assetReadiness.readinessPercent, 0) / branchOverviews.length 
          : 100,
        branchesExcellent: branchOverviews.filter(b => b.operationalStatus === 'excellent').length,
        branchesGood: branchOverviews.filter(b => b.operationalStatus === 'good').length,
        branchesNeedAttention: branchOverviews.filter(b => b.operationalStatus === 'needs_attention').length,
        branchesCritical: branchOverviews.filter(b => b.operationalStatus === 'critical').length,
      };

      res.json({ summary, branches: branchOverviews });
    } catch (error) {
      console.error("Error fetching branch overview report:", error);
      res.status(500).json({ error: "Failed to fetch branch overview report" });
    }
  });

  // Executive Summary Report - Comprehensive data for PDF/Excel export
  app.get("/api/reports/executive-summary", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const { startDate, endDate, branchId, cashierId, status, discrepancyStatus } = req.query;
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      const allBranches = await storage.getAllBranches();
      const branches = branchFilter.branchIds 
        ? allBranches.filter(b => branchFilter.branchIds!.includes(b.id))
        : allBranches;
      
      const operationsReport = await storage.getOperationsReport({
        branchId: branchFilter.singleBranchId || undefined,
        branchIds: branchFilter.branchIds || undefined,
        startDate: startDate as string | undefined,
        endDate: endDate as string | undefined,
      });
      
      const allItemsRaw = effectiveBranchId 
        ? await storage.getInventoryItemsByBranch(effectiveBranchId)
        : await storage.getAllInventoryItems();
      const allItems = branchFilter.branchIds && !effectiveBranchId
        ? allItemsRaw.filter(i => branchFilter.branchIds!.includes(i.branchId))
        : allItemsRaw;
      const dashJournalFilters: any = {};
      if (effectiveBranchId) {
        dashJournalFilters.branchId = effectiveBranchId;
      } else if (branchFilter.branchIds) {
        dashJournalFilters.branchIds = branchFilter.branchIds;
      }
      if (startDate) dashJournalFilters.startDate = startDate as string;
      if (endDate) dashJournalFilters.endDate = endDate as string;
      // Honor optional cashier/status/discrepancy filters for the executive
      // KPIs so the user sees numbers consistent with their dashboard filters.
      if (cashierId && typeof cashierId === 'string') dashJournalFilters.cashierId = cashierId;
      if (status && typeof status === 'string') dashJournalFilters.status = status;
      if (discrepancyStatus && typeof discrepancyStatus === 'string') dashJournalFilters.discrepancyStatus = discrepancyStatus;
      const { journals: filteredJournals } = await storage.getCashierJournalsFiltered(dashJournalFilters);

      const goodItems = allItems.filter(i => i.status === 'good').length;
      const maintenanceItems = allItems.filter(i => i.status === 'maintenance' || i.status === 'damaged').length;
      const totalInventoryValue = allItems.reduce((sum, i) => sum + ((i.price || 0) * i.quantity), 0);
      const assetReadinessPercent = allItems.length > 0 ? (goodItems / allItems.length) * 100 : 100;

      const now = new Date();
      const currentYearMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
      // PERF: scope target computation to allowed branches to skip unnecessary work.
      const scopedTargetBranchIds = effectiveBranchId
        ? [effectiveBranchId]
        : (branchFilter.branchIds || undefined);
      const targetsProgress = await storage.getAllBranchesSalesProgress(currentYearMonth, scopedTargetBranchIds);
      const totalTarget = targetsProgress.reduce((sum, b) => sum + (b.targetAmount || 0), 0);
      const totalAchieved = targetsProgress.reduce((sum, b) => sum + (b.achievedAmount || 0), 0);
      const targetAchievementPercent = totalTarget > 0 ? (totalAchieved / totalTarget) * 100 : 0;

      const executiveSummary = {
        reportDate: new Date().toISOString(),
        period: { startDate: startDate || 'N/A', endDate: endDate || 'N/A' },
        
        salesOverview: {
          totalSales: operationsReport.salesReport.totalSales,
          cashSales: operationsReport.salesReport.cashSales,
          networkSales: operationsReport.salesReport.networkSales,
          deliverySales: operationsReport.salesReport.deliverySales,
          totalTransactions: operationsReport.salesReport.totalTransactions,
          averageTicket: operationsReport.salesReport.averageTicket,
          discrepancies: {
            shortages: operationsReport.salesReport.totalShortages,
            shortageAmount: operationsReport.salesReport.shortageAmount,
            surpluses: operationsReport.salesReport.totalSurpluses,
            surplusAmount: operationsReport.salesReport.surplusAmount,
          },
        },

        productionOverview: {
          totalOrders: operationsReport.productionReport.totalOrders,
          completedOrders: operationsReport.productionReport.completedOrders,
          pendingOrders: operationsReport.productionReport.pendingOrders,
          inProgressOrders: operationsReport.productionReport.inProgressOrders,
          totalQuantityProduced: operationsReport.productionReport.totalQuantityProduced,
          qualityPassRate: operationsReport.productionReport.qualityPassRate,
        },

        assetsOverview: {
          totalAssets: allItems.length,
          goodAssets: goodItems,
          maintenanceNeeded: maintenanceItems,
          assetReadinessPercent,
          totalInventoryValue,
        },

        targetsOverview: {
          totalTarget,
          totalAchieved,
          achievementPercent: targetAchievementPercent,
          branchesAboveTarget: targetsProgress.filter(b => b.achievementPercent >= 100).length,
          branchesBelowTarget: targetsProgress.filter(b => b.achievementPercent < 80).length,
        },

        branchPerformance: operationsReport.branchComparison.map(b => ({
          branchId: b.branchId,
          branchName: b.branchName,
          totalSales: b.totalSales,
          totalOrders: b.totalOrders,
          qualityPassRate: b.qualityPassRate,
          averageTicket: b.averageTicket,
        })),

        shiftsOverview: {
          totalShifts: operationsReport.shiftsReport.totalShifts,
          totalEmployeeAssignments: operationsReport.shiftsReport.totalEmployeeAssignments,
        },

        keyMetrics: {
          totalBranches: branches.length,
          activeCashiers: new Set(filteredJournals.map(j => j.cashierId)).size,
          averageDailySales: operationsReport.salesReport.dailySales.length > 0 
            ? operationsReport.salesReport.totalSales / operationsReport.salesReport.dailySales.length 
            : 0,
        },
      };

      res.json(executiveSummary);
    } catch (error) {
      console.error("Error fetching executive summary:", error);
      res.status(500).json({ error: "Failed to fetch executive summary" });
    }
  });

  // Payment Method Mismatch Analysis Report - تحليل فروقات طرق الدفع بين POS والتيرمنال
  app.get("/api/reports/payment-mismatch-analysis", isAuthenticated, requirePermission("cashier_journal", "view"), async (req, res) => {
    try {
      const { branchId, startDate, endDate, cashierId, status, discrepancyStatus } = req.query;
      
      // SECURITY: Apply mandatory branch filter for non-admins
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      // Get cashier journals for the date range
      const conditions: SQL[] = [];
      if (branchFilter.singleBranchId) {
        conditions.push(eq(cashierSalesJournals.branchId, branchFilter.singleBranchId));
      } else if (branchFilter.branchIds) {
        conditions.push(inArray(cashierSalesJournals.branchId, branchFilter.branchIds));
      }
      if (startDate) {
        conditions.push(gte(cashierSalesJournals.journalDate, startDate as string));
      }
      if (endDate) {
        conditions.push(lte(cashierSalesJournals.journalDate, endDate as string));
      }
      if (status && typeof status === 'string') {
        conditions.push(eq(cashierSalesJournals.status, status));
      }
      if (discrepancyStatus && typeof discrepancyStatus === 'string') {
        conditions.push(eq(cashierSalesJournals.discrepancyStatus, discrepancyStatus));
      }
      
      let journals = await db.select()
        .from(cashierSalesJournals)
        .where(conditions.length > 0 ? and(...conditions) : undefined);
      
      // SECURITY: Non-admin/manager users can only see their own mismatch data.
      // Privileged users may pass an explicit cashierId to drill in.
      const canViewAllMismatch = await canUserViewAllCashiers(req);
      if (!canViewAllMismatch) {
        const user = getCurrentUser(req);
        journals = journals.filter(j => String(j.cashierId) === String(user.id));
      } else if (cashierId && typeof cashierId === 'string') {
        journals = journals.filter(j => String(j.cashierId) === cashierId);
      }
      
      if (journals.length === 0) {
        return res.json({
          summary: {
            totalJournals: 0,
            journalsWithMismatch: 0,
            mismatchRate: 0,
            totalMismatchAmount: 0,
            totalPosAmount: 0,
            totalTerminalAmount: 0,
          },
          byCashier: [],
          byBranch: [],
          byPaymentMethod: [],
          detailedMismatches: [],
        });
      }
      
      // Get payment breakdowns for all journals
      const journalIds = journals.map(j => j.id);
      const paymentBreakdowns = await db.select()
        .from(cashierPaymentBreakdowns)
        .where(inArray(cashierPaymentBreakdowns.journalId, journalIds));
      
      // Calculate mismatches
      const journalMismatches: any[] = [];
      const cashierStats: Record<string, { 
        cashierName: string; 
        totalMismatchAmount: number; 
        mismatchCount: number; 
        totalTransactions: number;
        methodErrors: Record<string, number>;
      }> = {};
      const branchStats: Record<string, { 
        branchName: string; 
        totalMismatchAmount: number; 
        mismatchCount: number;
      }> = {};
      const methodStats: Record<string, {
        posTotal: number;
        terminalTotal: number;
        discrepancy: number;
        discrepancyCount: number;
      }> = {};
      
      // Get all branches for name lookup
      const allBranches = await storage.getAllBranches();
      const branchNameMap = Object.fromEntries(allBranches.map(b => [b.id, b.name]));
      
      for (const journal of journals) {
        const journalBreakdowns = paymentBreakdowns.filter(pb => pb.journalId === journal.id);
        const cashierName = journal.cashierName || 'غير محدد';
        const branchName = branchNameMap[journal.branchId] || journal.branchId;
        
        let journalHasMismatch = false;
        let journalMismatchAmount = 0;
        const methodMismatches: any[] = [];
        
        for (const pb of journalBreakdowns) {
          const posAmount = pb.posAmount || 0;
          const terminalAmount = pb.terminalAmount || 0;
          const discrepancy = Math.abs(posAmount - terminalAmount);
          
          // Track method stats
          if (!methodStats[pb.paymentMethod]) {
            methodStats[pb.paymentMethod] = { posTotal: 0, terminalTotal: 0, discrepancy: 0, discrepancyCount: 0 };
          }
          methodStats[pb.paymentMethod].posTotal += posAmount;
          methodStats[pb.paymentMethod].terminalTotal += terminalAmount;
          
          // Consider mismatch if discrepancy > 0.5 SAR (to avoid floating point issues)
          if (discrepancy > 0.5) {
            journalHasMismatch = true;
            journalMismatchAmount += discrepancy;
            methodStats[pb.paymentMethod].discrepancy += discrepancy;
            methodStats[pb.paymentMethod].discrepancyCount++;
            
            methodMismatches.push({
              paymentMethod: pb.paymentMethod,
              posAmount,
              terminalAmount,
              discrepancy,
              discrepancyType: posAmount > terminalAmount ? 'pos_higher' : 'terminal_higher',
            });
          }
        }
        
        // Track cashier stats
        if (!cashierStats[journal.cashierId]) {
          cashierStats[journal.cashierId] = {
            cashierName,
            totalMismatchAmount: 0,
            mismatchCount: 0,
            totalTransactions: 0,
            methodErrors: {},
          };
        }
        cashierStats[journal.cashierId].totalTransactions++;
        
        // Track branch stats
        if (!branchStats[journal.branchId]) {
          branchStats[journal.branchId] = {
            branchName,
            totalMismatchAmount: 0,
            mismatchCount: 0,
          };
        }
        
        if (journalHasMismatch) {
          cashierStats[journal.cashierId].mismatchCount++;
          cashierStats[journal.cashierId].totalMismatchAmount += journalMismatchAmount;
          branchStats[journal.branchId].mismatchCount++;
          branchStats[journal.branchId].totalMismatchAmount += journalMismatchAmount;
          
          // Track method errors per cashier
          for (const mm of methodMismatches) {
            if (!cashierStats[journal.cashierId].methodErrors[mm.paymentMethod]) {
              cashierStats[journal.cashierId].methodErrors[mm.paymentMethod] = 0;
            }
            cashierStats[journal.cashierId].methodErrors[mm.paymentMethod]++;
          }
          
          journalMismatches.push({
            journalId: journal.id,
            journalDate: journal.journalDate,
            branchId: journal.branchId,
            branchName,
            cashierId: journal.cashierId,
            cashierName,
            shiftType: journal.shiftType,
            totalSales: journal.totalSales,
            totalMismatchAmount: journalMismatchAmount,
            methodMismatches,
          });
        }
      }
      
      // Calculate summary
      const totalMismatchAmount = Object.values(cashierStats).reduce((sum, c) => sum + c.totalMismatchAmount, 0);
      const journalsWithMismatch = Object.values(cashierStats).reduce((sum, c) => sum + c.mismatchCount, 0);
      const totalPosAmount = Object.values(methodStats).reduce((sum, m) => sum + m.posTotal, 0);
      const totalTerminalAmount = Object.values(methodStats).reduce((sum, m) => sum + m.terminalTotal, 0);
      
      res.json({
        summary: {
          totalJournals: journals.length,
          journalsWithMismatch,
          mismatchRate: journals.length > 0 ? (journalsWithMismatch / journals.length) * 100 : 0,
          totalMismatchAmount,
          totalPosAmount,
          totalTerminalAmount,
        },
        byCashier: Object.entries(cashierStats)
          .map(([cashierId, stats]) => ({
            cashierId,
            ...stats,
            errorRate: stats.totalTransactions > 0 ? (stats.mismatchCount / stats.totalTransactions) * 100 : 0,
          }))
          .sort((a, b) => b.totalMismatchAmount - a.totalMismatchAmount),
        byBranch: Object.entries(branchStats)
          .map(([branchId, stats]) => ({ branchId, ...stats }))
          .sort((a, b) => b.totalMismatchAmount - a.totalMismatchAmount),
        byPaymentMethod: Object.entries(methodStats)
          .map(([method, stats]) => ({
            paymentMethod: method,
            ...stats,
            discrepancyPercent: stats.terminalTotal > 0 ? (stats.discrepancy / stats.terminalTotal) * 100 : 0,
          }))
          .sort((a, b) => b.discrepancy - a.discrepancy),
        detailedMismatches: journalMismatches.slice(0, 100), // Limit to 100 records
      });
    } catch (error) {
      console.error("Error fetching payment mismatch analysis:", error);
      res.status(500).json({ error: "Failed to fetch payment mismatch analysis" });
    }
  });

