  // Daily Challenges as Targets - تحويل التحديات اليومية إلى أهداف
  app.get("/api/smart-incentives/challenges-as-targets", isAuthenticated, requirePermission("smart_incentives_challenges", "view"), async (req, res) => {
    try {
      const user = getCurrentUser(req);
      let { branchId, date, shiftType } = req.query;
      const branchFilter = getEffectiveBranchFilter(req, branchId as string | undefined);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      }
      if (branchFilter.singleBranchId) branchId = branchFilter.singleBranchId;
      const targetDate = (date as string) || new Date().toISOString().split('T')[0];
      
      console.log("[challenges-as-targets] branchId:", branchId, "targetDate:", targetDate, "shiftType:", shiftType);

      const allChallenges = await storage.getActiveDailyChallenges(branchId as string, targetDate);

      const validChallenges = allChallenges.filter(c => {
        if (c.validFrom > targetDate) return false;
        if (c.validTo && c.validTo < targetDate) return false;
        const cShift = (c.shiftType && c.shiftType !== 'null') ? c.shiftType : null;
        if (shiftType && shiftType !== "all" && cShift && cShift !== shiftType) return false;
        return true;
      });
      console.log("[challenges-as-targets] validChallenges count:", validChallenges.length, "details:", JSON.stringify(validChallenges.map(c => ({ id: c.id, name: c.name, cashierId: c.cashierId, shiftType: c.shiftType, validFrom: c.validFrom, validTo: c.validTo }))));

      const grouped: Record<string, { cashierId: string; branchId: string; shiftType: string; targetAmount: number; targetTransactions: number; targetTicketValue: number; challenges: Array<{ id: number; name: string; type: string; targetValue: number; basePoints: number }> }> = {};

      for (const ch of validChallenges) {
        if (!ch.cashierId || !ch.branchId) continue;
        const effectiveShift = (ch.shiftType && ch.shiftType !== 'null') ? ch.shiftType : null;
        const shiftsToAssign = effectiveShift ? [effectiveShift] : ["morning", "evening"];
        for (const shift of shiftsToAssign) {
          const key = `${ch.cashierId}_${ch.branchId}_${shift}`;
          if (!grouped[key]) {
            grouped[key] = { cashierId: ch.cashierId, branchId: ch.branchId, shiftType: shift, targetAmount: 0, targetTransactions: 0, targetTicketValue: 0, challenges: [] };
          }
          grouped[key].challenges.push({ id: ch.id, name: ch.name, type: ch.challengeType, targetValue: ch.targetValue, basePoints: ch.basePoints });
          if (ch.challengeType === 'shift_sales') grouped[key].targetAmount = ch.targetValue;
          else if (ch.challengeType === 'customer_count') grouped[key].targetTransactions = Math.round(ch.targetValue);
          else if (ch.challengeType === 'avg_ticket') grouped[key].targetTicketValue = ch.targetValue;
        }
      }

      let targets = Object.values(grouped).map((g, idx) => ({
        id: idx + 1,
        cashierId: g.cashierId,
        branchId: g.branchId,
        shiftType: g.shiftType,
        cashierRole: 'main',
        periodType: 'daily',
        startDate: targetDate,
        endDate: targetDate,
        totalTargetAmount: String(g.targetAmount),
        totalTargetTransactions: g.targetTransactions,
        targetAmount: String(g.targetAmount),
        targetTransactions: g.targetTransactions,
        targetTicketValue: String(g.targetTicketValue),
        targetDate: targetDate,
        isActive: true,
        createdAt: new Date().toISOString(),
        challenges: g.challenges,
      })) as any[];

      const activeCommissions = await storage.getActiveProductCommissions(branchId as string);
      const validCommissions = activeCommissions.filter(c => {
        if (c.validFrom > targetDate) return false;
        if (c.validTo && c.validTo < targetDate) return false;
        return true;
      });

      if (validCommissions.length > 0) {
        let branchCashierIds: string[] = [];
        const commissionsNeedingAllCashiers = validCommissions.some(c => !c.cashierId);
        if (commissionsNeedingAllCashiers && branchId) {
          const branchEmps = (await storage.getBranchEmployeesByBranch(branchId as string))
            .filter(emp => emp.status === 'active');
          branchCashierIds = branchEmps
            .filter(emp => emp.linkedUserId)
            .map(emp => emp.linkedUserId as string);
        }

        for (const commission of validCommissions) {
          const effectiveShift = (commission.shiftType && commission.shiftType !== 'null') ? commission.shiftType : ((shiftType as string) || 'morning');
          const cashierIds: string[] = commission.cashierId
            ? [commission.cashierId]
            : branchCashierIds;

          for (const cid of cashierIds) {
            targets.push({
              id: 10000 + commission.id,
              cashierId: cid,
              branchId: commission.branchId,
              shiftType: effectiveShift,
              cashierRole: 'main',
              periodType: commission.commissionType === 'weekly_product' ? 'weekly' : 'monthly',
              startDate: commission.validFrom,
              endDate: commission.validTo || targetDate,
              totalTargetAmount: "0",
              totalTargetTransactions: 0,
              targetAmount: "0",
              targetTransactions: 0,
              targetTicketValue: "0",
              targetDate: targetDate,
              isActive: true,
              createdAt: commission.createdAt,
              challenges: [{
                id: commission.id,
                name: commission.productName,
                type: 'product_commission',
                targetValue: commission.targetQuantity,
                basePoints: commission.pointsOnTarget,
              }],
              productCommission: {
                commissionId: commission.id,
                productName: commission.productName,
                targetQuantity: commission.targetQuantity,
                pointsOnTarget: commission.pointsOnTarget,
                bonusPointsPerExtra: commission.bonusPointsPerExtra,
                commissionType: commission.commissionType,
              },
            });
          }
        }
      }

      let filtered = targets;
      if (branchFilter.branchIds) {
        filtered = filtered.filter(t => branchFilter.branchIds!.includes(t.branchId));
        const canViewAll = await canUserViewAllCashiers(req);
        if (!canViewAll) {
          filtered = filtered.filter(t => String(t.cashierId) === String(user?.id));
        }
      }

      res.json(filtered);
    } catch (error) {
      console.error("Error fetching challenges as targets:", error);
      res.status(500).json({ error: "فشل في جلب الأهداف من التحديات" });
    }
  });

