  app.post("/api/smart-incentives/product-commission-achievement", isAuthenticated, requirePermission("smart_incentives_commissions", "view"), async (req, res) => {
    try {
      const user = getCurrentUser(req);
      const { cashierId, commissionId, date, shiftType, quantitySold } = req.body;
      if (!cashierId || !commissionId || !date || quantitySold === undefined) {
        return res.status(400).json({ error: "بيانات ناقصة" });
      }

      const isSelfRecording = String(cashierId) === String(user.id);
      if (!isSelfRecording && user.role !== 'admin') {
        const perms = await storage.getUserPermissions(user.id);
        const commPerm = perms.find((p: any) => p.module === 'smart_incentives_commissions');
        if (!commPerm) {
          return res.status(403).json({ error: "غير مصرح - تحتاج صلاحية عمولات الأصناف" });
        }
        let actionsArray: string[] = [];
        const rawActions = commPerm.actions as unknown;
        if (Array.isArray(rawActions)) actionsArray = rawActions;
        else if (typeof rawActions === 'string') actionsArray = rawActions.replace(/[{}]/g, '').split(',').map((a: string) => a.trim());
        if (!actionsArray.includes('create') && !actionsArray.includes('edit')) {
          return res.status(403).json({ error: "غير مصرح - تحتاج صلاحية إنشاء أو تعديل عمولات الأصناف" });
        }
      }

      const parsedCommissionId = parseInt(String(commissionId));
      if (isNaN(parsedCommissionId)) {
        return res.status(400).json({ error: "معرف العمولة غير صالح" });
      }
      if (isNaN(Date.parse(date))) {
        return res.status(400).json({ error: "التاريخ غير صالح" });
      }
      const parsedQty = parseInt(String(quantitySold));
      if (isNaN(parsedQty) || parsedQty < 0) {
        return res.status(400).json({ error: "الكمية المباعة يجب أن تكون رقماً موجباً" });
      }

      const commission = await storage.getProductCommission(commissionId);
      if (!commission) return res.status(404).json({ error: "العمولة غير موجودة" });
      if (!commission.isActive) return res.status(400).json({ error: "العمولة غير نشطة" });

      if (commission.cashierId && commission.cashierId !== cashierId) {
        return res.status(403).json({ error: "هذه العمولة غير مخصصة لهذا الكاشير" });
      }

      if (date < commission.validFrom || (commission.validTo && date > commission.validTo)) {
        return res.status(400).json({ error: "التاريخ خارج فترة صلاحية العمولة" });
      }

      const branchId = commission.branchId;
      if (!branchId) return res.status(400).json({ error: "الفرع غير محدد في العمولة" });

      // Branch isolation: ensure cashier can only record for their own branch
      if (isSelfRecording && user.branchId && user.branchId !== branchId) {
        return res.status(403).json({ error: "غير مصرح - العمولة تنتمي لفرع آخر" });
      }
      if (!isSelfRecording && user.role !== 'admin' && user.branchId && user.branchId !== branchId) {
        return res.status(403).json({ error: "غير مصرح بالوصول لعمولات فرع آخر" });
      }

      const existingSales = await storage.getCashierProductSales(cashierId, date);
      const existingRecord = existingSales.find(s => s.commissionId === commissionId && s.shiftType === (shiftType || null));

      const qty = parseInt(String(quantitySold));
      const targetQty = commission.targetQuantity;

      if (qty < targetQty) {
        return res.status(400).json({ error: `لم تكمل الهدف - الكمية المطلوبة ${targetQty} قطعة وأنت أدخلت ${qty} فقط` });
      }

      if (existingRecord) {
        return res.status(400).json({ error: "تم تسجيل الإنجاز مسبقاً لهذا التاريخ والشفت - لا يمكن التكرار" });
      }

      const isTargetMet = true;
      let pointsAwarded = commission.pointsOnTarget;
      const extraQty = qty - targetQty;
      if (extraQty > 0 && commission.bonusPointsPerExtra) {
        pointsAwarded += Math.floor(extraQty * commission.bonusPointsPerExtra);
      }

      const saleRecord = await storage.createCashierProductSale({
        cashierId,
        branchId,
        commissionId,
        salesDate: date,
        shiftType: shiftType || null,
        quantitySold: qty,
        targetQuantity: targetQty,
        isTargetMet,
        pointsAwarded,
        recordedBy: (req as any).user?.id || null,
      });

      if (pointsAwarded > 0) {
        const settings = await storage.getPointSettings();
        const pointValue = settings?.pointValue || 1;

        await storage.createPointsEntry({
          cashierId,
          branchId,
          transactionDate: date,
          shiftType: shiftType || null,
          pointsType: 'product_commission',
          sourceId: commissionId,
          sourceName: commission.productName,
          pointsEarned: pointsAwarded,
          pointValue,
          amountEarned: pointsAwarded * pointValue,
          status: 'earned',
          notes: `عمولة صنف: ${commission.productName} - الكمية: ${qty}/${targetQty}`,
        });
      }

      res.json({ success: true, sale: saleRecord, pointsAwarded, isTargetMet });
    } catch (error) {
      console.error("Error recording commission achievement:", error);
      res.status(500).json({ error: "فشل في تسجيل الإنجاز" });
    }
  });

