  // Calculate incentives for all approved journals in a date range
  app.post("/api/smart-incentives/calculate-batch", isAuthenticated, requirePermission("smart_incentives_wallet", "create"), async (req, res) => {
    try {
      const user = getCurrentUser(req);
      const { branchId, dateFrom, dateTo } = req.body;
      if (!branchId || !dateFrom || !dateTo) {
        return res.status(400).json({ error: "يجب تحديد الفرع وتاريخ البداية والنهاية" });
      }
      if (isNaN(Date.parse(dateFrom))) {
        return res.status(400).json({ error: "تاريخ البداية غير صالح" });
      }
      if (isNaN(Date.parse(dateTo))) {
        return res.status(400).json({ error: "تاريخ النهاية غير صالح" });
      }
      if (user.role !== 'admin' && !(await canAccessBranch(req, branchId))) {
        return res.status(403).json({ error: "غير مصرح بالاحتساب لهذا الفرع" });
      }
      
      const { journals: approvedJournals } = await storage.getCashierJournalsFiltered({
        branchId,
        startDate: dateFrom,
        endDate: dateTo,
        status: 'approved',
      });
      
      const { journals: postedJournals } = await storage.getCashierJournalsFiltered({
        branchId,
        startDate: dateFrom,
        endDate: dateTo,
        status: 'posted',
      });
      
      const { journals: submittedJournals } = await storage.getCashierJournalsFiltered({
        branchId,
        startDate: dateFrom,
        endDate: dateTo,
        status: 'submitted',
      });
      
      const allJournals = [...approvedJournals, ...postedJournals, ...submittedJournals];
      
      let totalPoints = 0;
      let totalAmount = 0;
      let processedCount = 0;
      const errors: string[] = [];
      const journalDetails: Array<{journalId: number; cashierName: string; journalDate: string; status: string; points: number; diagnostics: any[]}> = [];
      
      for (const journal of allJournals) {
        try {
          const result = await storage.calculateJournalIncentives(journal.id);
          totalPoints += result.totalPoints;
          totalAmount += result.totalAmount;
          processedCount++;
          journalDetails.push({
            journalId: journal.id,
            cashierName: journal.cashierName,
            journalDate: journal.journalDate,
            status: journal.status,
            points: result.totalPoints,
            diagnostics: result.diagnostics || [],
          });
        } catch (err: any) {
          errors.push(`يومية #${journal.id}: ${err.message}`);
          console.error(`Error calculating for journal ${journal.id}:`, err);
        }
      }
      
      res.json({ processedCount, totalJournals: allJournals.length, totalPoints, totalAmount, journalDetails, errors: errors.length > 0 ? errors : undefined });
    } catch (error: any) {
      console.error("Error in batch calculation:", error);
      res.status(500).json({ error: "فشل في الاحتساب الجماعي" });
    }
  });

