  // Cashier Leaderboard - ترتيب الكاشيرين
  app.get("/api/analytics/cashier-leaderboard", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const { branchId, fromDate, toDate, status, discrepancyType } = req.query;
      
      if (!fromDate || !toDate) {
        return res.status(400).json({ error: "fromDate and toDate are required" });
      }
      
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      let data = await storage.getCashierLeaderboard(
        effectiveBranchId,
        fromDate as string,
        toDate as string,
        status as string | undefined,
        discrepancyType as string | undefined
      );
      if (!effectiveBranchId && branchFilter.branchIds) {
        data = data.filter((d: any) => branchFilter.branchIds!.includes(d.branchId));
      }
      
      // SECURITY: Non-admin/manager users can only see their own leaderboard data
      const canViewAllFlag = await canUserViewAllCashiers(req);
      if (!canViewAllFlag) {
        const user = getCurrentUser(req);
        data = data.filter((d: any) => String(d.cashierId) === String(user.id));
      }
      
      // Get incentive tiers to enrich the leaderboard
      const incentiveTiers = await storage.getActiveIncentiveTiers();
      
      // Get monthly targets for the period to calculate achievement
      const yearMonth = (fromDate as string).substring(0, 7);

      // PERF: fetch all branch monthly targets used by the leaderboard once
      // instead of per cashier (was 1 query per cashier in the leaderboard).
      const uniqueBranchIds = Array.from(new Set(data.map(c => c.branchId)));
      const monthlyTargetsAll = uniqueBranchIds.length > 0
        ? await storage.getBranchMonthlyTargetsForMonth(uniqueBranchIds, yearMonth)
        : [];
      const targetByBranchId = new Map(monthlyTargetsAll.map(t => [t.branchId, t]));

      // Enrich each cashier with their incentive tier (no DB calls in the loop).
      const enrichedData = data.map((cashier) => {
        const branchTarget = targetByBranchId.get(cashier.branchId);
        const targetAmount = branchTarget?.targetAmount || 0;
        const achievementPercent = targetAmount > 0 ? (cashier.totalSales / targetAmount) * 100 : 0;
        
        // Find applicable incentive tier
        const applicableTier = incentiveTiers.find(tier => {
          const minOk = achievementPercent >= (tier.minAchievementPercent || 0);
          const maxOk = !tier.maxAchievementPercent || achievementPercent <= tier.maxAchievementPercent;
          return minOk && maxOk && (tier.applicableTo === 'all' || tier.applicableTo === 'cashier');
        });
        
        // Calculate potential reward
        let calculatedReward = 0;
        if (applicableTier) {
          if (applicableTier.rewardType === 'fixed' && applicableTier.fixedAmount) {
            calculatedReward = applicableTier.fixedAmount;
          } else if (applicableTier.rewardType === 'percentage' && applicableTier.percentageRate) {
            const excessSales = cashier.totalSales - targetAmount;
            calculatedReward = excessSales > 0 ? (excessSales * applicableTier.percentageRate) / 100 : 0;
          } else if (applicableTier.rewardType === 'both') {
            if (applicableTier.fixedAmount) calculatedReward += applicableTier.fixedAmount;
            if (applicableTier.percentageRate) {
              const excessSales = cashier.totalSales - targetAmount;
              if (excessSales > 0) calculatedReward += (excessSales * applicableTier.percentageRate) / 100;
            }
          }
        }
        
        return {
          ...cashier,
          targetAmount,
          achievementPercent,
          incentiveTier: applicableTier ? {
            id: applicableTier.id,
            name: applicableTier.name,
            minPercent: applicableTier.minAchievementPercent,
            maxPercent: applicableTier.maxAchievementPercent
          } : null,
          calculatedReward
        };
      });
      
      res.json(enrichedData);
    } catch (error) {
      console.error("Error fetching cashier leaderboard:", error);
      res.status(500).json({ error: "Failed to fetch cashier leaderboard" });
    }
  });

  // Branch Competition - منافسة الفروع
  app.get("/api/analytics/branch-competition", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const { fromDate, toDate, status, discrepancyType, branchId } = req.query;
      
      if (!fromDate || !toDate) {
        return res.status(400).json({ error: "fromDate and toDate are required" });
      }
      
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const yearMonth = (fromDate as string).substring(0, 7);
      // PERF: scope branches first, then aggregate in 3 batched queries
      // instead of running getBranchMonthlyTargetByMonth + getCashierLeaderboard
      // per branch (was 2 × N branches DB calls + per-cashier work inside).
      const allBranches = await storage.getAllBranches();
      const effectiveBranchId = branchFilter.singleBranchId;
      const branches = effectiveBranchId
        ? allBranches.filter(b => b.id === effectiveBranchId)
        : (branchFilter.branchIds
          ? allBranches.filter(b => branchFilter.branchIds!.includes(b.id))
          : allBranches);

      if (branches.length === 0) {
        return res.json([]);
      }

      const scopedBranchIds = branches.map(b => b.id);
      const branchAgg = await storage.getBranchSalesAggregates(
        scopedBranchIds,
        fromDate as string,
        toDate as string,
        status as string | undefined,
        discrepancyType as string | undefined,
      );
      const monthlyTargetsAll = await storage.getBranchMonthlyTargetsForMonth(
        scopedBranchIds,
        yearMonth,
      );
      const incentiveTiers = await storage.getActiveIncentiveTiers();
      const aggByBranch = new Map(branchAgg.map(r => [r.branchId, r]));
      const targetByBranch = new Map(monthlyTargetsAll.map(t => [t.branchId, t]));

      const branchStats = branches.map((branch) => {
        const branchTarget = targetByBranch.get(branch.id);
        const targetAmount = branchTarget?.targetAmount || 0;
        const agg = aggByBranch.get(branch.id) || { totalSales: 0, cashierCount: 0, totalTransactions: 0 };
        const totalSales = agg.totalSales;
        const cashierCount = agg.cashierCount;
        const totalTransactions = agg.totalTransactions;

        const achievementPercent = targetAmount > 0 ? (totalSales / targetAmount) * 100 : 0;
        const variance = totalSales - targetAmount;
        
        // Find applicable incentive tier for branch
        const applicableTier = incentiveTiers.find(tier => {
          const minOk = achievementPercent >= (tier.minAchievementPercent || 0);
          const maxOk = !tier.maxAchievementPercent || achievementPercent <= tier.maxAchievementPercent;
          return minOk && maxOk && (tier.applicableTo === 'all' || tier.applicableTo === 'branch');
        });
        
        // Calculate potential reward
        let calculatedReward = 0;
        if (applicableTier) {
          if (applicableTier.rewardType === 'fixed' && applicableTier.fixedAmount) {
            calculatedReward = applicableTier.fixedAmount;
          } else if (applicableTier.rewardType === 'percentage' && applicableTier.percentageRate) {
            const excessSales = totalSales - targetAmount;
            calculatedReward = excessSales > 0 ? (excessSales * applicableTier.percentageRate) / 100 : 0;
          } else if (applicableTier.rewardType === 'both') {
            if (applicableTier.fixedAmount) calculatedReward += applicableTier.fixedAmount;
            if (applicableTier.percentageRate) {
              const excessSales = totalSales - targetAmount;
              if (excessSales > 0) calculatedReward += (excessSales * applicableTier.percentageRate) / 100;
            }
          }
        }
        
        return {
          branchId: branch.id,
          branchName: branch.name,
          targetAmount,
          totalSales,
          achievementPercent,
          variance,
          cashierCount,
          totalTransactions,
          averageTicket: totalTransactions > 0 ? totalSales / totalTransactions : 0,
          incentiveTier: applicableTier ? {
            id: applicableTier.id,
            name: applicableTier.name,
            minPercent: applicableTier.minAchievementPercent,
            maxPercent: applicableTier.maxAchievementPercent
          } : null,
          calculatedReward,
          rank: 0
        };
      });

      // Sort by achievement percent and assign ranks
      branchStats.sort((a, b) => b.achievementPercent - a.achievementPercent);
      branchStats.forEach((branch, idx) => { branch.rank = idx + 1; });
      
      res.json(branchStats);
    } catch (error) {
      console.error("Error fetching branch competition:", error);
      res.status(500).json({ error: "Failed to fetch branch competition" });
    }
  });

