  // Get Waste Analytics - waste vs sales comparison (must be before /:id route)
  app.get("/api/waste-reports/analytics", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const queryBranchId = req.query.branchId as string | undefined;
      const date = req.query.date as string || new Date().toISOString().split('T')[0];
      
      // SECURITY: Apply branch filter
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      if (!effectiveBranchId) {
        return res.json({ error: "يجب تحديد الفرع" });
      }
      
      const branchId = effectiveBranchId;
      
      // Get current month date range
      const currentMonth = date.substring(0, 7);
      const monthStart = `${currentMonth}-01`;
      const monthEnd = `${currentMonth}-31`;
      
      // Get daily waste reports
      const dailyWasteReports = await storage.getWasteReports(branchId ?? undefined, date, date);
      const dailyWasteValue = dailyWasteReports.reduce((sum, r) => sum + (r.totalValue || 0), 0);
      const dailyWasteItems = dailyWasteReports.reduce((sum, r) => sum + (r.totalItems || 0), 0);
      
      // Get monthly waste reports
      const monthlyWasteReports = await storage.getWasteReports(branchId ?? undefined, monthStart, monthEnd);
      const monthlyWasteValue = monthlyWasteReports.reduce((sum, r) => sum + (r.totalValue || 0), 0);
      const monthlyWasteItems = monthlyWasteReports.reduce((sum, r) => sum + (r.totalItems || 0), 0);
      
      const [dailySalesResult, monthlySalesResult] = await Promise.all([
        db.select({
          totalSales: sql<number>`coalesce(sum(total_sales), 0)::numeric`,
        }).from(cashierSalesJournals)
          .where(and(
            eq(cashierSalesJournals.journalDate, date),
            branchId ? eq(cashierSalesJournals.branchId, branchId) : undefined
          )),
        db.select({
          totalSales: sql<number>`coalesce(sum(total_sales), 0)::numeric`,
        }).from(cashierSalesJournals)
          .where(and(
            gte(cashierSalesJournals.journalDate, monthStart),
            lte(cashierSalesJournals.journalDate, monthEnd),
            branchId ? eq(cashierSalesJournals.branchId, branchId) : undefined
          )),
      ]);
      const dailySales = Number(dailySalesResult[0]?.totalSales || 0);
      const monthlySales = Number(monthlySalesResult[0]?.totalSales || 0);
      
      // Calculate waste percentages
      const dailyWastePercent = dailySales > 0 ? (dailyWasteValue / dailySales) * 100 : 0;
      const monthlyWastePercent = monthlySales > 0 ? (monthlyWasteValue / monthlySales) * 100 : 0;
      
      // Get waste by reason
      const wasteByReason: Record<string, { count: number; value: number }> = {};
      for (const report of dailyWasteReports) {
        const items = await storage.getWasteItems(report.id);
        for (const item of items) {
          const reason = item.wasteReason || 'other';
          if (!wasteByReason[reason]) {
            wasteByReason[reason] = { count: 0, value: 0 };
          }
          wasteByReason[reason].count += item.quantity || 0;
          wasteByReason[reason].value += item.totalValue || 0;
        }
      }
      
      res.json({
        date,
        branchId: branchId || 'all',
        daily: {
          wasteValue: dailyWasteValue,
          wasteItems: dailyWasteItems,
          sales: dailySales,
          wastePercent: Math.round(dailyWastePercent * 100) / 100,
          reportsCount: dailyWasteReports.length,
        },
        monthly: {
          wasteValue: monthlyWasteValue,
          wasteItems: monthlyWasteItems,
          sales: monthlySales,
          wastePercent: Math.round(monthlyWastePercent * 100) / 100,
          reportsCount: monthlyWasteReports.length,
        },
        wasteByReason,
      });
    } catch (error) {
      console.error("Error fetching waste analytics:", error);
      res.status(500).json({ error: "فشل في جلب إحصائيات الهالك" });
    }
  });

  // Detailed Waste Analytics Reports
  app.get("/api/waste-reports/analytics-detailed", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const queryBranchId = req.query.branchId as string | undefined;
      const dateFrom = req.query.dateFrom as string || new Date(Date.now() - 30 * 86400000).toISOString().split('T')[0];
      const dateTo = req.query.dateTo as string || new Date().toISOString().split('T')[0];
      const productIdFilter = req.query.productId ? Number(req.query.productId) : undefined;
      const categoryFilter = req.query.category as string | undefined;

      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }

      const effectiveBranchId = branchFilter.singleBranchId;
      const reports = await storage.getWasteReports(effectiveBranchId ?? undefined, dateFrom, dateTo);
      const approvedReports = reports.filter(r => r.status === "approved" || r.status === "submitted" || r.status === "draft");

      const allProducts = await storage.getAllProducts();
      const productMap = new Map(allProducts.map((p: any) => [p.id, p]));
      const allBranches = await storage.getAllBranches();
      const branchMap = new Map(allBranches.map((b: any) => [b.id, b]));

      const allItems: Array<{ item: any; report: any }> = [];
      for (const report of approvedReports) {
        const items = await storage.getWasteItems(report.id);
        for (const item of items) {
          if (productIdFilter && item.productId !== productIdFilter) continue;
          const product = productMap.get(item.productId);
          if (categoryFilter && categoryFilter !== "all" && product?.category !== categoryFilter) continue;
          allItems.push({ item, report });
        }
      }

      let totalValue = 0;
      let totalQuantity = 0;
      const byDateMap: Record<string, { date: string; totalValue: number; totalQuantity: number; itemCount: number }> = {};
      const byProductMap: Record<number, { productId: number; productName: string; category: string; totalQuantity: number; totalValue: number; reportCount: number; dates: Set<string>; reasons: Record<string, number> }> = {};
      const byCategoryMap: Record<string, { category: string; categoryLabel: string; totalQuantity: number; totalValue: number; productCount: Set<number> }> = {};
      const byReasonMap: Record<string, { reason: string; totalQuantity: number; totalValue: number; productCount: Set<number> }> = {};
      const byBranchMap: Record<string, { branchId: string; branchName: string; totalQuantity: number; totalValue: number; reportCount: number }> = {};

      const categoryLabels: Record<string, string> = {
        pastries: "معجنات", sweets: "حلويات", bread: "خبز", cakes: "كيك",
        cookies: "كوكيز", drinks: "مشروبات", sandwiches: "ساندويتشات", other: "أخرى"
      };
      const reasonLabels: Record<string, string> = {
        expired: "منتهي الصلاحية", damaged: "تالف", quality_issue: "مشكلة جودة",
        overproduction: "إنتاج زائد", customer_return: "إرجاع عميل", other: "أخرى"
      };

      for (const { item, report } of allItems) {
        const product = productMap.get(item.productId);
        const productName = product?.name || "غير معروف";
        const category = product?.category || "other";
        const reason = item.wasteReason || "other";
        const value = item.totalValue || 0;
        const qty = item.quantity || 0;

        totalValue += value;
        totalQuantity += qty;

        if (!byDateMap[report.reportDate]) {
          byDateMap[report.reportDate] = { date: report.reportDate, totalValue: 0, totalQuantity: 0, itemCount: 0 };
        }
        byDateMap[report.reportDate].totalValue += value;
        byDateMap[report.reportDate].totalQuantity += qty;
        byDateMap[report.reportDate].itemCount += 1;

        if (!byProductMap[item.productId]) {
          byProductMap[item.productId] = { productId: item.productId, productName, category, totalQuantity: 0, totalValue: 0, reportCount: 0, dates: new Set(), reasons: {} };
        }
        byProductMap[item.productId].totalQuantity += qty;
        byProductMap[item.productId].totalValue += value;
        byProductMap[item.productId].dates.add(report.reportDate);
        byProductMap[item.productId].reasons[reason] = (byProductMap[item.productId].reasons[reason] || 0) + qty;

        if (!byCategoryMap[category]) {
          byCategoryMap[category] = { category, categoryLabel: categoryLabels[category] || category, totalQuantity: 0, totalValue: 0, productCount: new Set() };
        }
        byCategoryMap[category].totalQuantity += qty;
        byCategoryMap[category].totalValue += value;
        byCategoryMap[category].productCount.add(item.productId);

        if (!byReasonMap[reason]) {
          byReasonMap[reason] = { reason, totalQuantity: 0, totalValue: 0, productCount: new Set() };
        }
        byReasonMap[reason].totalQuantity += qty;
        byReasonMap[reason].totalValue += value;
        byReasonMap[reason].productCount.add(item.productId);

        if (!byBranchMap[report.branchId]) {
          const branch = branchMap.get(report.branchId);
          byBranchMap[report.branchId] = { branchId: report.branchId, branchName: branch?.name || report.branchId, totalQuantity: 0, totalValue: 0, reportCount: 0 };
        }
        byBranchMap[report.branchId].totalQuantity += qty;
        byBranchMap[report.branchId].totalValue += value;
      }

      for (const { report } of allItems) {
        if (byBranchMap[report.branchId]) {
          byBranchMap[report.branchId].reportCount = approvedReports.filter(r => r.branchId === report.branchId).length;
        }
      }

      const byDate = Object.values(byDateMap).sort((a, b) => a.date.localeCompare(b.date));
      const dayCount = byDate.length || 1;

      const byProduct = Object.values(byProductMap).map(p => ({
        productId: p.productId,
        productName: p.productName,
        category: p.category,
        categoryLabel: categoryLabels[p.category] || p.category,
        totalQuantity: p.totalQuantity,
        totalValue: Math.round(p.totalValue * 100) / 100,
        occurrences: p.dates.size,
        lastWasteDate: Array.from(p.dates).sort().pop() || "",
        topReason: Object.entries(p.reasons).sort(([,a],[,b]) => b - a)[0]?.[0] || "other",
        topReasonLabel: reasonLabels[Object.entries(p.reasons).sort(([,a],[,b]) => b - a)[0]?.[0] || "other"] || "أخرى",
      })).sort((a, b) => b.totalValue - a.totalValue);

      const recurring = byProduct
        .filter(p => p.occurrences >= 3)
        .sort((a, b) => b.occurrences - a.occurrences);

      const byCategory = Object.values(byCategoryMap).map(c => ({
        category: c.category,
        categoryLabel: c.categoryLabel,
        totalQuantity: c.totalQuantity,
        totalValue: Math.round(c.totalValue * 100) / 100,
        productCount: c.productCount.size,
        percentage: totalValue > 0 ? Math.round((c.totalValue / totalValue) * 10000) / 100 : 0,
      })).sort((a, b) => b.totalValue - a.totalValue);

      const byReason = Object.values(byReasonMap).map(r => ({
        reason: r.reason,
        reasonLabel: reasonLabels[r.reason] || r.reason,
        totalQuantity: r.totalQuantity,
        totalValue: Math.round(r.totalValue * 100) / 100,
        productCount: r.productCount.size,
        percentage: totalValue > 0 ? Math.round((r.totalValue / totalValue) * 10000) / 100 : 0,
      })).sort((a, b) => b.totalValue - a.totalValue);

      const byBranch = Object.values(byBranchMap).sort((a, b) => b.totalValue - a.totalValue);

      res.json({
        filters: { branchId: effectiveBranchId || "all", dateFrom, dateTo, productId: productIdFilter, category: categoryFilter },
        summary: {
          totalValue: Math.round(totalValue * 100) / 100,
          totalQuantity,
          avgWastePerDay: Math.round((totalValue / dayCount) * 100) / 100,
          avgQuantityPerDay: Math.round((totalQuantity / dayCount) * 100) / 100,
          reportCount: approvedReports.length,
          daysCovered: dayCount,
          productCount: Object.keys(byProductMap).length,
        },
        byDate,
        byProduct: byProduct.slice(0, 50),
        topDamaged: byProduct.slice(0, 10),
        recurring,
        byCategory,
        byReason,
        byBranch,
      });
    } catch (error) {
      console.error("Error fetching detailed waste analytics:", error);
      res.status(500).json({ error: "فشل في جلب التقارير التفصيلية للهالك" });
    }
  });

  // Get Product-Level Waste Details (must be before /:id route)
  app.get("/api/waste-reports/product-details/:productId", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const productId = Number(req.params.productId);
      if (isNaN(productId)) return res.status(400).json({ error: "معرف المنتج غير صالح" });

      const queryBranchId = req.query.branchId as string | undefined;
      const dateFrom = req.query.dateFrom as string || new Date(Date.now() - 90 * 86400000).toISOString().split('T')[0];
      const dateTo = req.query.dateTo as string || new Date().toISOString().split('T')[0];

      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);
      if (!branchFilter.hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول" });

      const product = await storage.getProduct(productId);
      if (!product) return res.status(404).json({ error: "المنتج غير موجود" });

      const categoryLabels: Record<string, string> = {
        pastries: "معجنات", sweets: "حلويات", bread: "خبز", cakes: "كيك",
        cookies: "كوكيز", drinks: "مشروبات", sandwiches: "ساندويتشات", other: "أخرى"
      };
      const reasonLabels: Record<string, string> = {
        expired: "منتهي الصلاحية", damaged: "تالف", quality_issue: "مشكلة جودة",
        overproduction: "إنتاج زائد", customer_return: "إرجاع عميل", other: "أخرى"
      };

      const effectiveBranchId = branchFilter.singleBranchId;
      const reports = await storage.getWasteReports(effectiveBranchId ?? undefined, dateFrom, dateTo);

      const allBranches = await storage.getAllBranches();
      const branchMap = new Map(allBranches.map((b: any) => [b.id, b]));

      const wasteEntries: Array<{
        wasteItemId: number;
        reportId: number;
        reportDate: string;
        shift: string;
        branchId: string;
        branchName: string;
        quantity: number;
        unitPrice: number;
        totalValue: number;
        wasteReason: string;
        wasteReasonLabel: string;
        reasonDetails: string | null;
        imageUrl: string | null;
        reportStatus: string;
      }> = [];

      let totalQuantity = 0;
      let totalValue = 0;
      const reasonCounts: Record<string, number> = {};
      const branchCounts: Record<string, { branchName: string; quantity: number; value: number }> = {};
      const images: string[] = [];

      for (const report of reports) {
        const items = await storage.getWasteItems(report.id);
        for (const item of items) {
          if (item.productId !== productId) continue;

          const branch = branchMap.get(report.branchId);
          const qty = item.quantity || 0;
          const val = item.totalValue || 0;
          const reason = item.wasteReason || "other";

          totalQuantity += qty;
          totalValue += val;
          reasonCounts[reason] = (reasonCounts[reason] || 0) + qty;

          if (!branchCounts[report.branchId]) {
            branchCounts[report.branchId] = { branchName: branch?.name || report.branchId, quantity: 0, value: 0 };
          }
          branchCounts[report.branchId].quantity += qty;
          branchCounts[report.branchId].value += val;

          if (item.imageUrl) images.push(item.imageUrl);

          wasteEntries.push({
            wasteItemId: item.id,
            reportId: report.id,
            reportDate: report.reportDate,
            shift: report.shiftId ? String(report.shiftId) : "-",
            branchId: report.branchId,
            branchName: branch?.name || report.branchId,
            quantity: qty,
            unitPrice: item.unitPrice || 0,
            totalValue: val,
            wasteReason: reason,
            wasteReasonLabel: reasonLabels[reason] || reason,
            reasonDetails: item.reasonDetails || null,
            imageUrl: item.imageUrl || null,
            reportStatus: report.status || "draft",
          });
        }
      }

      wasteEntries.sort((a, b) => b.reportDate.localeCompare(a.reportDate));

      const topReason = Object.entries(reasonCounts).sort(([,a],[,b]) => b - a)[0];
      const reasonBreakdown = Object.entries(reasonCounts).map(([reason, count]) => ({
        reason,
        reasonLabel: reasonLabels[reason] || reason,
        quantity: count,
        percentage: totalQuantity > 0 ? Math.round((count / totalQuantity) * 10000) / 100 : 0,
      })).sort((a, b) => b.quantity - a.quantity);

      const branchBreakdown = Object.entries(branchCounts).map(([branchId, data]) => ({
        branchId,
        ...data,
      })).sort((a, b) => b.value - a.value);

      res.json({
        product: {
          id: product.id,
          name: product.name,
          nameEn: product.nameEn || null,
          sku: product.sku || null,
          category: product.category,
          categoryLabel: categoryLabels[product.category] || product.category,
          unit: product.unit || "قطعة",
          basePrice: product.basePrice || 0,
          priceExclVat: product.priceExclVat || 0,
          description: product.description || null,
          isActive: product.isActive,
        },
        summary: {
          totalQuantity,
          totalValue: Math.round(totalValue * 100) / 100,
          entryCount: wasteEntries.length,
          avgQuantityPerEntry: wasteEntries.length > 0 ? Math.round((totalQuantity / wasteEntries.length) * 100) / 100 : 0,
          topReason: topReason ? topReason[0] : null,
          topReasonLabel: topReason ? (reasonLabels[topReason[0]] || topReason[0]) : null,
          firstDate: wasteEntries.length > 0 ? wasteEntries[wasteEntries.length - 1].reportDate : null,
          lastDate: wasteEntries.length > 0 ? wasteEntries[0].reportDate : null,
        },
        images,
        reasonBreakdown,
        branchBreakdown,
        entries: wasteEntries,
      });
    } catch (error) {
      console.error("Error fetching product waste details:", error);
      res.status(500).json({ error: "فشل في جلب تفاصيل هالك المنتج" });
    }
  });

  // Get Waste Stats - today's summary by branch (must be before /:id route)
  app.get("/api/waste-reports/stats", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const today = new Date().toISOString().split('T')[0];
      const queryBranchId = req.query.branchId as string | undefined;
      
      // SECURITY: Apply branch filter
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const branchId = branchFilter.singleBranchId;
      const reports = await storage.getWasteReports(branchId ?? undefined, today, today);
      
      const branchStats = new Map<string, { totalItems: number; totalValue: number; reportCount: number }>();
      
      for (const report of reports) {
        const existing = branchStats.get(report.branchId) || { totalItems: 0, totalValue: 0, reportCount: 0 };
        branchStats.set(report.branchId, {
          totalItems: existing.totalItems + (report.totalItems || 0),
          totalValue: existing.totalValue + (report.totalValue || 0),
          reportCount: existing.reportCount + 1,
        });
      }
      
      const stats = Array.from(branchStats.entries()).map(([branchId, data]) => ({
        branchId,
        date: today,
        ...data,
      }));
      
      res.json(stats);
    } catch (error) {
      console.error("Error fetching waste stats:", error);
      res.status(500).json({ error: "Failed to fetch waste stats" });
    }
  });

  // Get All Waste Reports
  app.get("/api/waste-reports", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const queryBranchId = req.query.branchId as string | undefined;
      const dateFrom = req.query.dateFrom as string | undefined;
      const dateTo = req.query.dateTo as string | undefined;
      
      // SECURITY: Apply branch filter
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      const reports = await storage.getWasteReports(effectiveBranchId ?? undefined, dateFrom, dateTo);
      const filteredReports = branchFilter.branchIds && !effectiveBranchId
        ? reports.filter(r => branchFilter.branchIds!.includes(r.branchId))
        : reports;
      res.json(filteredReports);
    } catch (error) {
      console.error("Error fetching waste reports:", error);
      res.status(500).json({ error: "Failed to fetch waste reports" });
    }
  });

  // Waste Reports History endpoint (MUST be before /:id route to avoid Express matching "history" as :id)
  app.get("/api/waste-reports/history", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const queryBranchId = req.query.branchId as string | undefined;
      const dateFrom = req.query.dateFrom as string | undefined;
      const dateTo = req.query.dateTo as string | undefined;
      const status = req.query.status as string | undefined;
      
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      const reports = await storage.getWasteReports(effectiveBranchId ?? undefined, dateFrom, dateTo);
      const branchFiltered = branchFilter.branchIds && !effectiveBranchId
        ? reports.filter(r => branchFilter.branchIds!.includes(r.branchId))
        : reports;
      
      const filtered = status && status !== "all" 
        ? branchFiltered.filter(r => r.status === status) 
        : branchFiltered;
      
      const reportsWithItems = await Promise.all(filtered.map(async (report) => {
        const items = await storage.getWasteItems(report.id);
        return { ...report, items };
      }));
      
      res.json(reportsWithItems);
    } catch (error) {
      console.error("Error fetching waste reports history:", error);
      res.status(500).json({ error: "فشل في جلب سجل تقارير الهالك" });
    }
  });

  // Get Single Waste Report
  app.get("/api/waste-reports/:id", isAuthenticated, requirePermission("operations", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) {
        return res.status(400).json({ error: "Invalid report ID" });
      }
      const report = await storage.getWasteReport(id);
      if (!report) {
        return res.status(404).json({ error: "Report not found" });
      }
      
      // Verify branch access for non-admin users
      const user = getCurrentUser(req);
      if (user?.role !== "admin" && report.branchId) {
        const hasAccess = await canAccessBranch(req, report.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "ليس لديك صلاحية للوصول لهذا التقرير" });
        }
      }
      
      res.json(report);
    } catch (error) {
      console.error("Error fetching waste report:", error);
      res.status(500).json({ error: "Failed to fetch waste report" });
    }
  });

  // Create Waste Report
  app.post("/api/waste-reports", isAuthenticated, requirePermission("operations", "create"), requireBranchAccess, async (req, res) => {
    try {
      const currentUser = getCurrentUser(req);
      
      if (!isUserAdmin(req) && req.body.branchId) {
        const hasAccess = await canAccessBranch(req, req.body.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "ليس لديك صلاحية لإنشاء تقرير هدر لهذا الفرع" });
        }
      }
      
      if (!req.body.branchId) {
        return res.status(400).json({ error: "الفرع مطلوب" });
      }
      
      // Check for existing report for same branch+date+shift (only AFTER access check)
      if (req.body.reportDate) {
        const existingReports = await storage.getWasteReports(req.body.branchId, req.body.reportDate, req.body.reportDate);
        const existingForShift = existingReports.find(r => 
          r.shiftName === (req.body.shiftName || null)
        );
        if (existingForShift) {
          return res.status(200).json({ ...existingForShift, existing: true });
        }
      }
      
      const sanitizedBody = { ...req.body };
      if (typeof sanitizedBody.notes === 'string') sanitizedBody.notes = sanitizedBody.notes.slice(0, 1000);
      if (typeof sanitizedBody.shiftName === 'string') sanitizedBody.shiftName = sanitizedBody.shiftName.slice(0, 50);
      
      const validatedData = insertWasteReportSchema.parse({
        ...sanitizedBody,
        reportedBy: currentUser?.id,
        reporterName: currentUser ? `${currentUser.firstName || ''} ${currentUser.lastName || ''}`.trim() : null,
      });
      const report = await storage.createWasteReport(validatedData);
      res.status(201).json(report);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid data", details: error.errors });
      }
      console.error("Error creating waste report:", error);
      res.status(500).json({ error: "Failed to create waste report" });
    }
  });

  // Update Waste Report with approval workflow
  app.patch("/api/waste-reports/:id", isAuthenticated, requirePermission("operations", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) {
        return res.status(400).json({ error: "Invalid report ID" });
      }
      
      const existingReport = await storage.getWasteReport(id);
      if (!existingReport) {
        return res.status(404).json({ error: "Report not found" });
      }
      
      const user = getCurrentUser(req);
      if (user?.role !== "admin" && existingReport.branchId) {
        const hasAccess = await canAccessBranch(req, existingReport.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "ليس لديك صلاحية لتعديل تقارير هذا الفرع" });
        }
      }
      
      const isAdmin = user?.role === "admin" || user?.role === "manager";
      const newStatus = req.body.status;
      
      // Prevent edits to approved reports (except by admin)
      if (existingReport.status === 'approved' && !isAdmin) {
        return res.status(403).json({ error: "لا يمكن تعديل تقرير معتمد" });
      }
      
      // When report is submitted, only allow status changes (approve/reject) by authorized users
      if (existingReport.status === 'submitted' && !isAdmin) {
        if (!newStatus || (newStatus !== 'approved' && newStatus !== 'rejected')) {
          return res.status(403).json({ error: "التقرير مرسل للاعتماد ولا يمكن تعديله" });
        }
      }
      
      // Only allow approve/reject by admin/manager
      if (newStatus === 'approved' || newStatus === 'rejected') {
        if (!isAdmin) {
          return res.status(403).json({ error: "فقط المدير يمكنه اعتماد أو رفض التقارير" });
        }
      }
      
      if (newStatus === 'submitted' || newStatus === 'approved') {
        const items = await storage.getWasteItems(id);
        if (!items || items.length === 0) {
          return res.status(400).json({ error: "لا يمكن إرسال أو اعتماد تقرير بدون أصناف هالكة" });
        }
      }
      
      const partialData = insertWasteReportSchema.partial().parse(req.body);
      
      if (newStatus === 'approved') {
        // Manager-approval gate: if the branch's daily waste exceeds the configured
        // gate threshold, approval requires a written justification from the manager.
        const justification = typeof req.body.approvalJustification === 'string'
          ? req.body.approvalJustification.trim()
          : '';
        try {
          const gate = await checkApprovalGate({
            branchId: existingReport.branchId,
            date: existingReport.reportDate,
          });
          if (gate.required && !justification) {
            return res.status(409).json({
              error: "هذا التقرير يتجاوز الحد المسموح للهدر ويتطلب تبرير المدير قبل الاعتماد",
              requiresJustification: true,
              threshold: gate.threshold,
              currentPercent: gate.currentPercent,
            });
          }
          if (gate.required && justification) {
            const stamp = `[موافقة استثنائية — تجاوز ${gate.currentPercent}% / الحد ${gate.threshold}%: ${justification.slice(0, 500)} — ${user?.id || ''} ${new Date().toISOString().split('T')[0]}]`;
            (partialData as any).notes = `${existingReport.notes ? existingReport.notes + '\n' : ''}${stamp}`;
          }
        } catch (gateErr) {
          // Fail closed: never auto-approve a high-waste report if the gate check
          // itself fails — block the approval and ask the user to retry.
          console.error("Approval gate check failed (blocking approval):", gateErr);
          return res.status(503).json({ error: "تعذّر التحقق من حد الموافقة، يرجى المحاولة مرة أخرى" });
        }
        (partialData as any).approvedBy = user?.id;
        (partialData as any).approvedAt = new Date();
      }
      
      if (newStatus === 'rejected') {
        (partialData as any).approvedBy = user?.id;
        (partialData as any).approvedAt = new Date();
      }
      
      const report = await storage.updateWasteReport(id, partialData);

      // Run the governance engine after a report is submitted or approved so any
      // breached thresholds raise alerts + notify managers. Non-blocking.
      if (newStatus === 'submitted' || newStatus === 'approved') {
        evaluateWasteGovernance({
          branchId: existingReport.branchId,
          date: existingReport.reportDate,
        }).catch((e) => console.error("[waste-governance] post-status hook failed:", e));
      }

      res.json(report);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: "Invalid data", details: error.errors });
      }
      console.error("Error updating waste report:", error);
      res.status(500).json({ error: "Failed to update waste report" });
    }
  });

