  // Get single production order with items
  app.get("/api/advanced-production-orders/:id", isAuthenticated, requirePermission("production", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) {
        return res.status(400).json({ error: "Invalid order ID" });
      }
      
      const result = await storage.getAdvancedProductionOrderWithItems(id);
      if (!result) {
        return res.status(404).json({ error: "Order not found" });
      }
      
      // SECURITY: Verify branch access for non-admin users (must have access to either source or target branch)
      if (!isUserAdmin(req)) {
        const hasSourceAccess = result.order.sourceBranchId ? await canAccessBranch(req, result.order.sourceBranchId) : false;
        const hasTargetAccess = result.order.targetBranchId ? await canAccessBranch(req, result.order.targetBranchId) : false;
        if (!hasSourceAccess && !hasTargetAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الأمر" });
        }
      }
      
      const schedules = await storage.getProductionOrderSchedules(id);
      
      const order = result.order;
      const orderStartDate = order.startDate;
      const orderEndDate = order.endDate || order.startDate;
      let dailyProductionComparison: any[] = [];
      let comparisonScope = '';
      
      if (order.sourceBranchId) {
        const normalizeArabic = (name: string): string => {
          return name
            .trim()
            .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
            .replace(/[أإآٱ]/g, 'ا')
            .replace(/ة/g, 'ه')
            .replace(/ى/g, 'ي')
            .replace(/ؤ/g, 'و')
            .replace(/ئ/g, 'ي')
            .replace(/[-_\s]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();
        };
        
        let allBatches: any[] = [];
        
        const batchesByOrderId = await storage.getAllDailyProductionBatches({
          branchId: order.sourceBranchId,
          productionOrderId: id,
        } as any);
        
        if (batchesByOrderId && batchesByOrderId.length > 0) {
          allBatches = batchesByOrderId;
          comparisonScope = 'مرتبط بأمر الإنتاج';
        } else if (orderStartDate) {
          if (orderStartDate === orderEndDate || !orderEndDate) {
            const dateBatches = await storage.getAllDailyProductionBatches({
              branchId: order.sourceBranchId,
              date: orderStartDate,
            });
            allBatches = dateBatches;
            comparisonScope = `تاريخ ${orderStartDate}`;
          } else {
            const start = new Date(orderStartDate);
            const end = new Date(orderEndDate);
            const dateList: string[] = [];
            for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
              dateList.push(d.toISOString().split('T')[0]);
            }
            for (const dateStr of dateList) {
              const dayBatches = await storage.getAllDailyProductionBatches({
                branchId: order.sourceBranchId,
                date: dateStr,
              });
              allBatches.push(...dayBatches);
            }
            comparisonScope = `من ${orderStartDate} إلى ${orderEndDate}`;
          }
        }
        
        const orderItems = result.items || [];
        
        const batchesByProductId = new Map<number, { totalProduced: number; batches: any[] }>();
        const batchesByName = new Map<string, { totalProduced: number; batches: any[] }>();
        
        for (const batch of allBatches) {
          if (batch.productId) {
            if (!batchesByProductId.has(batch.productId)) {
              batchesByProductId.set(batch.productId, { totalProduced: 0, batches: [] });
            }
            const entry = batchesByProductId.get(batch.productId)!;
            entry.totalProduced += batch.quantity || 0;
            entry.batches.push(batch);
          }
          
          const nameKey = normalizeArabic(batch.productName);
          if (!batchesByName.has(nameKey)) {
            batchesByName.set(nameKey, { totalProduced: 0, batches: [] });
          }
          const nameEntry = batchesByName.get(nameKey)!;
          nameEntry.totalProduced += batch.quantity || 0;
          nameEntry.batches.push(batch);
        }
        
        const matchedBatchKeys = new Set<string>();
        
        dailyProductionComparison = orderItems.map((item: any) => {
          const itemProductId = item.productId || item.product_id;
          const itemName = normalizeArabic(item.productName || item.product_name || '');
          
          let matched: { totalProduced: number; batches: any[] } | undefined;
          
          if (itemProductId && batchesByProductId.has(itemProductId)) {
            matched = batchesByProductId.get(itemProductId);
            if (matched) {
              for (const b of matched.batches) {
                matchedBatchKeys.add(normalizeArabic(b.productName));
              }
            }
          }
          
          if (!matched) {
            matched = batchesByName.get(itemName);
            if (matched) matchedBatchKeys.add(itemName);
          }
          
          if (!matched) {
            for (const [bKey, bVal] of batchesByName.entries()) {
              if (bKey.includes(itemName) || itemName.includes(bKey)) {
                matched = bVal;
                matchedBatchKeys.add(bKey);
                break;
              }
            }
          }
          
          if (!matched) {
            const itemParts = itemName.split(' ').filter((p: string) => p.length > 2);
            if (itemParts.length >= 2) {
              for (const [bKey, bVal] of batchesByName.entries()) {
                const matchCount = itemParts.filter((p: string) => bKey.includes(p)).length;
                if (matchCount >= Math.ceil(itemParts.length * 0.6)) {
                  matched = bVal;
                  matchedBatchKeys.add(bKey);
                  break;
                }
              }
            }
          }
          
          const actualProduced = matched?.totalProduced || 0;
          const targetQty = Number(item.targetQuantity || item.target_quantity || item.quantity) || 0;
          const variance = actualProduced - targetQty;
          const achievementPct = targetQty > 0 ? Math.round((actualProduced / targetQty) * 100) : 0;
          
          return {
            orderItemId: item.id,
            productName: item.productName || item.product_name,
            category: item.category || item.productCategory || item.product_category || '',
            targetQuantity: targetQty,
            actualProduced,
            variance,
            achievementPct,
            unit: item.unit || 'قطعة',
            batchCount: matched?.batches?.length || 0,
          };
        });
        
        const unmatchedBatches = [...batchesByName.entries()].filter(([bKey]) => !matchedBatchKeys.has(bKey));
        
        for (const [, val] of unmatchedBatches) {
          const batch = val.batches[0];
          dailyProductionComparison.push({
            orderItemId: null,
            productName: batch.productName,
            category: batch.productCategory || '',
            targetQuantity: 0,
            actualProduced: val.totalProduced,
            variance: val.totalProduced,
            achievementPct: 0,
            unit: batch.unit || 'قطعة',
            batchCount: val.batches.length,
            isExtraProduction: true,
          });
        }
      }
      
      res.json({ ...result, schedules, dailyProductionComparison, comparisonScope });
    } catch (error) {
      console.error("Error fetching production order:", error);
      res.status(500).json({ error: "Failed to fetch production order" });
    }
  });

  // Create production order
  app.post("/api/advanced-production-orders", isAuthenticated, requirePermission("production", "create"), async (req, res) => {
    try {
      const { items, schedules, ...orderData } = req.body;
      
      // Generate order number
      const timestamp = Date.now().toString(36).toUpperCase();
      const random = Math.random().toString(36).substring(2, 6).toUpperCase();
      orderData.orderNumber = `PO-${timestamp}-${random}`;
      orderData.createdBy = (req as any).user?.id;
      
      const order = await storage.createAdvancedProductionOrder(orderData);
      
      // Create items if provided
      if (items && Array.isArray(items) && items.length > 0) {
        const itemsWithOrderId = items.map((item: any) => ({
          ...item,
          orderId: order.id
        }));
        await storage.bulkCreateProductionOrderItems(itemsWithOrderId);
        
        // Update order totals
        await storage.updateAdvancedProductionOrder(order.id, {
          totalItems: items.length,
          estimatedCost: items.reduce((sum: number, i: any) => sum + (i.totalValue || 0), 0)
        });
      }
      
      // Create schedules if provided
      if (schedules && Array.isArray(schedules) && schedules.length > 0) {
        const schedulesWithOrderId = schedules.map((s: any) => ({
          ...s,
          orderId: order.id
        }));
        await storage.bulkCreateProductionOrderSchedules(schedulesWithOrderId);
      }
      
      const result = await storage.getAdvancedProductionOrderWithItems(order.id);
      res.status(201).json(result);
    } catch (error: any) {
      console.error("Error creating production order:", error);
      console.error("Error details:", error?.message, error?.code, error?.detail);
      
      // Return detailed error message
      let errorMessage = "فشل في إنشاء أمر الإنتاج";
      if (error?.code === '23503') {
        errorMessage = "خطأ: المنتج أو الفرع غير موجود في قاعدة البيانات - " + (error?.detail || '');
      } else if (error?.code === '23505') {
        errorMessage = "خطأ: رقم الأمر مكرر";
      } else if (error?.message) {
        errorMessage = "خطأ: " + error.message;
      }
      
      console.error("Production order error:", error);
      res.status(500).json({ error: errorMessage });
    }
  });

  app.get("/api/advanced-production-orders/:id/mto-items", isAuthenticated, requirePermission("production", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) return res.status(400).json({ error: "Invalid order ID" });

      const result = await storage.getAdvancedProductionOrderWithItems(id);
      if (!result) return res.status(404).json({ error: "Order not found" });

      const order = result.order;

      if (!isUserAdmin(req)) {
        const hasSourceAccess = order.sourceBranchId ? await canAccessBranch(req, order.sourceBranchId) : false;
        const hasTargetAccess = order.targetBranchId ? await canAccessBranch(req, order.targetBranchId) : false;
        if (!hasSourceAccess && !hasTargetAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول" });
        }
      }

      if (order.mtoItems && Array.isArray(order.mtoItems) && (order.mtoItems as any[]).length > 0) {
        return res.json({ items: order.mtoItems, source: 'stored' });
      }

      const branchId = order.sourceBranchId;
      const salesData = await db.select().from(dailySalesData).where(eq(dailySalesData.branchId, branchId));

      if (!salesData || salesData.length === 0) {
        return res.json({ items: [], source: 'no_data' });
      }

      const productionItemNames = result.items.map((i: any) => (i.productName || '').trim().toLowerCase());
      
      const productAggregates = new Map<string, { totalQty: number; totalValue: number; count: number; category: string | null }>();
      salesData.forEach(sd => {
        const name = (sd.productName || '').trim();
        const key = name.toLowerCase();
        const existing = productAggregates.get(key) || { totalQty: 0, totalValue: 0, count: 0, category: null };
        existing.totalQty += (sd.quantitySold || 0);
        existing.totalValue += (sd.salesValue || 0);
        existing.count += 1;
        if (!existing.category && sd.productCategory) existing.category = sd.productCategory;
        productAggregates.set(key, existing);
      });

      const mtoItems: any[] = [];
      productAggregates.forEach((agg, key) => {
        const isInProduction = productionItemNames.some((pn: string) => {
          if (pn === key) return true;
          const pnNorm = pn.replace(/[-_\s]+/g, ' ').trim();
          const keyNorm = key.replace(/[-_\s]+/g, ' ').trim();
          return pnNorm === keyNorm || pnNorm.includes(keyNorm) || keyNorm.includes(pnNorm);
        });
        if (!isInProduction) {
          const displayName = salesData.find(sd => (sd.productName || '').trim().toLowerCase() === key)?.productName || key;
          const uniqueDays = new Set(salesData.filter(sd => (sd.productName || '').trim().toLowerCase() === key).map(sd => String(sd.salesDate))).size;
          const avgDailyQty = agg.count > 0 ? Math.ceil(agg.totalQty / Math.max(1, uniqueDays)) : 0;
          const avgDailyValue = agg.count > 0 ? Math.round(agg.totalValue / Math.max(1, uniqueDays)) : 0;

          const scalingFactor = order.targetSalesValue && agg.totalValue > 0 
            ? (order.targetSalesValue / (productAggregates.size > 0 ? Array.from(productAggregates.values()).reduce((s, v) => s + v.totalValue, 0) : 1))
            : 1;

          mtoItems.push({
            productName: displayName,
            productCategory: agg.category || 'غير محدد',
            forecastedQuantity: Math.ceil(avgDailyQty * scalingFactor),
            forecastedSalesAmount: Math.round(avgDailyValue * scalingFactor),
          });
        }
      });

      if (mtoItems.length > 0) {
        await db.update(advancedProductionOrders)
          .set({ mtoItems: mtoItems })
          .where(eq(advancedProductionOrders.id, id));
      }

      res.json({ items: mtoItems, source: 'calculated' });
    } catch (error) {
      console.error("Error getting MTO items:", error);
      res.status(500).json({ error: "فشل في جلب أصناف التحضير بعد الطلب" });
    }
  });

