  // Employee Schedules - جداول الموظفين
  app.get("/api/employee-schedules", isAuthenticated, requirePermission("shifts", "view"), async (req, res) => {
    try {
      const { periodId, employeeId, date, branchId, startDate, endDate } = req.query;
      
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const effectiveBranchId = branchFilter.singleBranchId;
      const allowedBranchIds = branchFilter.branchIds;
      
      if (periodId) {
        let schedules = await storage.getEmployeeSchedulesByPeriod(parseInt(periodId as string));
        // SECURITY: Filter by allowed branches to prevent cross-branch access
        if (allowedBranchIds !== null) {
          const allowedSet = new Set(allowedBranchIds);
          schedules = schedules.filter((s: any) => allowedSet.has(s.branchId));
        }
        return res.json(schedules);
      }
      if (employeeId) {
        let schedules = await storage.getEmployeeSchedulesByEmployee(
          employeeId as string,
          startDate as string,
          endDate as string
        );
        // SECURITY: Filter by allowed branches to prevent cross-branch access
        if (allowedBranchIds !== null) {
          const allowedSet = new Set(allowedBranchIds);
          schedules = schedules.filter((s: any) => allowedSet.has(s.branchId));
        }
        return res.json(schedules);
      }
      if (effectiveBranchId && startDate && endDate) {
        const schedules = await storage.getEmployeeSchedulesByBranchAndDateRange(
          effectiveBranchId,
          startDate as string,
          endDate as string
        );
        return res.json(schedules);
      }
      if (date) {
        let schedules = await storage.getEmployeeSchedulesByDate(date as string, effectiveBranchId ?? undefined);
        // SECURITY: Filter by allowed branches for multi-branch users without specific branch
        if (!effectiveBranchId && allowedBranchIds !== null) {
          const allowedSet = new Set(allowedBranchIds);
          schedules = schedules.filter((s: any) => allowedSet.has(s.branchId));
        }
        return res.json(schedules);
      }
      
      res.json([]);
    } catch (error) {
      console.error("Error fetching employee schedules:", error);
      res.status(500).json({ error: "فشل في جلب جداول الموظفين" });
    }
  });

