  // Attendance Records - سجلات الحضور
  app.get("/api/attendance", isAuthenticated, requirePermission("attendance", "view"), async (req, res) => {
    try {
      const { branchId, employeeId, startDate, endDate, status } = req.query;
      
      // SECURITY: Apply branch filter
      const queryBranchId = branchId as string | undefined;
      // HR is cross-branch by design: HR managers (and hr_management:view) get
      // READ access across all branches on this GET, matching the HR Hub bundle.
      let branchFilter = getEffectiveBranchFilter(req, queryBranchId);
      if (hasCrossBranchHrReadAccess(req)) {
        branchFilter = { ...branchFilter, hasAccess: true, singleBranchId: queryBranchId || null, branchIds: null };
      }

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      const filters: any = {};
      if (branchFilter.singleBranchId) filters.branchId = branchFilter.singleBranchId;
      if (employeeId) filters.employeeId = employeeId;
      if (startDate) filters.startDate = startDate;
      if (endDate) filters.endDate = endDate;
      if (status) filters.status = status;
      
      let records = await storage.getAllAttendanceRecords(filters);
      
      // SECURITY: For multi-branch users without a specific branchId filter,
      // branchFilter.singleBranchId is null but branchIds contains the allowed list.
      // We must filter records to only include allowed branches.
      if (branchFilter.branchIds !== null && !branchFilter.singleBranchId) {
        const allowedSet = new Set(branchFilter.branchIds);
        records = records.filter((r: any) => allowedSet.has(r.branchId));
      }
      
      res.json(records);
    } catch (error) {
      console.error("Error fetching attendance records:", error);
      res.status(500).json({ error: "فشل في جلب سجلات الحضور" });
    }
  });

