  // Check-in / Check-out with signature
  // ============ Biometric / WebAuthn Endpoints ============
  
  // In-memory challenge store with TTL (5 minutes)
  const biometricChallenges = new Map<string, { challenge: string; employeeId: string; branchId?: string; type: string; timestamp: number }>();
  setInterval(() => {
    const now = Date.now();
    const keys = Array.from(biometricChallenges.keys());
    for (const key of keys) {
      const val = biometricChallenges.get(key);
      if (val && now - val.timestamp > 10 * 60 * 1000) biometricChallenges.delete(key);
    }
  }, 60000);

  // Get biometric registration options (challenge) for an employee
  app.post("/api/biometric/register-options", biometricRateLimiter, isAuthenticated, requirePermission("attendance_check", "create"), async (req, res) => {
    try {
      const { employeeId, employeeName, branchId } = req.body;
      if (!employeeId || !employeeName || !branchId) {
        return res.status(400).json({ error: "بيانات الموظف مطلوبة" });
      }

      // SECURITY: Branch isolation check
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
        }
      }

      const crypto = await import("crypto");
      const challenge = crypto.randomBytes(32).toString("base64url");
      const stableUserId = crypto.createHash("sha256").update(`butter-employee-${employeeId}-${branchId}`).digest().slice(0, 16);
      const userIdBase64 = stableUserId.toString("base64url");
      
      const challengeKey = `reg_${employeeId}_${Date.now()}`;
      biometricChallenges.set(challengeKey, { challenge, employeeId, type: "register", timestamp: Date.now() });

      const origin = req.headers.origin || `https://${req.headers.host}`;
      let rpId: string;
      try {
        rpId = new URL(origin).hostname;
      } catch {
        rpId = req.headers.host?.split(':')[0] || "localhost";
      }

      const existingCreds = await pool.query(
        `SELECT credential_id FROM biometric_credentials WHERE employee_id = $1 AND branch_id = $2 AND is_active = true`,
        [String(employeeId), branchId]
      );
      const excludeCredentials = existingCreds.rows.map((row: any) => ({
        id: row.credential_id,
        type: "public-key",
        transports: ["internal"],
      }));

      const options = {
        challenge,
        rp: { name: "باتر - نظام الحضور", id: rpId },
        user: { id: userIdBase64, name: `${employeeName} (${employeeId})`, displayName: employeeName },
        pubKeyCredParams: [
          { alg: -7, type: "public-key" },
          { alg: -257, type: "public-key" },
        ],
        authenticatorSelection: {
          userVerification: "required",
          residentKey: "required",
          requireResidentKey: true,
        },
        excludeCredentials,
        timeout: 120000,
        attestation: "none",
      };

      res.json({ options, challengeKey });
    } catch (error) {
      console.error("Error generating biometric options:", error);
      res.status(500).json({ error: "فشل في إنشاء خيارات البصمة" });
    }
  });

  // Register biometric credential for an employee
  app.post("/api/biometric/register", biometricRateLimiter, isAuthenticated, requirePermission("attendance_check", "create"), async (req, res) => {
    try {
      const { employeeId, employeeName, branchId, credentialId, publicKey, deviceInfo, challengeKey, deviceType, deviceModel, registrationMethod, registeredByName } = req.body;
      const currentUser = getCurrentUser(req);

      if (!employeeId || !employeeName || !branchId || !credentialId || !publicKey) {
        return res.status(400).json({ error: "جميع البيانات مطلوبة" });
      }

      // SECURITY: Branch isolation check
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
        }
      }
      
      // SECURITY: Validate challenge was issued by server (REQUIRED - prevents replay attacks)
      if (!challengeKey) {
        return res.status(400).json({ error: "مفتاح التسجيل مطلوب" });
      }
      const storedChallenge = biometricChallenges.get(challengeKey);
      if (!storedChallenge || storedChallenge.employeeId !== employeeId || storedChallenge.type !== "register") {
        return res.status(400).json({ error: "طلب التسجيل غير صالح أو منتهي الصلاحية" });
      }
      const challengeAge = Date.now() - storedChallenge.timestamp;
      if (challengeAge > 5 * 60 * 1000) {
        biometricChallenges.delete(challengeKey);
        return res.status(400).json({ error: "انتهت صلاحية طلب التسجيل، يرجى المحاولة مجدداً" });
      }
      biometricChallenges.delete(challengeKey);

      // Check if credential already exists
      const existing = await storage.getBiometricCredentialByCredentialId(credentialId);
      if (existing) {
        return res.status(400).json({ error: "هذه البصمة مسجلة مسبقاً" });
      }

      const validMethods = ["fingerprint", "face"];
      const validDeviceTypes = ["mobile_android", "mobile_ios", "tablet", "desktop"];

      const credential = await storage.createBiometricCredential({
        employeeId,
        employeeName,
        branchId,
        credentialId,
        publicKey,
        counter: 0,
        deviceInfo: deviceInfo || null,
        deviceType: validDeviceTypes.includes(deviceType) ? deviceType : null,
        deviceModel: deviceModel || null,
        registrationMethod: validMethods.includes(registrationMethod) ? registrationMethod : "fingerprint",
        registeredBy: currentUser?.id || null,
        registeredByName: registeredByName || [currentUser?.firstName, currentUser?.lastName].filter(Boolean).join(' ') || currentUser?.username || null,
        isActive: true,
      });

      res.json({ success: true, credential });
    } catch (error) {
      console.error("Error registering biometric:", error);
      res.status(500).json({ error: "فشل في تسجيل البصمة" });
    }
  });

  // Get verification options (challenge) for biometric verification
  app.post("/api/biometric/verify-options", biometricRateLimiter, isAuthenticated, async (req, res) => {
    try {
      const { employeeId, branchId, discoverMode } = req.body;

      const crypto = await import("crypto");
      const challenge = crypto.randomBytes(32).toString("base64url");
      const rpId = (req.headers.origin ? new URL(req.headers.origin).hostname : req.headers.host?.split(':')[0]) || "localhost";

      if (discoverMode && branchId) {
        const challengeKey = `verify_discover_${branchId}_${Date.now()}`;
        biometricChallenges.set(challengeKey, { challenge, employeeId: "discover", branchId, type: "verify_discover", timestamp: Date.now() });

        const options = {
          challenge,
          rpId,
          allowCredentials: [],
          userVerification: "required",
          timeout: 60000,
        };

        return res.json({ options, challengeKey, registrationMethod: "fingerprint", discoverMode: true });
      }

      if (!employeeId) {
        return res.status(400).json({ error: "معرف الموظف مطلوب" });
      }

      const credentials = await storage.getBiometricCredentials(employeeId);
      if (credentials.length === 0) {
        return res.status(404).json({ error: "لا توجد بصمة مسجلة لهذا الموظف", noBiometric: true });
      }

      const primaryMethod = credentials[0].registrationMethod || "fingerprint";
      
      const challengeKey = `verify_${employeeId}_${Date.now()}`;
      biometricChallenges.set(challengeKey, { challenge, employeeId, type: "verify", timestamp: Date.now() });

      const options = {
        challenge,
        rpId,
        allowCredentials: credentials.map(c => ({
          id: c.credentialId,
          type: "public-key",
          transports: ["internal"],
        })),
        userVerification: "required",
        timeout: 60000,
      };

      res.json({ options, challengeKey, registrationMethod: primaryMethod });
    } catch (error) {
      console.error("Error generating verify options:", error);
      res.status(500).json({ error: "فشل في إنشاء خيارات التحقق" });
    }
  });

  // Verify biometric credential - returns a server-signed verification token
  app.post("/api/biometric/verify", biometricRateLimiter, isAuthenticated, async (req, res) => {
    try {
      const { credentialId, employeeId, challengeKey } = req.body;
      if (!credentialId) {
        return res.status(400).json({ error: "بيانات التحقق مطلوبة" });
      }
      
      if (!challengeKey) {
        return res.status(400).json({ error: "مفتاح التحقق مطلوب", verified: false });
      }
      const storedChallenge = biometricChallenges.get(challengeKey);
      if (!storedChallenge) {
        return res.status(400).json({ error: "طلب التحقق غير صالح أو منتهي الصلاحية", verified: false });
      }

      const isDiscoverMode = storedChallenge.type === "verify_discover";
      if (!isDiscoverMode && (!employeeId || storedChallenge.employeeId !== employeeId || storedChallenge.type !== "verify")) {
        return res.status(400).json({ error: "طلب التحقق غير صالح أو منتهي الصلاحية", verified: false });
      }

      const challengeAge = Date.now() - storedChallenge.timestamp;
      if (challengeAge > 5 * 60 * 1000) {
        biometricChallenges.delete(challengeKey);
        return res.status(400).json({ error: "انتهت صلاحية طلب التحقق، يرجى المحاولة مجدداً", verified: false });
      }
      biometricChallenges.delete(challengeKey);

      const credential = await storage.getBiometricCredentialByCredentialId(credentialId);
      if (!credential) {
        return res.status(400).json({ error: "البصمة غير مسجلة", verified: false });
      }

      if (isDiscoverMode) {
        const challengeBranchId = (storedChallenge as any).branchId;
        if (challengeBranchId && credential.branchId !== challengeBranchId) {
          return res.status(403).json({ error: "البصمة مسجلة في فرع آخر", verified: false });
        }
      } else if (credential.employeeId !== employeeId) {
        return res.status(403).json({ error: "البصمة لا تتطابق مع الموظف", verified: false });
      }

      const resolvedEmployeeId = isDiscoverMode ? credential.employeeId : employeeId;

      await storage.updateBiometricCredentialCounter(credential.id, credential.counter + 1);
      
      const crypto = await import("crypto");
      const tokenData = `${resolvedEmployeeId}:${Date.now()}:${crypto.randomBytes(8).toString("hex")}`;
      const verificationToken = Buffer.from(tokenData).toString("base64url");
      
      biometricChallenges.set(`token_${verificationToken}`, { 
        challenge: verificationToken, employeeId: resolvedEmployeeId, type: "verified_token", timestamp: Date.now() 
      });

      res.json({ 
        verified: true, 
        employeeId: resolvedEmployeeId,
        employeeName: credential.employeeName, 
        verificationToken,
        registrationMethod: credential.registrationMethod || "fingerprint",
        discoverMode: isDiscoverMode,
      });
    } catch (error) {
      console.error("Error verifying biometric:", error);
      res.status(500).json({ error: "فشل في التحقق من البصمة", verified: false });
    }
  });

  // Get biometric status for employees in a branch
  app.get("/api/biometric/branch/:branchId", isAuthenticated, async (req, res) => {
    try {
      // SECURITY: Branch isolation check
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, req.params.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
        }
      }

      const credentials = await storage.getBiometricCredentialsByBranch(req.params.branchId);
      const statusMap: Record<string, { hasCredential: boolean; hasPin: boolean; credentialCount: number; lastUsed: string | null; registrationMethod: string | null }> = {};
      
      for (const cred of credentials) {
        if (!statusMap[cred.employeeId]) {
          statusMap[cred.employeeId] = { hasCredential: true, hasPin: false, credentialCount: 0, lastUsed: null, registrationMethod: null };
        }
        statusMap[cred.employeeId].credentialCount++;
        if (cred.registrationMethod === "pin") {
          statusMap[cred.employeeId].hasPin = true;
        }
        if (!statusMap[cred.employeeId].registrationMethod && cred.registrationMethod) {
          statusMap[cred.employeeId].registrationMethod = cred.registrationMethod;
        }
        if (cred.lastUsedAt) {
          const lastUsed = cred.lastUsedAt.toISOString();
          if (!statusMap[cred.employeeId].lastUsed || lastUsed > statusMap[cred.employeeId].lastUsed!) {
            statusMap[cred.employeeId].lastUsed = lastUsed;
          }
        }
      }
      
      res.json(statusMap);
    } catch (error) {
      console.error("Error getting biometric status:", error);
      res.status(500).json({ error: "فشل في جلب حالة البصمات" });
    }
  });

  // Delete biometric credential
  app.delete("/api/biometric/:id", isAuthenticated, requirePermission("attendance_check", "delete"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const success = await storage.deleteBiometricCredential(id);
      if (!success) {
        return res.status(404).json({ error: "البصمة غير موجودة" });
      }
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting biometric:", error);
      res.status(500).json({ error: "فشل في حذف البصمة" });
    }
  });

  // ============ End Biometric Endpoints ============

  // Biometric Settings Admin APIs - إعدادات البصمة للمسؤول
  const VALID_REGISTRATION_METHODS = ["fingerprint", "face"];
  const VALID_DEVICE_TYPES = ["mobile_android", "mobile_ios", "tablet", "desktop"];

  async function verifyBiometricOwnership(credentialId: number, req: any): Promise<{ credential: any; error?: string }> {
    const currentUser = getCurrentUser(req);
    const [credential] = await db.select({
      id: biometricCredentials.id,
      employeeId: biometricCredentials.employeeId,
      employeeName: biometricCredentials.employeeName,
      branchId: biometricCredentials.branchId,
      credentialId: biometricCredentials.credentialId,
      publicKey: biometricCredentials.publicKey,
      counter: biometricCredentials.counter,
      deviceInfo: biometricCredentials.deviceInfo,
      registeredBy: biometricCredentials.registeredBy,
      isActive: biometricCredentials.isActive,
      lastUsedAt: biometricCredentials.lastUsedAt,
      createdAt: biometricCredentials.createdAt,
      deviceType: biometricCredentials.deviceType,
      deviceModel: biometricCredentials.deviceModel,
      registrationMethod: biometricCredentials.registrationMethod,
      registeredByName: biometricCredentials.registeredByName,
      deactivatedAt: biometricCredentials.deactivatedAt,
      deactivatedBy: biometricCredentials.deactivatedBy,
      deactivationReason: biometricCredentials.deactivationReason,
      usageCount: biometricCredentials.usageCount,
    }).from(biometricCredentials).where(eq(biometricCredentials.id, credentialId));
    if (!credential) return { credential: null, error: "البصمة غير موجودة" };
    if (!isUserAdmin(req)) {
      const hasAccess = await canAccessBranch(req, credential.branchId);
      if (!hasAccess) {
        return { credential: null, error: "لا يمكنك تعديل بصمات فرع آخر" };
      }
    }
    return { credential };
  }

  function parseDeviceFromUA(ua: string | null): { type: string; model: string; os: string; browser: string } {
    if (!ua) return { type: "unknown", model: "غير معروف", os: "غير معروف", browser: "غير معروف" };
    let type = "desktop";
    let model = "غير معروف";
    let os = "غير معروف";
    let browser = "غير معروف";
    if (/iPad/i.test(ua)) { type = "tablet"; model = "iPad"; }
    else if (/iPhone/i.test(ua)) { type = "mobile_ios"; model = "iPhone"; }
    else if (/Android/i.test(ua) && /Mobile/i.test(ua)) { type = "mobile_android"; const m = ua.match(/;\s*([^;)]+)\s*Build/); model = m ? m[1].trim() : "Android"; }
    else if (/Android/i.test(ua)) { type = "tablet"; model = "Android Tablet"; }
    else if (/Mac/i.test(ua)) { model = "Mac"; }
    else if (/Windows/i.test(ua)) { model = "Windows PC"; }
    if (/iPhone OS (\d+[_\d]*)/i.test(ua)) os = "iOS " + ua.match(/iPhone OS (\d+[_\d]*)/i)![1].replace(/_/g, ".");
    else if (/CPU OS (\d+[_\d]*)/i.test(ua)) os = "iPadOS " + ua.match(/CPU OS (\d+[_\d]*)/i)![1].replace(/_/g, ".");
    else if (/Android (\d+[\.\d]*)/i.test(ua)) os = "Android " + ua.match(/Android (\d+[\.\d]*)/i)![1];
    else if (/Mac OS X/i.test(ua)) os = "macOS";
    else if (/Windows NT/i.test(ua)) os = "Windows";
    if (/CriOS/i.test(ua)) browser = "Chrome (iOS)";
    else if (/Chrome\/(\d+)/i.test(ua) && !/Edg/i.test(ua)) browser = "Chrome " + ua.match(/Chrome\/(\d+)/i)![1];
    else if (/Safari/i.test(ua) && !/Chrome/i.test(ua)) browser = "Safari";
    else if (/Edg/i.test(ua)) browser = "Edge";
    else if (/Firefox/i.test(ua)) browser = "Firefox";
    return { type, model, os, browser };
  }

  app.get("/api/biometric-settings/branch/:branchId", isAuthenticated, requirePermission("biometric_settings", "view"), async (req, res) => {
    try {
      const { branchId } = req.params;
      const currentUser = getCurrentUser(req);
      
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "لا يمكنك عرض بيانات فرع آخر" });
        }
      }

      const branchEmps = await db.select().from(branchEmployees).where(
        and(eq(branchEmployees.branchId, branchId), eq(branchEmployees.status, "active"))
      ).orderBy(branchEmployees.employeeName);

      const seenNames = new Set<string>();
      const allEmployeeEntries: Array<{ id: number; employeeName: string; employeeNumber?: string; jobTitle?: string; position?: string; source: string }> = [];

      for (const emp of branchEmps) {
        const nameKey = emp.employeeName.trim().toLowerCase();
        if (seenNames.has(nameKey)) continue;
        seenNames.add(nameKey);
        allEmployeeEntries.push({
          id: emp.id,
          employeeName: emp.employeeName,
          employeeNumber: emp.employeeNumber || undefined,
          jobTitle: emp.jobTitle || undefined,
          position: emp.jobTitle || undefined,
          source: "branch_employee",
        });
      }

      const credentials = await db.select({
        id: biometricCredentials.id,
        employeeId: biometricCredentials.employeeId,
        employeeName: biometricCredentials.employeeName,
        branchId: biometricCredentials.branchId,
        credentialId: biometricCredentials.credentialId,
        publicKey: biometricCredentials.publicKey,
        counter: biometricCredentials.counter,
        deviceInfo: biometricCredentials.deviceInfo,
        registeredBy: biometricCredentials.registeredBy,
        isActive: biometricCredentials.isActive,
        lastUsedAt: biometricCredentials.lastUsedAt,
        createdAt: biometricCredentials.createdAt,
        deviceType: biometricCredentials.deviceType,
        deviceModel: biometricCredentials.deviceModel,
        registrationMethod: biometricCredentials.registrationMethod,
        registeredByName: biometricCredentials.registeredByName,
        deactivatedAt: biometricCredentials.deactivatedAt,
        deactivatedBy: biometricCredentials.deactivatedBy,
        deactivationReason: biometricCredentials.deactivationReason,
        usageCount: biometricCredentials.usageCount,
      }).from(biometricCredentials).where(
        eq(biometricCredentials.branchId, branchId)
      );

      const allEmpIds = allEmployeeEntries.map(e => `branch_emp_${e.id}`);
      const attendanceStats = await pool.query(
        `SELECT employee_id, 
          COUNT(*) as total_attendance,
          COUNT(CASE WHEN biometric_verified = true THEN 1 END) as biometric_attendance,
          COUNT(CASE WHEN status = 'on_time' THEN 1 END) as on_time_count,
          COUNT(CASE WHEN status = 'late' THEN 1 END) as late_count,
          MAX(attendance_date) as last_attendance_date,
          MAX(CASE WHEN actual_check_in IS NOT NULL THEN created_at END) as last_check_in_time
        FROM attendance_records 
        WHERE branch_id = $1 AND employee_id = ANY($2)
        GROUP BY employee_id`,
        [branchId, allEmpIds]
      );
      const attendanceMap = new Map<string, any>();
      for (const row of attendanceStats.rows) {
        attendanceMap.set(row.employee_id, row);
      }

      const lastAttendanceDetails = await pool.query(
        `SELECT DISTINCT ON (employee_id) employee_id, attendance_date, actual_check_in, actual_check_out, 
          location_info, device_info, biometric_verified, status
        FROM attendance_records 
        WHERE branch_id = $1 AND employee_id = ANY($2)
        ORDER BY employee_id, created_at DESC`,
        [branchId, allEmpIds]
      );
      const lastAttendanceMap = new Map<string, any>();
      for (const row of lastAttendanceDetails.rows) {
        lastAttendanceMap.set(row.employee_id, row);
      }

      const registeredByIds = credentials.map(c => c.registeredBy).filter(Boolean);
      const registeredByUsers = registeredByIds.length > 0 
        ? await pool.query(`SELECT id, username, first_name, last_name FROM users WHERE id = ANY($1)`, [registeredByIds])
        : { rows: [] };
      const userMap = new Map<string, string>();
      for (const u of registeredByUsers.rows) {
        userMap.set(String(u.id), `${u.first_name || ''} ${u.last_name || ''}`.trim() || u.username || String(u.id));
      }

      const credentialMap = new Map<string, typeof credentials>();
      for (const cred of credentials) {
        const key = cred.employeeId;
        if (!credentialMap.has(key)) credentialMap.set(key, []);
        credentialMap.get(key)!.push(cred);
      }

      const nameCredentialMap = new Map<string, typeof credentials>();
      for (const cred of credentials) {
        const nameKey = (cred.employeeName || "").trim().toLowerCase();
        if (nameKey) {
          if (!nameCredentialMap.has(nameKey)) nameCredentialMap.set(nameKey, []);
          nameCredentialMap.get(nameKey)!.push(cred);
        }
      }

      const result = allEmployeeEntries.map(emp => {
        const idStr = String(emp.id);
        const branchEmpId = `branch_emp_${idStr}`;
        const empCredentials = credentialMap.get(idStr)
          || credentialMap.get(branchEmpId)
          || nameCredentialMap.get((emp.employeeName || "").trim().toLowerCase())
          || [];
        const activeCredentials = empCredentials.filter((c: any) => c.isActive);
        const attStats = attendanceMap.get(branchEmpId);
        const lastAtt = lastAttendanceMap.get(branchEmpId);
        return {
          employee: emp,
          biometricStatus: activeCredentials.length > 0 ? "registered" : "not_registered",
          credentials: empCredentials.map(c => {
            const parsed = parseDeviceFromUA(c.deviceInfo);
            const resolvedDeviceType = c.deviceType || parsed.type;
            const resolvedDeviceModel = c.deviceModel || parsed.model;
            return {
              id: c.id,
              registrationMethod: c.registrationMethod || "fingerprint",
              deviceType: resolvedDeviceType,
              deviceModel: resolvedDeviceModel,
              deviceOS: parsed.os,
              deviceBrowser: parsed.browser,
              deviceInfo: c.deviceInfo,
              isActive: c.isActive,
              registeredByName: c.registeredByName || userMap.get(String(c.registeredBy)) || null,
              registeredById: c.registeredBy,
              lastUsedAt: c.lastUsedAt,
              usageCount: c.usageCount || 0,
              deactivatedAt: c.deactivatedAt,
              deactivatedBy: c.deactivatedBy,
              deactivationReason: c.deactivationReason,
              createdAt: c.createdAt,
            };
          }),
          totalCredentials: empCredentials.length,
          activeCredentials: activeCredentials.length,
          attendanceStats: attStats ? {
            totalAttendance: parseInt(attStats.total_attendance) || 0,
            biometricAttendance: parseInt(attStats.biometric_attendance) || 0,
            onTimeCount: parseInt(attStats.on_time_count) || 0,
            lateCount: parseInt(attStats.late_count) || 0,
            lastAttendanceDate: attStats.last_attendance_date,
          } : null,
          lastAttendance: lastAtt ? {
            date: lastAtt.attendance_date,
            checkIn: lastAtt.actual_check_in,
            checkOut: lastAtt.actual_check_out,
            locationInfo: lastAtt.location_info,
            deviceInfo: lastAtt.device_info,
            biometricVerified: lastAtt.biometric_verified,
            status: lastAtt.status,
          } : null,
        };
      });

      res.json(result);
    } catch (error) {
      console.error("Error getting biometric settings:", error);
      res.status(500).json({ error: "فشل في جلب إعدادات البصمة" });
    }
  });

  app.patch("/api/biometric-settings/:id/toggle", isAuthenticated, requirePermission("biometric_settings", "change_status"), async (req, res) => {
    try {
      const currentUser = getCurrentUser(req);

      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const { credential: existingCred, error: ownershipError } = await verifyBiometricOwnership(id, req);
      if (ownershipError) return res.status(existingCred ? 403 : 404).json({ error: ownershipError });

      const { isActive, reason } = req.body;
      if (typeof isActive !== "boolean") return res.status(400).json({ error: "قيمة التفعيل مطلوبة" });
      if (reason && typeof reason !== "string") return res.status(400).json({ error: "السبب يجب أن يكون نصاً" });

      const updateData: any = { isActive };
      if (!isActive) {
        updateData.deactivatedAt = new Date();
        updateData.deactivatedBy = currentUser.id;
        updateData.deactivationReason = reason || "تعطيل بواسطة المسؤول";
      } else {
        updateData.deactivatedAt = null;
        updateData.deactivatedBy = null;
        updateData.deactivationReason = null;
      }

      const allowedCols = new Set(['is_active', 'deactivated_at', 'deactivated_by', 'deactivation_reason']);
      const setClauses: string[] = [];
      const setValues: any[] = [];
      let paramIdx = 1;
      for (const [key, val] of Object.entries(updateData)) {
        const col = key.replace(/([A-Z])/g, '_$1').toLowerCase();
        if (!allowedCols.has(col)) continue;
        setClauses.push(`${col} = $${paramIdx++}`);
        setValues.push(val);
      }
      setValues.push(id);
      const updateResult = await pool.query(
        `UPDATE biometric_credentials SET ${setClauses.join(', ')} WHERE id = $${paramIdx} RETURNING id, employee_id, employee_name, branch_id, credential_id, is_active, device_type, device_model, registration_method, deactivated_at, deactivated_by, deactivation_reason`,
        setValues
      );
      const updated = updateResult.rows[0];

      res.json({ success: true, credential: updated });
    } catch (error) {
      console.error("Error toggling biometric:", error);
      res.status(500).json({ error: "فشل في تعديل حالة البصمة" });
    }
  });

  app.patch("/api/biometric-settings/:id/update", isAuthenticated, requirePermission("biometric_settings", "edit"), async (req, res) => {
    try {
      const currentUser = getCurrentUser(req);

      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const { credential: existingCred, error: ownershipError } = await verifyBiometricOwnership(id, req);
      if (ownershipError) return res.status(existingCred ? 403 : 404).json({ error: ownershipError });

      const { registrationMethod, deviceType, deviceModel } = req.body;

      if (registrationMethod && !VALID_REGISTRATION_METHODS.includes(registrationMethod)) {
        return res.status(400).json({ error: "نوع التسجيل غير صالح. القيم المتاحة: fingerprint, face" });
      }
      if (deviceType && !VALID_DEVICE_TYPES.includes(deviceType)) {
        return res.status(400).json({ error: "نوع الجهاز غير صالح" });
      }
      if (deviceModel && (typeof deviceModel !== "string" || deviceModel.length > 100)) {
        return res.status(400).json({ error: "موديل الجهاز غير صالح" });
      }

      const setClauses2: string[] = [];
      const setValues2: any[] = [];
      let pIdx = 1;
      if (registrationMethod) { setClauses2.push(`registration_method = $${pIdx++}`); setValues2.push(registrationMethod); }
      if (deviceType !== undefined) { setClauses2.push(`device_type = $${pIdx++}`); setValues2.push(deviceType); }
      if (deviceModel !== undefined) { setClauses2.push(`device_model = $${pIdx++}`); setValues2.push(deviceModel); }

      if (setClauses2.length === 0) return res.status(400).json({ error: "لا توجد بيانات للتحديث" });

      setValues2.push(id);
      const updateResult2 = await pool.query(
        `UPDATE biometric_credentials SET ${setClauses2.join(', ')} WHERE id = $${pIdx} RETURNING id, employee_id, employee_name, branch_id, credential_id, is_active, device_type, device_model, registration_method`,
        setValues2
      );
      const updated = updateResult2.rows[0];

      res.json({ success: true, credential: updated });
    } catch (error) {
      console.error("Error updating biometric settings:", error);
      res.status(500).json({ error: "فشل في تحديث إعدادات البصمة" });
    }
  });

