  // Check-in employee by manager or attendance clerk
  app.post("/api/attendance/check-in-employee", isAuthenticated, requirePermission("attendance_check", "create"), async (req, res) => {
    try {

      const { employeeId, branchId, signature, scheduleId, scheduledStartTime, scheduledEndTime, employeeName, userLatitude, userLongitude, attendanceDate, biometricVerified } = req.body;
      
      if (!employeeId || !branchId) {
        return res.status(400).json({ error: "معرف الموظف والفرع مطلوبين" });
      }
      
      // SECURITY: Input format validation
      if (typeof employeeId !== 'string' || employeeId.length > 200) {
        return res.status(400).json({ error: "معرف الموظف غير صالح" });
      }
      if (typeof branchId !== 'string' || branchId.length > 100) {
        return res.status(400).json({ error: "معرف الفرع غير صالح" });
      }
      
      // Validate attendanceDate: only today or yesterday allowed (Saudi time)
      if (attendanceDate) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(attendanceDate)) {
          return res.status(400).json({ error: "صيغة التاريخ غير صالحة" });
        }
        const saudiToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
        const yesterdayDate = new Date();
        yesterdayDate.setDate(yesterdayDate.getDate() - 1);
        const saudiYesterday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(yesterdayDate);
        if (attendanceDate !== saudiToday && attendanceDate !== saudiYesterday) {
          return res.status(400).json({ error: "يسمح فقط بتاريخ اليوم أو الأمس" });
        }
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بتسجيل حضور موظفي هذا الفرع" });
        }
      }
      
      // SECURITY: Validate branch exists (application-level FK replacement)
      const [branch] = await db.select().from(branches).where(eq(branches.id, branchId));
      if (!branch) {
        return res.status(400).json({ error: "الفرع غير موجود" });
      }
      
      // SECURITY: Server-side geolocation verification
      if (branch && branch.latitude && branch.longitude) {
        if (!userLatitude || !userLongitude) {
          return res.status(400).json({ error: "الموقع الجغرافي مطلوب للتحقق من موقع الفرع" });
        }
        
        // Calculate distance using Haversine formula
        const R = 6371e3; // Earth radius in meters
        const lat1 = branch.latitude * Math.PI / 180;
        const lat2 = userLatitude * Math.PI / 180;
        const deltaLat = (userLatitude - branch.latitude) * Math.PI / 180;
        const deltaLon = (userLongitude - branch.longitude) * Math.PI / 180;
        
        const a = Math.sin(deltaLat / 2) * Math.sin(deltaLat / 2) +
                  Math.cos(lat1) * Math.cos(lat2) *
                  Math.sin(deltaLon / 2) * Math.sin(deltaLon / 2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        const distance = R * c; // Distance in meters
        
        const allowedRadius = branch.locationRadius || 200;
        if (distance > allowedRadius) {
          return res.status(403).json({ 
            error: `الموقع خارج النطاق المسموح (${Math.round(distance)} متر من الفرع، المسموح: ${allowedRadius} متر)` 
          });
        }
      }

      if (!signature || signature.length < 100) {
        return res.status(400).json({ error: "التوقيع مطلوب لتسجيل الحضور" });
      }

      if (signature.length > 500000) {
        return res.status(400).json({ error: "حجم التوقيع كبير جداً" });
      }

      let serverBiometricVerified = false;
      const biometricTokenValue = req.body.biometricToken;

      if (biometricVerified && biometricTokenValue) {
        const tokenKey = `token_${biometricTokenValue}`;
        const tokenData = biometricChallenges.get(tokenKey);

        if (tokenData && tokenData.employeeId === employeeId && tokenData.type === "verified_token") {
          const tokenAge = Date.now() - tokenData.timestamp;

          if (tokenAge < 10 * 60 * 1000) {
            serverBiometricVerified = true;
            biometricChallenges.delete(tokenKey);
          }
        }
      }

      const saudiToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
      const targetDate = attendanceDate || saudiToday;
      const existingRecord = await storage.getAttendanceByEmployeeAndDate(employeeId, targetDate);
      if (existingRecord && existingRecord.actualCheckIn) {
        return res.status(400).json({ error: "تم تسجيل حضور هذا الموظف مسبقاً اليوم" });
      }
      
      let record;
      try {
        record = await storage.checkInEmployee(employeeId, branchId, signature, scheduleId, scheduledStartTime, scheduledEndTime, employeeName, targetDate);
      } catch (checkInError: any) {
        console.error("[Check-in] checkInEmployee failed:", checkInError?.message || checkInError);
        if (checkInError?.message?.includes('مسبقاً') || checkInError?.message?.includes('لا ينتمي') || checkInError?.message?.includes('غير نشط')) {
          return res.status(400).json({ error: checkInError.message });
        }
        return res.status(500).json({ error: "فشل في تسجيل الحضور" });
      }
      
      if (record && record.id && serverBiometricVerified) {
        try {
          await storage.updateAttendanceRecord(record.id, { biometricVerified: true, biometricCheckIn: true });
        } catch (updateError: any) {
          console.error("[Check-in] updateAttendanceRecord biometric failed:", updateError?.message || updateError);
        }
      }
      
      res.status(201).json({ ...record, biometricVerified: serverBiometricVerified });
    } catch (error: any) {
      console.error("[Check-in] Unexpected error:", error?.message || error, error?.stack);
      res.status(500).json({ error: "فشل في تسجيل الحضور" });
    }
  });

  // Check-out employee by manager or attendance clerk
  app.post("/api/attendance/check-out-employee", isAuthenticated, requirePermission("attendance_check", "edit"), async (req, res) => {
    try {
      const { employeeId, scheduleId, signature, attendanceDate, biometricVerified } = req.body;
      
      if (!employeeId) {
        return res.status(400).json({ error: "معرف الموظف مطلوب" });
      }
      
      // SECURITY: Input format validation
      if (typeof employeeId !== 'string' || employeeId.length > 200) {
        return res.status(400).json({ error: "معرف الموظف غير صالح" });
      }
      
      // Validate attendanceDate: only today or yesterday allowed (Saudi time)
      if (attendanceDate) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(attendanceDate)) {
          return res.status(400).json({ error: "صيغة التاريخ غير صالحة" });
        }
        const saudiToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
        const yesterdayDate = new Date();
        yesterdayDate.setDate(yesterdayDate.getDate() - 1);
        const saudiYesterday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(yesterdayDate);
        if (attendanceDate !== saudiToday && attendanceDate !== saudiYesterday) {
          return res.status(400).json({ error: "يسمح فقط بتاريخ اليوم أو الأمس" });
        }
      }
      
      // SECURITY: Verify branch access for non-admin users based on employee's branch
      const saudiToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
      const targetDate = attendanceDate || saudiToday;
      const existingRecord = await storage.getAttendanceByEmployeeAndDate(employeeId, targetDate);
      
      if (!existingRecord) {
        return res.status(404).json({ error: "لم يتم تسجيل حضور هذا الموظف في هذا التاريخ" });
      }
      
      if (existingRecord.actualCheckOut) {
        return res.status(400).json({ error: "تم تسجيل انصراف هذا الموظف بالفعل اليوم" });
      }
      
      if (!isUserAdmin(req)) {
        if (existingRecord.branchId) {
          const hasAccess = await canAccessBranch(req, existingRecord.branchId);
          if (!hasAccess) {
            return res.status(403).json({ error: "غير مصرح بتسجيل انصراف موظفي هذا الفرع" });
          }
        }
      }

      if (!signature || signature.length < 100) {
        return res.status(400).json({ error: "التوقيع مطلوب لتسجيل الانصراف" });
      }

      if (signature.length > 500000) {
        return res.status(400).json({ error: "حجم التوقيع كبير جداً" });
      }

      let serverBiometricVerified = false;
      const biometricTokenValue = req.body.biometricToken;

      if (biometricVerified && biometricTokenValue) {
        const tokenKey = `token_${biometricTokenValue}`;
        const tokenData = biometricChallenges.get(tokenKey);

        if (tokenData && tokenData.employeeId === employeeId && tokenData.type === "verified_token") {
          const tokenAge = Date.now() - tokenData.timestamp;

          if (tokenAge < 10 * 60 * 1000) {
            serverBiometricVerified = true;
            biometricChallenges.delete(tokenKey);
          }
        }
      }
      
      let record;
      try {
        record = await storage.checkOutEmployee(employeeId, signature, scheduleId, targetDate);
      } catch (checkOutError: any) {
        console.error("[Check-out] checkOutEmployee failed:", checkOutError?.message || checkOutError);
        return res.status(500).json({ error: "فشل في تسجيل الانصراف" });
      }
      if (!record) {
        return res.status(404).json({ error: "لم يتم تسجيل حضور هذا الموظف اليوم" });
      }
      
      if (record.id && serverBiometricVerified) {
        try {
          await storage.updateAttendanceRecord(record.id, { biometricCheckOut: true, biometricVerified: true });
        } catch (updateError: any) {
          console.error("[Check-out] updateAttendanceRecord biometric failed:", updateError?.message || updateError);
        }
      }
      
      res.json({ ...record, biometricVerified: serverBiometricVerified });
    } catch (error: any) {
      console.error("[Check-out] Unexpected error:", error?.message || error, error?.stack);
      res.status(500).json({ error: "فشل في تسجيل الانصراف" });
    }
  });

