  // Generate timesheet report for an employee
  app.post("/api/timesheet-reports/generate", isAuthenticated, requirePermission("timesheet", "create"), async (req, res) => {
    try {
      const { employeeId, branchId, startDate, endDate } = req.body;
      
      if (!employeeId || !branchId || !startDate || !endDate) {
        return res.status(400).json({ error: "جميع الحقول مطلوبة: employeeId, branchId, startDate, endDate" });
      }

      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      }

      // Check if report already exists (Phase 3: include lock status)
      const existing = await storage.getTimesheetReportByEmployeeAndDates(employeeId, startDate, endDate);
      if (existing) {
        return res.status(400).json({
          error: existing.isLocked
            ? "يوجد تقرير مقفل لهذه الفترة - يجب إعادة الإصدار من سجل التقارير"
            : "يوجد تقرير مسبق لهذه الفترة",
          existingReportId: existing.id,
          isLocked: existing.isLocked,
        });
      }

      // Get employee info - handle both regular users and branch employees
      let employeeName = "";
      if (employeeId.startsWith("branch_emp_")) {
        const branchEmployeeId = parseInt(employeeId.replace("branch_emp_", ""));
        const branchEmployee = await storage.getBranchEmployee(branchEmployeeId);
        if (!branchEmployee) {
          return res.status(404).json({ error: "موظف الفرع غير موجود" });
        }
        employeeName = branchEmployee.employeeName;
      } else {
        const user = await storage.getUser(employeeId);
        if (!user) {
          return res.status(404).json({ error: "الموظف غير موجود" });
        }
        employeeName = `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.username || '';
      }

      // Get schedules and attendance for the date range
      const schedules = await storage.getEmployeeSchedulesByBranchAndDateRange(branchId, startDate, endDate);
      const employeeSchedules = schedules.filter(s => s.employeeId === employeeId);
      
      const attendance = await storage.getAllAttendanceRecords({
        employeeId,
        branchId,
        startDate,
        endDate
      });

      // Calculate totals
      let totalScheduledDays = 0;
      let totalPresentDays = 0;
      let totalAbsentDays = 0;
      let totalLateDays = 0;
      let totalScheduledHours = 0;
      let totalActualHours = 0;
      let totalOvertimeMinutes = 0;
      let totalLateMinutes = 0;

      // Create report first
      const report = await storage.createTimesheetReport({
        employeeId,
        branchId,
        startDate,
        endDate,
        generatedBy: req.currentUser?.id,
        status: "pending_employee_signature",
        totalScheduledDays: 0,
        totalPresentDays: 0,
        totalAbsentDays: 0,
        totalLateDays: 0,
        totalScheduledHours: 0,
        totalActualHours: 0,
        totalOvertimeMinutes: 0,
        totalLateMinutes: 0,
      });

      // Generate daily entries
      const entries: any[] = [];
      const start = new Date(startDate);
      const end = new Date(endDate);
      const dayNames = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

      for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        const dateStr = d.toISOString().split('T')[0];
        const dayOfWeek = dayNames[d.getDay()];
        
        const schedule = employeeSchedules.find(s => s.scheduleDate === dateStr);
        const attendanceRecord = attendance.find(a => a.attendanceDate === dateStr);
        
        const isOff = schedule?.isOff || dayOfWeek === 'fri';
        const scheduledStartTime = schedule?.startTime || "08:00"; // Default start time
        const scheduledEndTime = schedule?.endTime || "16:00"; // Default end time
        const actualStartTime = attendanceRecord?.actualCheckIn || null;
        const actualEndTime = attendanceRecord?.actualCheckOut || null;
        
        // Calculate hours (default 8 hours work day)
        let scheduledHours = 8;
        if (schedule?.startTime && schedule?.endTime && !isOff) {
          const startParts = schedule.startTime.split(':').map(Number);
          const endParts = schedule.endTime.split(':').map(Number);
          scheduledHours = (endParts[0] + endParts[1]/60) - (startParts[0] + startParts[1]/60);
        }
        
        let actualHours = attendanceRecord?.workingHours || 0;
        let overtimeMinutes = attendanceRecord?.overtimeMinutes || 0;
        let lateMinutes = attendanceRecord?.lateMinutes || 0;
        
        // Determine status
        let status = "pending";
        if (isOff) {
          status = "day_off";
        } else if (attendanceRecord) {
          if (attendanceRecord.status === "present") status = "present";
          else if (attendanceRecord.status === "late") status = "late";
          else if (attendanceRecord.status === "absent") status = "absent";
          else status = attendanceRecord.status || "pending";
        } else if (!isOff) {
          // Count as work day without attendance record
          status = "absent";
        }

        // Update totals - count all non-off days as scheduled work days
        if (!isOff) {
          totalScheduledDays++;
          totalScheduledHours += scheduledHours;
          
          if (status === "present" || status === "late") {
            totalPresentDays++;
            totalActualHours += actualHours;
            totalOvertimeMinutes += overtimeMinutes;
          }
          if (status === "late") {
            totalLateDays++;
            totalLateMinutes += lateMinutes;
          }
          if (status === "absent") {
            totalAbsentDays++;
          }
        }

        entries.push({
          reportId: report.id,
          date: dateStr,
          dayOfWeek,
          scheduledStartTime,
          scheduledEndTime,
          actualStartTime,
          actualEndTime,
          isOff,
          status,
          scheduledHours,
          actualHours,
          overtimeMinutes,
          lateMinutes,
          checkInSignature: attendanceRecord?.checkInSignature || null,
          checkOutSignature: attendanceRecord?.checkOutSignature || null,
        });
      }

      // Save entries
      await storage.createBulkTimesheetReportEntries(entries);

      // Update report with totals
      const updatedReport = await storage.updateTimesheetReport(report.id, {
        totalScheduledDays,
        totalPresentDays,
        totalAbsentDays,
        totalLateDays,
        totalScheduledHours: Math.round(totalScheduledHours * 100) / 100,
        totalActualHours: Math.round(totalActualHours * 100) / 100,
        totalOvertimeMinutes,
        totalLateMinutes,
      });

      res.status(201).json({ report: updatedReport, entriesCount: entries.length });
    } catch (error) {
      console.error("Error generating timesheet report:", error);
      res.status(500).json({ error: "فشل في إنشاء التقرير" });
    }
  });

  // Bulk generate timesheet reports for many employees in a branch (single month)
  // Body: { branchId, startDate, endDate, employeeIds: string[] }
  // Returns: { created, skipped, failed, summary }
  app.post("/api/timesheet-reports/generate-bulk", isAuthenticated, requirePermission("timesheet", "create"), async (req, res) => {
    try {
      const { branchId, startDate, endDate, employeeIds } = req.body;

      if (!branchId || !startDate || !endDate || !Array.isArray(employeeIds) || employeeIds.length === 0) {
        return res.status(400).json({ error: "يجب تحديد الفرع والفترة وقائمة الموظفين" });
      }

      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      }

      // Pre-fetch schedules, attendance, branch employees, and branch users ONCE for the whole branch+range
      // (avoid N+1 + build branch-scoped allow-set for security)
      const [allSchedules, allAttendance, branchEmps, allUsers] = await Promise.all([
        storage.getEmployeeSchedulesByBranchAndDateRange(branchId, startDate, endDate),
        storage.getAllAttendanceRecords({ branchId, startDate, endDate }),
        storage.getBranchEmployeesByBranch(branchId),
        storage.getAllUsers(),
      ]);

      // Build branch-scoped allow-set: which employee IDs (in either UUID or branch_emp_X form) belong to this branch?
      const branchUserIdSet = new Set<string>(allUsers.filter((u: any) => u.branchId === branchId).map((u: any) => u.id));
      const branchEmpById = new Map<number, any>();
      const linkedUserToBranchEmpId = new Map<string, number>();
      for (const be of branchEmps) {
        branchEmpById.set(be.id, be);
        if (be.linkedUserId) linkedUserToBranchEmpId.set(be.linkedUserId, be.id);
      }

      const dayNames = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

      const created: Array<{ employeeId: string; reportId?: number; entriesCount: number }> = [];
      const skipped: Array<{ employeeId: string; reason: string; existingReportId?: number }> = [];
      const failed: Array<{ employeeId: string; error: string }> = [];

      for (const employeeId of employeeIds) {
        try {
          // Resolve employee + branch employee numeric ID + ENFORCE branch membership (security)
          let branchEmpNumId: number | undefined;
          if (employeeId.startsWith("branch_emp_")) {
            const beId = parseInt(employeeId.replace("branch_emp_", ""));
            const be = branchEmpById.get(beId);
            if (!be) {
              failed.push({ employeeId, error: "موظف الفرع غير موجود في هذا الفرع" });
              continue;
            }
            // SECURITY: branch employee must belong to the selected branch
            if (be.branchId !== branchId) {
              failed.push({ employeeId, error: "الموظف لا ينتمي إلى الفرع المحدد" });
              continue;
            }
            branchEmpNumId = beId;
          } else {
            // SECURITY: user must be either a branch member or linked via branch_employees to this branch
            const isBranchUser = branchUserIdSet.has(employeeId);
            const linkedBranchEmpId = linkedUserToBranchEmpId.get(employeeId);
            if (!isBranchUser && linkedBranchEmpId === undefined) {
              failed.push({ employeeId, error: "الموظف لا ينتمي إلى الفرع المحدد" });
              continue;
            }
            if (linkedBranchEmpId !== undefined) branchEmpNumId = linkedBranchEmpId;
          }

          // Skip if already exists (after branch validation so out-of-branch IDs always report as failed, not skipped)
          // Phase 3: distinguish locked vs unlocked existing reports
          const existing = await storage.getTimesheetReportByEmployeeAndDates(employeeId, startDate, endDate);
          if (existing) {
            skipped.push({
              employeeId,
              reason: existing.isLocked ? "already_locked" : "already_exists",
              existingReportId: existing.id,
            });
            continue;
          }

          // Filter schedules and attendance for this employee
          const empSchedules = allSchedules.filter((s: any) => {
            if (s.employeeId === employeeId) return true;
            if (branchEmpNumId !== undefined && s.branchEmployeeId === branchEmpNumId) return true;
            return false;
          });
          const empAttendance = allAttendance.filter((a: any) => {
            if (a.employeeId === employeeId) return true;
            if (branchEmpNumId !== undefined && a.branchEmployeeId === branchEmpNumId) return true;
            return false;
          });

          // Create the report shell
          const report = await storage.createTimesheetReport({
            employeeId, branchId, startDate, endDate,
            generatedBy: req.currentUser?.id,
            status: "pending_employee_signature",
            totalScheduledDays: 0, totalPresentDays: 0, totalAbsentDays: 0, totalLateDays: 0,
            totalScheduledHours: 0, totalActualHours: 0, totalOvertimeMinutes: 0, totalLateMinutes: 0,
          });

          // Compute daily entries + totals (same logic as single endpoint)
          let totalScheduledDays = 0, totalPresentDays = 0, totalAbsentDays = 0, totalLateDays = 0;
          let totalScheduledHours = 0, totalActualHours = 0;
          let totalOvertimeMinutes = 0, totalLateMinutes = 0;
          const entries: any[] = [];

          const start = new Date(startDate);
          const end = new Date(endDate);
          for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
            const dateStr = d.toISOString().split('T')[0];
            const dayOfWeek = dayNames[d.getDay()];

            const schedule = empSchedules.find((s: any) => s.scheduleDate === dateStr);
            const attendanceRecord = empAttendance.find((a: any) => a.attendanceDate === dateStr);

            const isOff = schedule?.isOff || dayOfWeek === 'fri';
            const scheduledStartTime = schedule?.startTime || "08:00";
            const scheduledEndTime = schedule?.endTime || "16:00";
            const actualStartTime = attendanceRecord?.actualCheckIn || null;
            const actualEndTime = attendanceRecord?.actualCheckOut || null;

            let scheduledHours = 8;
            if (schedule?.startTime && schedule?.endTime && !isOff) {
              const sp = schedule.startTime.split(':').map(Number);
              const ep = schedule.endTime.split(':').map(Number);
              scheduledHours = (ep[0] + ep[1]/60) - (sp[0] + sp[1]/60);
            }

            const actualHours = attendanceRecord?.workingHours || 0;
            const overtimeMinutes = attendanceRecord?.overtimeMinutes || 0;
            const lateMinutes = attendanceRecord?.lateMinutes || 0;

            let status = "pending";
            if (isOff) status = "day_off";
            else if (attendanceRecord) {
              if (attendanceRecord.status === "present") status = "present";
              else if (attendanceRecord.status === "late") status = "late";
              else if (attendanceRecord.status === "absent") status = "absent";
              else status = attendanceRecord.status || "pending";
            } else status = "absent";

            if (!isOff) {
              totalScheduledDays++;
              totalScheduledHours += scheduledHours;
              if (status === "present" || status === "late") {
                totalPresentDays++;
                totalActualHours += actualHours;
                totalOvertimeMinutes += overtimeMinutes;
              }
              if (status === "late") { totalLateDays++; totalLateMinutes += lateMinutes; }
              if (status === "absent") totalAbsentDays++;
            }

            entries.push({
              reportId: report.id, date: dateStr, dayOfWeek,
              scheduledStartTime, scheduledEndTime, actualStartTime, actualEndTime,
              isOff, status, scheduledHours, actualHours, overtimeMinutes, lateMinutes,
              checkInSignature: attendanceRecord?.checkInSignature || null,
              checkOutSignature: attendanceRecord?.checkOutSignature || null,
            });
          }

          await storage.createBulkTimesheetReportEntries(entries);
          const updatedReport = await storage.updateTimesheetReport(report.id, {
            totalScheduledDays, totalPresentDays, totalAbsentDays, totalLateDays,
            totalScheduledHours: Math.round(totalScheduledHours * 100) / 100,
            totalActualHours: Math.round(totalActualHours * 100) / 100,
            totalOvertimeMinutes, totalLateMinutes,
          });

          created.push({ employeeId, reportId: updatedReport?.id, entriesCount: entries.length });
        } catch (e: any) {
          console.error(`Bulk timesheet generation failed for ${employeeId}:`, e);
          failed.push({ employeeId, error: e?.message || "خطأ غير معروف" });
        }
      }

      res.status(201).json({
        created, skipped, failed,
        summary: { created: created.length, skipped: skipped.length, failed: failed.length },
      });
    } catch (error) {
      console.error("Error in bulk timesheet generation:", error);
      res.status(500).json({ error: "فشل في الإنشاء الجماعي للتقارير" });
    }
  });

  // Generate branch-wide timesheet PDF (multi-page, one employee per page)
  app.post("/api/timesheet-reports/generate-branch-pdf", isAuthenticated, requirePermission("timesheet", "create"), async (req, res) => {
    try {
      const { branchId, startDate, endDate } = req.body;
      if (!branchId || branchId === "all" || !startDate || !endDate) {
        return res.status(400).json({ error: "يجب اختيار فرع محدد وفترة زمنية" });
      }

      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      }

      const branch = await storage.getBranch(branchId);
      if (!branch) return res.status(404).json({ error: "الفرع غير موجود" });

      // Build employee list (mirrors UI logic): branch users + branch_employees without linked user
      const allUsers = await storage.getAllUsers();
      const branchUsers = allUsers.filter((u: any) => u.branchId === branchId);
      const branchEmps = await storage.getBranchEmployeesByBranch(branchId);
      const standaloneEmps = branchEmps.filter((be: any) => !be.linkedUserId && (be.status === 'active' || !be.status));

      // Map linkedUserId → branchEmployeeNumericId so we can match records across all storage shapes
      const linkedUserToBranchEmp = new Map<string, number>();
      for (const be of branchEmps) {
        if (be.linkedUserId) linkedUserToBranchEmp.set(be.linkedUserId, be.id);
      }

      type Emp = {
        id: string;
        name: string;
        jobTitle: string;
        employeeNumber?: string;
        userId?: string;
        branchEmpNumId?: number;
      };
      const employees: Emp[] = [
        ...branchUsers.map((u: any) => ({
          id: u.id,
          name: `${u.firstName || ''} ${u.lastName || ''}`.trim() || u.username || 'موظف',
          jobTitle: u.jobTitle || '-',
          userId: u.id,
          branchEmpNumId: linkedUserToBranchEmp.get(u.id),
        })),
        ...standaloneEmps.map((be: any) => ({
          id: `branch_emp_${be.id}`,
          name: be.employeeName,
          jobTitle: be.jobTitle,
          employeeNumber: be.employeeNumber || undefined,
          branchEmpNumId: be.id,
        })),
      ];

      // Match a schedule/attendance record to an employee using ANY of:
      // user UUID, branch_emp_<num> string, or numeric branchEmployeeId
      const matchesEmp = (rec: any, emp: Emp): boolean => {
        if (emp.userId && rec.employeeId === emp.userId) return true;
        if (emp.branchEmpNumId !== undefined) {
          if (rec.branchEmployeeId === emp.branchEmpNumId) return true;
          if (rec.employeeId === `branch_emp_${emp.branchEmpNumId}`) return true;
        }
        return false;
      };

      if (employees.length === 0) {
        return res.status(400).json({ error: "لا يوجد موظفون في هذا الفرع" });
      }

      // Fetch schedules and attendance once for the whole branch+range
      const allSchedules = await storage.getEmployeeSchedulesByBranchAndDateRange(branchId, startDate, endDate);
      const allAttendance = await storage.getAllAttendanceRecords({ branchId, startDate, endDate });

      const dayNames = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
      const arDayMap: Record<string, string> = {
        sat: "السبت", sun: "الأحد", mon: "الاثنين", tue: "الثلاثاء", wed: "الأربعاء", thu: "الخميس", fri: "الجمعة"
      };
      const arStatusMap: Record<string, string> = {
        present: "حاضر", late: "متأخر", absent: "غائب", day_off: "إجازة", pending: "معلق"
      };
      const monthLabel = (() => {
        try {
          const d = new Date(startDate);
          const months = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
          return `${months[d.getMonth()]} ${d.getFullYear()}`;
        } catch { return ""; }
      })();

      const employeeReports = employees.map(emp => {
        const empSchedules = allSchedules.filter((s: any) => matchesEmp(s, emp));
        const empAttendance = allAttendance.filter((a: any) => matchesEmp(a, emp));

        let scheduledDays = 0, presentDays = 0, absentDays = 0, lateDays = 0, offDays = 0;
        let totalScheduledHours = 0, totalActualHours = 0, totalLateMinutes = 0, totalOvertimeMinutes = 0;
        const entries: any[] = [];

        // Parse YYYY-MM-DD into local-date to avoid timezone drift during iteration
        const [sy, sm, sd] = startDate.split('-').map(Number);
        const [ey, em, ed] = endDate.split('-').map(Number);
        const start = new Date(sy, sm - 1, sd);
        const end = new Date(ey, em - 1, ed);

        for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
          const yyyy = d.getFullYear();
          const mm = String(d.getMonth() + 1).padStart(2, '0');
          const dd = String(d.getDate()).padStart(2, '0');
          const dateStr = `${yyyy}-${mm}-${dd}`;
          const dayKey = dayNames[d.getDay()];
          const schedule = empSchedules.find((s: any) => s.scheduleDate === dateStr);
          const attendance = empAttendance.find((a: any) => a.attendanceDate === dateStr);

          const isOff = schedule?.isOff ?? (dayKey === 'fri' && !schedule);
          const scheduledStart = schedule?.startTime || (isOff ? "-" : "08:00");
          const scheduledEnd = schedule?.endTime || (isOff ? "-" : "16:00");

          let scheduledHours = 0;
          if (!isOff && schedule?.startTime && schedule?.endTime) {
            const sp = schedule.startTime.split(':').map(Number);
            const ep = schedule.endTime.split(':').map(Number);
            scheduledHours = (ep[0] + ep[1] / 60) - (sp[0] + sp[1] / 60);
            if (scheduledHours < 0) scheduledHours += 24;
          } else if (!isOff) {
            scheduledHours = 8;
          }

          let statusKey = "pending";
          if (isOff) {
            statusKey = "day_off";
          } else if (attendance) {
            statusKey = (attendance.status === "present" || attendance.status === "late" || attendance.status === "absent")
              ? attendance.status
              : "absent";
          } else {
            statusKey = "absent";
          }

          const actualHours = attendance?.workingHours || 0;
          const lateMin = attendance?.lateMinutes || 0;
          const otMin = attendance?.overtimeMinutes || 0;

          if (isOff) {
            offDays++;
          } else {
            scheduledDays++;
            totalScheduledHours += scheduledHours;
            if (statusKey === "present" || statusKey === "late") {
              presentDays++;
              totalActualHours += actualHours;
              totalOvertimeMinutes += otMin;
            }
            if (statusKey === "late") {
              lateDays++;
              totalLateMinutes += lateMin;
            }
            if (statusKey === "absent") absentDays++;
          }

          entries.push({
            date: dateStr,
            dayName: arDayMap[dayKey] || dayKey,
            scheduledStart,
            scheduledEnd,
            actualCheckIn: attendance?.actualCheckIn || (isOff ? "-" : "غ"),
            actualCheckOut: attendance?.actualCheckOut || (isOff ? "-" : "غ"),
            workHours: actualHours ? actualHours.toFixed(1) : "-",
            status: arStatusMap[statusKey] || statusKey,
            isOff,
            checkInSignature: attendance?.checkInSignature || null,
          });
        }

        return {
          employeeName: emp.name,
          jobTitle: emp.jobTitle,
          employeeNumber: emp.employeeNumber,
          scheduledDays, presentDays, absentDays, lateDays, offDays,
          totalScheduledHours: Math.round(totalScheduledHours * 100) / 100,
          totalActualHours: Math.round(totalActualHours * 100) / 100,
          totalLateMinutes,
          totalOvertimeMinutes,
          entries,
        };
      });

      // Exclude employees with zero attendance (no present/late days) from the branch PDF
      const employeeReportsWithAttendance = employeeReports.filter(r => (r.presentDays || 0) > 0);

      if (employeeReportsWithAttendance.length === 0) {
        return res.status(400).json({ error: "لا يوجد موظفون لديهم حضور في هذه الفترة" });
      }

      const pdfBuffer = await generateBranchTimesheetPdf({
        branchName: branch.name,
        periodStart: startDate,
        periodEnd: endDate,
        monthLabel,
        employees: employeeReportsWithAttendance,
      });

      // ASCII fallback + RFC 5987 UTF-8 encoded variant so Arabic branch names work
      const safeAscii = `branch_timesheet_${startDate}_${endDate}.pdf`;
      const utf8Name = encodeURIComponent(`timesheet_${branch.name}_${startDate}_${endDate}.pdf`);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="${safeAscii}"; filename*=UTF-8''${utf8Name}`);
      res.setHeader('Content-Length', pdfBuffer.length.toString());
      res.end(pdfBuffer);
    } catch (error) {
      console.error("Error generating branch timesheet PDF:", error);
      res.status(500).json({ error: "فشل في إنشاء تقرير الفرع" });
    }
  });

  // Sign timesheet report (employee or manager)
  // Generate single-employee timesheet PDF (Phase 2 - rich PDF with exceptions panel + embedded signatures)
  app.post("/api/timesheet-reports/:id/generate-pdf", isAuthenticated, requirePermission("timesheet", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const report = await storage.getTimesheetReport(id);
      if (!report) return res.status(404).json({ error: "التقرير غير موجود" });

      // SECURITY: branch access check
      if (!isUserAdmin(req) && report.branchId) {
        const hasAccess = await canAccessBranch(req, report.branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا التقرير" });
      }

      const [entries, branch, allUsers, branchEmps] = await Promise.all([
        storage.getTimesheetReportEntries(id),
        storage.getBranch(report.branchId),
        storage.getAllUsers(),
        storage.getBranchEmployeesByBranch(report.branchId),
      ]);
      if (!branch) return res.status(404).json({ error: "الفرع غير موجود" });

      // Resolve employee display info
      let employeeName = "موظف", jobTitle = "-", employeeNumber: string | undefined;
      if (report.employeeId.startsWith("branch_emp_")) {
        const beId = parseInt(report.employeeId.replace("branch_emp_", ""));
        const be = branchEmps.find((x: any) => x.id === beId);
        if (be) { employeeName = be.employeeName; jobTitle = be.jobTitle || "-"; employeeNumber = be.employeeNumber || undefined; }
      } else {
        const u = allUsers.find((x: any) => x.id === report.employeeId);
        if (u) {
          employeeName = `${u.firstName || ""} ${u.lastName || ""}`.trim() || u.username || "موظف";
          jobTitle = u.jobTitle || "-";
        }
        if (report.branchEmployeeId) {
          const linkedBe = branchEmps.find((x: any) => x.id === report.branchEmployeeId);
          if (linkedBe?.employeeNumber) employeeNumber = linkedBe.employeeNumber;
        }
      }

      const arDayMap: Record<string, string> = { sat: "السبت", sun: "الأحد", mon: "الاثنين", tue: "الثلاثاء", wed: "الأربعاء", thu: "الخميس", fri: "الجمعة" };
      const arStatusMap: Record<string, string> = { present: "حاضر", late: "متأخر", absent: "غائب", day_off: "إجازة", pending: "معلق" };

      const monthLabel = (() => {
        try {
          const d = new Date(report.startDate);
          const months = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
          return `${months[d.getMonth()]} ${d.getFullYear()}`;
        } catch { return ""; }
      })();

      // Build entries + exceptions in one pass (sorted by date)
      const sortedEntries = [...entries].sort((a, b) => a.date.localeCompare(b.date));
      const pdfEntries = sortedEntries.map(e => ({
        date: e.date,
        dayName: arDayMap[e.dayOfWeek] || e.dayOfWeek,
        scheduledStart: e.scheduledStartTime || (e.isOff ? "-" : "08:00"),
        scheduledEnd: e.scheduledEndTime || (e.isOff ? "-" : "16:00"),
        actualCheckIn: e.actualStartTime || (e.isOff ? "-" : "غ"),
        actualCheckOut: e.actualEndTime || (e.isOff ? "-" : "غ"),
        workHours: (e.actualHours && e.actualHours > 0) ? e.actualHours.toFixed(1) : "-",
        status: arStatusMap[e.status || "pending"] || (e.status || "pending"),
        isOff: !!e.isOff,
        lateMinutes: e.lateMinutes || 0,
        overtimeMinutes: e.overtimeMinutes || 0,
        checkInSignature: e.checkInSignature || null,
      }));

      const exceptions: Array<{ date: string; dayName: string; type: "late" | "absent" | "overtime"; detail: string }> = [];
      for (const e of sortedEntries) {
        const dayName = arDayMap[e.dayOfWeek] || e.dayOfWeek;
        if (e.status === "absent" && !e.isOff) {
          exceptions.push({ date: e.date, dayName, type: "absent", detail: "غياب بدون عذر" });
        }
        if ((e.lateMinutes || 0) > 0) {
          exceptions.push({ date: e.date, dayName, type: "late", detail: `تأخير ${e.lateMinutes} دقيقة` });
        }
        if ((e.overtimeMinutes || 0) > 0) {
          exceptions.push({ date: e.date, dayName, type: "overtime", detail: `${e.overtimeMinutes} دقيقة عمل إضافي` });
        }
      }

      const pdfBuffer = await generateSingleTimesheetPdf({
        branchName: branch.name,
        periodStart: report.startDate,
        periodEnd: report.endDate,
        monthLabel,
        employeeName, jobTitle, employeeNumber,
        scheduledDays: report.totalScheduledDays || 0,
        presentDays: report.totalPresentDays || 0,
        absentDays: report.totalAbsentDays || 0,
        lateDays: report.totalLateDays || 0,
        offDays: Math.max(0, sortedEntries.filter(e => e.isOff).length),
        totalScheduledHours: report.totalScheduledHours || 0,
        totalActualHours: report.totalActualHours || 0,
        totalLateMinutes: report.totalLateMinutes || 0,
        totalOvertimeMinutes: report.totalOvertimeMinutes || 0,
        entries: pdfEntries,
        exceptions,
        employeeSignature: report.employeeSignature,
        employeeSignedAt: report.employeeSignedAt ? report.employeeSignedAt.toISOString() : null,
        employeeAcknowledgment: report.employeeAcknowledgment,
        managerSignature: report.managerSignature,
        managerSignedAt: report.managerSignedAt ? report.managerSignedAt.toISOString() : null,
        managerAcknowledgment: report.managerAcknowledgment,
        status: report.status,
      });

      const safeName = employeeName.replace(/[^\w\u0600-\u06FF\s-]/g, "").replace(/\s+/g, "_");
      const safeAscii = `timesheet_${report.id}_${report.startDate}_${report.endDate}.pdf`;
      const utf8Filename = `timesheet_${safeName}_${report.startDate}_${report.endDate}.pdf`;
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="${safeAscii}"; filename*=UTF-8''${encodeURIComponent(utf8Filename)}`);
      res.setHeader("Content-Length", String(pdfBuffer.length));
      res.send(pdfBuffer);
    } catch (error: any) {
      console.error("Error generating single timesheet PDF:", error);
      res.status(500).json({ error: error.message || "فشل في توليد التقرير" });
    }
  });

  app.post("/api/timesheet-reports/:id/sign", isAuthenticated, requirePermission("attendance", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      
      const { signatureType, signature, acknowledgment } = req.body;
      
      if (!signatureType || !signature) {
        return res.status(400).json({ error: "نوع التوقيع والتوقيع مطلوبان" });
      }
      
      if (signatureType !== 'employee' && signatureType !== 'manager') {
        return res.status(400).json({ error: "نوع التوقيع غير صالح" });
      }
      
      const signerId = req.currentUser?.id;
      if (!signerId) {
        return res.status(401).json({ error: "المستخدم غير موجود" });
      }

      // Validate signature size (max 500KB base64)
      if (signature.length > 500000) {
        return res.status(400).json({ error: "حجم التوقيع كبير جداً" });
      }
      
      // Phase 3: Block signing on locked reports
      const existingReport = await storage.getTimesheetReport(id);
      if (!existingReport) return res.status(404).json({ error: "التقرير غير موجود" });
      if (existingReport.isLocked) {
        return res.status(400).json({ error: "هذا التقرير مقفل - يجب إعادة الإصدار قبل التعديل" });
      }

      const report = await storage.signTimesheetReport(id, signatureType, signature, signerId, acknowledgment);
      if (!report) {
        return res.status(404).json({ error: "التقرير غير موجود" });
      }

      // Phase 3: audit log + in-app notifications
      const performerName = `${req.currentUser?.firstName || ""} ${req.currentUser?.lastName || ""}`.trim() || req.currentUser?.username || signerId;
      try {
        await storage.createTimesheetAuditLog({
          reportId: id,
          action: signatureType === 'employee' ? 'signed_employee' : 'signed_manager',
          performedBy: signerId,
          performedByName: performerName,
          ipAddress: (req.ip || req.headers['x-forwarded-for'] as string || '').toString().slice(0, 100),
          userAgent: (req.headers['user-agent'] || '').toString().slice(0, 500),
          notes: acknowledgment ? acknowledgment.slice(0, 500) : null,
        });

        if (report.status === 'finalized' && existingReport.status !== 'finalized') {
          await storage.createTimesheetAuditLog({
            reportId: id,
            action: 'locked',
            performedBy: signerId,
            performedByName: performerName,
            notes: 'قفل تلقائي عند اكتمال التوقيعات',
          });
        }

        // Notifications: branch users (best-effort)
        const branchUsers = await storage.getAllUsers().catch(() => [] as any[]);
        const branchManagers = branchUsers.filter((u: any) => u.branchId === report.branchId && (u.role === 'manager' || u.role === 'admin'));
        if (signatureType === 'employee' && report.status === 'pending_manager_signature') {
          await Promise.all(branchManagers.map((m: any) => storage.createSystemNotification({
            userId: m.id,
            branchId: report.branchId,
            title: 'تقرير دوام بانتظار توقيعك',
            message: `وقّع الموظف على تقرير دوام للفترة ${report.startDate} - ${report.endDate}`,
            type: 'info',
            category: 'system',
            priority: 'normal',
            linkType: 'meeting',
            linkId: id,
            linkUrl: `/timesheet?reportId=${id}`,
            createdBy: signerId,
          }).catch(() => null)));
        } else if (report.status === 'finalized') {
          // notify the employee (only if has user account)
          if (!report.employeeId.startsWith('branch_emp_')) {
            await storage.createSystemNotification({
              userId: report.employeeId,
              branchId: report.branchId,
              title: 'اكتمل توقيع تقرير دوامك',
              message: `تم توقيع وقفل تقرير دوامك للفترة ${report.startDate} - ${report.endDate}`,
              type: 'success',
              category: 'system',
              priority: 'normal',
              linkType: 'meeting',
              linkId: id,
              linkUrl: `/timesheet?reportId=${id}`,
              createdBy: signerId,
            }).catch(() => null);
          }
        }
      } catch (auditErr) {
        console.error("Audit/notification side-effect failed (non-blocking):", auditErr);
      }

      res.json(report);
    } catch (error) {
      console.error("Error signing timesheet report:", error);
      res.status(500).json({ error: "فشل في توقيع التقرير" });
    }
  });

  // Reject a timesheet report (manager/HR) with notes - رفض التقرير مع ملاحظات
  app.post("/api/timesheet-reports/:id/reject", isAuthenticated, requirePermission("attendance", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const { reason } = req.body || {};
      if (!reason || typeof reason !== 'string' || reason.trim().length < 3) {
        return res.status(400).json({ error: "يجب كتابة سبب الرفض (3 أحرف على الأقل)" });
      }

      const rejecterId = req.currentUser?.id;
      if (!rejecterId) return res.status(401).json({ error: "المستخدم غير موجود" });

      const existingReport = await storage.getTimesheetReport(id);
      if (!existingReport) return res.status(404).json({ error: "التقرير غير موجود" });
      if (existingReport.isLocked || existingReport.status === 'finalized') {
        return res.status(400).json({ error: "لا يمكن رفض تقرير مكتمل أو مقفل - استخدم إعادة الإصدار" });
      }
      if (existingReport.status !== 'pending_manager_signature') {
        return res.status(400).json({ error: "لا يمكن الرفض إلا عندما يكون التقرير بانتظار توقيع المدير" });
      }
      // SECURITY: branch access for non-admin users
      if (!isUserAdmin(req) && existingReport.branchId) {
        const hasAccess = await canAccessBranch(req, existingReport.branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح" });
      }

      const report = await storage.rejectTimesheetReport(id, reason.trim().slice(0, 1000), rejecterId);
      if (!report) return res.status(404).json({ error: "التقرير غير موجود" });

      const performerName = `${req.currentUser?.firstName || ""} ${req.currentUser?.lastName || ""}`.trim() || req.currentUser?.username || rejecterId;
      try {
        await storage.createTimesheetAuditLog({
          reportId: id,
          action: 'rejected',
          performedBy: rejecterId,
          performedByName: performerName,
          ipAddress: (req.ip || req.headers['x-forwarded-for'] as string || '').toString().slice(0, 100),
          userAgent: (req.headers['user-agent'] || '').toString().slice(0, 500),
          notes: reason.trim().slice(0, 500),
        });
        // Notify the employee (only if has user account)
        if (!report.employeeId.startsWith('branch_emp_')) {
          await storage.createSystemNotification({
            userId: report.employeeId,
            branchId: report.branchId,
            title: 'تم رفض تقرير دوامك',
            message: `رُفض تقرير الفترة ${report.startDate} - ${report.endDate}. الملاحظات: ${reason.trim().slice(0, 200)}`,
            type: 'warning',
            category: 'system',
            priority: 'high',
            linkType: 'meeting',
            linkId: id,
            linkUrl: `/my-portal`,
            createdBy: rejecterId,
          }).catch(() => null);
        }
      } catch (auditErr) {
        console.error("Reject audit/notification side-effect failed (non-blocking):", auditErr);
      }

      res.json(report);
    } catch (error) {
      console.error("Error rejecting timesheet report:", error);
      res.status(500).json({ error: "فشل في رفض التقرير" });
    }
  });

  // Delete timesheet report
  app.delete("/api/timesheet-reports/:id", isAuthenticated, requirePermission("attendance", "delete"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      
      const report = await storage.getTimesheetReport(id);
      if (!report) {
        return res.status(404).json({ error: "التقرير غير موجود" });
      }
      
      if (report.status === 'finalized' || report.isLocked) {
        return res.status(400).json({ error: "لا يمكن حذف تقرير مكتمل أو مقفل - استخدم إعادة الإصدار بدلاً من ذلك" });
      }

      await storage.deleteTimesheetReport(id);

      // Phase 3: audit (best-effort; cascade may have removed it but log it for paper trail in archive separately is overkill)
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting timesheet report:", error);
      res.status(500).json({ error: "فشل في حذف التقرير" });
    }
  });

  // ============= Phase 3: Audit Log + Reissue endpoints =============

  // Get audit log for a report
  app.get("/api/timesheet-reports/:id/audit-log", isAuthenticated, requirePermission("timesheet", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      const report = await storage.getTimesheetReport(id);
      if (!report) return res.status(404).json({ error: "التقرير غير موجود" });
      if (!isUserAdmin(req) && report.branchId) {
        const hasAccess = await canAccessBranch(req, report.branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح" });
      }
      const log = await storage.getTimesheetAuditLog(id);
      res.json(log);
    } catch (error) {
      console.error("Error fetching timesheet audit log:", error);
      res.status(500).json({ error: "فشل في جلب سجل التدقيق" });
    }
  });

  // Reissue a locked report (admin only)
  app.post("/api/timesheet-reports/:id/reissue", isAuthenticated, async (req, res) => {
    try {
      if (!isUserAdmin(req)) {
        return res.status(403).json({ error: "إعادة الإصدار متاحة للمشرفين فقط" });
      }
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      const { reason } = req.body || {};
      if (!reason || typeof reason !== 'string' || reason.trim().length < 5) {
        return res.status(400).json({ error: "يجب توضيح سبب إعادة الإصدار (5 أحرف على الأقل)" });
      }

      const existing = await storage.getTimesheetReport(id);
      if (!existing) return res.status(404).json({ error: "التقرير غير موجود" });
      if (existing.supersededBy) {
        return res.status(400).json({ error: "هذا التقرير سبق وتم استبداله بإصدار أحدث" });
      }

      const performerId = req.currentUser?.id || '';
      const performerName = `${req.currentUser?.firstName || ""} ${req.currentUser?.lastName || ""}`.trim() || req.currentUser?.username || performerId;

      const result = await storage.reissueTimesheetReport(id, reason.trim(), performerId);
      if (!result) return res.status(500).json({ error: "فشل في إعادة الإصدار" });

      // Audit logs (old + new)
      try {
        await storage.createTimesheetAuditLog({
          reportId: id,
          action: 'reissued',
          performedBy: performerId,
          performedByName: performerName,
          ipAddress: (req.ip || '').toString().slice(0, 100),
          userAgent: (req.headers['user-agent'] || '').toString().slice(0, 500),
          notes: `استُبدل بالإصدار #${result.newReport.id}: ${reason.trim().slice(0, 400)}`,
        });
        await storage.createTimesheetAuditLog({
          reportId: result.newReport.id,
          action: 'created',
          performedBy: performerId,
          performedByName: performerName,
          notes: `إعادة إصدار من #${id} (الإصدار ${result.newReport.version})`,
        });

        // Notify employee if has account
        if (!result.newReport.employeeId.startsWith('branch_emp_')) {
          await storage.createSystemNotification({
            userId: result.newReport.employeeId,
            branchId: result.newReport.branchId,
            title: 'تم إعادة إصدار تقرير دوامك',
            message: `أُعيد إصدار تقرير الفترة ${result.newReport.startDate} - ${result.newReport.endDate}. السبب: ${reason.trim().slice(0, 200)}`,
            type: 'warning',
            category: 'system',
            priority: 'high',
            linkType: 'meeting',
            linkId: result.newReport.id,
            linkUrl: `/timesheet?reportId=${result.newReport.id}`,
            createdBy: performerId,
          }).catch(() => null);
        }
      } catch (e) { console.error("Reissue audit/notification failed:", e); }

      res.json(result);
    } catch (error) {
      console.error("Error reissuing timesheet report:", error);
      res.status(500).json({ error: "فشل في إعادة الإصدار" });
    }
  });

  // =====================================================
  // Branch Employees API - موظفي الفروع
  // =====================================================

  app.get("/api/branch-employees/bundle", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      const queryBranchId = req.query.branchId as string | undefined;
      const queryStatus = req.query.status as string | undefined; // active|inactive|terminated|on_leave|all
      const VALID_STATUS = new Set(["active", "inactive", "terminated", "on_leave"]);
      const statusFilter = queryStatus && VALID_STATUS.has(queryStatus) ? queryStatus : undefined;
      const allowedBranches = getAllowedBranchIds(req);

      // PERF: callers can opt out of expensive bundle parts they don't render.
      // E.g. terminated-employees only needs `employees`, not `stats` or
      // `systemUsers`. Pass ?include=employees (comma-separated) to skip.
      // Default = everything, for backwards compatibility.
      // Guard against array/object shapes Express produces for repeated query
      // params (?include=a&include=b). Only honor a plain string; otherwise
      // fall back to "return everything" so callers can't break the endpoint
      // by passing weird shapes.
      const rawInclude = req.query.include;
      const includeParam = typeof rawInclude === "string" ? rawInclude.trim() : "";
      const includeSet = includeParam ? new Set(includeParam.split(",").map(s => s.trim()).filter(Boolean)) : null;
      const wantEmployees = !includeSet || includeSet.has("employees");
      const wantStats = !includeSet || includeSet.has("stats");
      const wantSystemUsers = !includeSet || includeSet.has("systemUsers");

      const [employees, stats, systemUsers] = await Promise.all([
        !wantEmployees ? Promise.resolve([]) :
        (async () => {
          try {
            let emps;
            if (allowedBranches === null) {
              if (queryBranchId) {
                emps = await storage.getBranchEmployeesByBranch(queryBranchId, { status: statusFilter });
              } else {
                emps = await storage.getAllBranchEmployees({ status: statusFilter });
              }
            } else if (allowedBranches.length > 0) {
              if (queryBranchId && allowedBranches.includes(queryBranchId)) {
                emps = await storage.getBranchEmployeesByBranch(queryBranchId, { status: statusFilter });
              } else {
                emps = await storage.getAllBranchEmployees({ status: statusFilter, branchIds: allowedBranches });
              }
            } else {
              emps = [];
            }
            // SAFETY: Deduplicate by id (in case any DB-level duplicates ever exist or join effects)
            const seen = new Map();
            for (const e of emps) {
              if (!seen.has(e.id)) seen.set(e.id, e);
            }
            return Array.from(seen.values());
          } catch (e) {
            console.error("Bundle: employees fetch failed", e);
            return [];
          }
        })(),
        !wantStats ? Promise.resolve(null) :
        (async () => {
          try {
            if (allowedBranches === null) {
              return await storage.getBranchEmployeeStats(queryBranchId ?? undefined);
            }
            if (allowedBranches.length > 0) {
              if (queryBranchId && allowedBranches.includes(queryBranchId)) {
                return await storage.getBranchEmployeeStats(queryBranchId);
              }
              const branchStatsArr = await Promise.all(
                allowedBranches.map(bid => storage.getBranchEmployeeStats(bid))
              );
              const natMap = new Map<string, number>();
              const jobMap = new Map<string, number>();
              const statusMap = new Map<string, number>();
              let totalEmployees = 0;
              let totalSalaries = 0;
              for (const s of branchStatsArr) {
                totalEmployees += s.totalEmployees || 0;
                totalSalaries += s.totalSalaries || 0;
                for (const x of s.byNationality || []) natMap.set(x.nationality, (natMap.get(x.nationality) || 0) + x.count);
                for (const x of s.byJobTitle || []) jobMap.set(x.jobTitle, (jobMap.get(x.jobTitle) || 0) + x.count);
                for (const x of s.byStatus || []) statusMap.set(x.status, (statusMap.get(x.status) || 0) + x.count);
              }
              return {
                totalEmployees,
                totalSalaries,
                byNationality: Array.from(natMap.entries()).map(([nationality, count]) => ({ nationality, count })),
                byJobTitle: Array.from(jobMap.entries()).map(([jobTitle, count]) => ({ jobTitle, count })),
                byStatus: Array.from(statusMap.entries()).map(([status, count]) => ({ status, count })),
              };
            }
            return { totalEmployees: 0, totalSalaries: 0, byNationality: [], byJobTitle: [], byStatus: [] };
          } catch (e) {
            console.error("Bundle: stats fetch failed", e);
            return { totalEmployees: 0, totalSalaries: 0, byNationality: [], byJobTitle: [], byStatus: [] };
          }
        })(),
        !wantSystemUsers ? Promise.resolve([]) :
        (async () => {
          try {
            const allUsers = await storage.getAllUsers();
            if (allowedBranches === null) {
              return allUsers.map((u: any) => ({
                id: u.id, username: u.username, firstName: u.firstName,
                lastName: u.lastName, role: u.role, branchId: u.branchId,
              }));
            }
            if (allowedBranches.length === 0) return [];
            const allowedSet = new Set(allowedBranches);
            const branchAccessList = await db.select().from(userBranchAccess).where(
              inArray(userBranchAccess.branchId, allowedBranches)
            );
            const userIdsWithAccess = new Set(branchAccessList.map(ba => ba.userId));
            const filtered = allUsers.filter((u: any) => {
              if (u.branchId && allowedSet.has(u.branchId)) return true;
              return userIdsWithAccess.has(u.id);
            });
            return filtered.map((u: any) => ({
              id: u.id, username: u.username, firstName: u.firstName,
              lastName: u.lastName, role: u.role, branchId: u.branchId,
            }));
          } catch (e) {
            console.error("Bundle: systemUsers fetch failed", e);
            return [];
          }
        })(),
      ]);

      res.json({ employees, stats, systemUsers });
    } catch (error) {
      console.error("Error fetching branch employees bundle:", error);
      res.status(500).json({ error: "فشل في جلب بيانات الموظفين المجمعة" });
    }
  });

  // Employee reports bundle - server-side filtered for performance
  app.get("/api/employee-reports/bundle", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      const queryBranchId = req.query.branchId as string | undefined;
      const month = req.query.month as string | undefined; // format: YYYY-MM
      const allowedBranches = getAllowedBranchIds(req);
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }

      const monthStart = month ? `${month}-01` : undefined;
      let monthEnd: string | undefined;
      if (month) {
        const [y, m] = month.split("-").map(Number);
        const lastDay = new Date(y, m, 0).getDate();
        monthEnd = `${month}-${String(lastDay).padStart(2, "0")}`;
      }

      const [employees, attendance, schedules, signedTimesheets, salaryDeductions] = await Promise.all([
        (async () => {
          try {
            if (allowedBranches === null) {
              if (queryBranchId && queryBranchId !== "all") {
                return await storage.getBranchEmployeesByBranch(queryBranchId);
              }
              return await storage.getAllBranchEmployees();
            } else if (allowedBranches.length > 0) {
              if (queryBranchId && queryBranchId !== "all" && allowedBranches.includes(queryBranchId)) {
                return await storage.getBranchEmployeesByBranch(queryBranchId);
              }
              const allEmps = await Promise.all(
                allowedBranches.map(branchId => storage.getBranchEmployeesByBranch(branchId))
              );
              return allEmps.flat();
            }
            return [];
          } catch (e) { return []; }
        })(),
        (async () => {
          try {
            const filters: any = {};
            if (branchFilter.singleBranchId) filters.branchId = branchFilter.singleBranchId;
            if (monthStart) filters.startDate = monthStart;
            if (monthEnd) filters.endDate = monthEnd;
            let records = await storage.getAllAttendanceRecords(filters);
            if (branchFilter.branchIds !== null && !branchFilter.singleBranchId) {
              const allowedSet = new Set(branchFilter.branchIds);
              records = records.filter((r: any) => allowedSet.has(r.branchId));
            }
            return records;
          } catch (e) { return []; }
        })(),
        (async () => {
          try {
            if (!monthStart || !monthEnd) return [];
            if (branchFilter.singleBranchId) {
              return await storage.getEmployeeSchedulesByBranchAndDateRange(
                branchFilter.singleBranchId, monthStart, monthEnd
              );
            }
            if (branchFilter.branchIds && branchFilter.branchIds.length > 0) {
              const allSchedules = await Promise.all(
                branchFilter.branchIds.map(bid =>
                  storage.getEmployeeSchedulesByBranchAndDateRange(bid, monthStart!, monthEnd!).catch(() => [])
                )
              );
              return allSchedules.flat();
            }
            return [];
          } catch (e) { return []; }
        })(),
        (async () => {
          try {
            if (!monthStart || !monthEnd) return [];
            if (branchFilter.singleBranchId) {
              return await storage.getFinalizedTimesheetEntriesByBranchAndDateRange(
                branchFilter.singleBranchId, monthStart, monthEnd
              );
            }
            if (branchFilter.branchIds && branchFilter.branchIds.length > 0) {
              const allReports = await Promise.all(
                branchFilter.branchIds.map(bid =>
                  storage.getFinalizedTimesheetEntriesByBranchAndDateRange(bid, monthStart!, monthEnd!).catch(() => [])
                )
              );
              return allReports.flat();
            }
            return [];
          } catch (e) { return []; }
        })(),
        (async () => {
          try {
            if (!month) return [];
            if (branchFilter.singleBranchId) {
              return await storage.getSalaryDeductionsByBranchAndMonth(branchFilter.singleBranchId, month);
            }
            if (branchFilter.branchIds && branchFilter.branchIds.length > 0) {
              const all = await Promise.all(
                branchFilter.branchIds.map(bid =>
                  storage.getSalaryDeductionsByBranchAndMonth(bid, month).catch(() => [])
                )
              );
              return all.flat();
            }
            // Admin all-branches scope (branchIds === null, hasAccess === true)
            if (branchFilter.branchIds === null) {
              return await storage.getAllSalaryDeductionsByMonth(month);
            }
            return [];
          } catch (e) { return []; }
        })(),
      ]);

      res.json({ employees, attendance, schedules, signedTimesheets, salaryDeductions });
    } catch (error) {
      console.error("Error fetching employee reports bundle:", error);
      res.status(500).json({ error: "فشل في جلب بيانات تقارير الموظفين" });
    }
  });

  // ===== Salary Deductions CRUD - السُلف والخصومات اليدوية =====
  app.get("/api/salary-deductions", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      const branchId = req.query.branchId as string | undefined;
      const month = req.query.month as string | undefined;
      const employeeIdParam = req.query.branchEmployeeId as string | undefined;

      if (employeeIdParam && month) {
        const eid = parseInt(employeeIdParam, 10);
        if (Number.isNaN(eid)) return res.status(400).json({ error: "رقم الموظف غير صحيح" });
        const emp = await storage.getBranchEmployee(eid);
        if (!emp) return res.status(404).json({ error: "الموظف غير موجود" });
        const hasAccess = await canAccessBranch(req, emp.branchId);
        if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول" });
        const rows = await storage.getSalaryDeductionsByEmployeeAndMonth(eid, month);
        return res.json(rows);
      }

      if (!branchId || !month) {
        return res.status(400).json({ error: "branchId و month مطلوبان" });
      }
      const hasAccess = await canAccessBranch(req, branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول" });
      const rows = await storage.getSalaryDeductionsByBranchAndMonth(branchId, month);
      res.json(rows);
    } catch (error) {
      console.error("Error fetching salary deductions:", error);
      res.status(500).json({ error: "فشل في جلب السُلف والخصومات" });
    }
  });

  app.post("/api/salary-deductions", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const { insertSalaryDeductionSchema } = await import("@shared/schema");
      const parsed = insertSalaryDeductionSchema.safeParse({
        ...req.body,
        createdBy: (req as any).user?.id,
      });
      if (!parsed.success) {
        return res.status(400).json({ error: "بيانات غير صحيحة", details: parsed.error.errors });
      }
      const emp = await storage.getBranchEmployee(parsed.data.branchEmployeeId);
      if (!emp) return res.status(404).json({ error: "الموظف غير موجود" });
      if (emp.branchId !== parsed.data.branchId) {
        return res.status(400).json({ error: "الفرع لا يطابق فرع الموظف" });
      }
      const hasAccess = await canAccessBranch(req, parsed.data.branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول" });
      const lock = await storage.getSalaryClosureByBranchAndMonth(parsed.data.branchId, parsed.data.month);
      if (lock && lock.status === "closed") {
        return res.status(423).json({ error: "هذا الشهر مغلق للرواتب — لا يمكن إضافة سلف/خصومات. أعد فتح الإغلاق أولاً." });
      }
      const row = await storage.createSalaryDeduction(parsed.data);
      res.status(201).json(row);
    } catch (error) {
      console.error("Error creating salary deduction:", error);
      res.status(500).json({ error: "فشل في إضافة السلفة/الخصم" });
    }
  });

  app.put("/api/salary-deductions/:id", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (Number.isNaN(id)) return res.status(400).json({ error: "رقم غير صحيح" });
      const existing = await storage.getSalaryDeduction(id);
      if (!existing) return res.status(404).json({ error: "السجل غير موجود" });
      const hasAccess = await canAccessBranch(req, existing.branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول" });
      const lockPut = await storage.getSalaryClosureByBranchAndMonth(existing.branchId, existing.month);
      if (lockPut && lockPut.status === "closed") {
        return res.status(423).json({ error: "هذا الشهر مغلق للرواتب — لا يمكن تعديل السلف/الخصومات. أعد فتح الإغلاق أولاً." });
      }
      // Lock down: only allow editing safe fields. Immutable: branchId, branchEmployeeId, createdBy, month, id, timestamps.
      const { z } = await import("zod");
      const updateSchema = z.object({
        type: z.enum(["advance", "deduction", "loan_installment", "penalty", "other"]).optional(),
        amount: z.number().positive().optional(),
        description: z.string().nullable().optional(),
      }).strict();
      const parsed = updateSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "بيانات غير صحيحة (الحقول المسموح تعديلها: النوع، المبلغ، الوصف)", details: parsed.error.errors });
      }
      const row = await storage.updateSalaryDeduction(id, parsed.data);
      res.json(row);
    } catch (error) {
      console.error("Error updating salary deduction:", error);
      res.status(500).json({ error: "فشل في تحديث السلفة/الخصم" });
    }
  });

  app.delete("/api/salary-deductions/:id", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (Number.isNaN(id)) return res.status(400).json({ error: "رقم غير صحيح" });
      const existing = await storage.getSalaryDeduction(id);
      if (!existing) return res.status(404).json({ error: "السجل غير موجود" });
      const hasAccess = await canAccessBranch(req, existing.branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول" });
      const lockDel = await storage.getSalaryClosureByBranchAndMonth(existing.branchId, existing.month);
      if (lockDel && lockDel.status === "closed") {
        return res.status(423).json({ error: "هذا الشهر مغلق للرواتب — لا يمكن حذف السلف/الخصومات. أعد فتح الإغلاق أولاً." });
      }
      await storage.deleteSalaryDeduction(id);
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting salary deduction:", error);
      res.status(500).json({ error: "فشل في حذف السلفة/الخصم" });
    }
  });

  // =====================================================
  // Salary Closures - إغلاق الرواتب الشهري (احتساب على الخادم + لقطة ثابتة + قفل)
  // =====================================================
  // يجلب البيانات الخام لفرع/شهر واحد ثم يحسبها مركزياً على الخادم.
  const fetchSalaryClosingRaw = async (branchId: string, month: string): Promise<SalaryClosingRaw> => {
    const monthStart = `${month}-01`;
    const [y, m] = month.split("-").map(Number);
    const lastDay = new Date(y, m, 0).getDate();
    const monthEnd = `${month}-${String(lastDay).padStart(2, "0")}`;
    const [employees, attendance, schedules, signedTimesheets, deductions] = await Promise.all([
      storage.getBranchEmployeesByBranch(branchId).catch(() => []),
      storage.getAllAttendanceRecords({ branchId, startDate: monthStart, endDate: monthEnd }).catch(() => []),
      storage.getEmployeeSchedulesByBranchAndDateRange(branchId, monthStart, monthEnd).catch(() => []),
      storage.getFinalizedTimesheetEntriesByBranchAndDateRange(branchId, monthStart, monthEnd).catch(() => []),
      storage.getSalaryDeductionsByBranchAndMonth(branchId, month).catch(() => []),
    ]);
    return { branchId, month, employees, attendance, schedules, signedTimesheets, deductions };
  };

  const currentUserName = (req: any): string => {
    const u = req.currentUser;
    if (!u) return "غير معروف";
    return [u.firstName, u.lastName].filter(Boolean).join(" ") || u.username || "غير معروف";
  };

  const isValidMonth = (m: any): m is string => typeof m === "string" && /^\d{4}-\d{2}$/.test(m);

  // معاينة (احتساب حيّ على الخادم — غير محفوظ) قبل الإغلاق
  app.get("/api/salary-closing/preview", isAuthenticated, requirePermission("salary_closing", "view"), async (req, res) => {
    try {
      const branchId = req.query.branchId as string | undefined;
      const month = req.query.month as string | undefined;
      if (!branchId || branchId === "all") return res.status(400).json({ error: "اختر فرعاً محدداً" });
      if (!isValidMonth(month)) return res.status(400).json({ error: "صيغة الشهر يجب أن تكون YYYY-MM" });
      const hasAccess = await canAccessBranch(req, branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });

      const existing = await storage.getSalaryClosureByBranchAndMonth(branchId, month);
      const isLocked = !!existing && existing.status === "closed";

      // عند القفل: نعيد اللقطة الثابتة المحفوظة (مصدر الحقيقة) بدل إعادة الحساب الحي
      if (isLocked && existing) {
        const savedLines = await storage.getSalaryClosureLines(existing.id);
        const lines = savedLines.map((l: any) => ({
          ...l,
          presentDates: l.presentDates ?? [],
          absentDates: l.absentDates ?? [],
          // اللقطة تخزّن أيام الغياب مجمّعة؛ نعرضها كأيام صريحة للعرض فقط
          absentDatesExplicit: l.absentDates ?? [],
          absentDatesMissing: [],
          offDates: l.offDates ?? [],
          manualDeductions: l.manualDeductions ?? [],
        }));
        return res.json({
          lines,
          totals: {
            employeeCount: existing.employeeCount,
            totalBase: existing.totalBase,
            totalAllowances: existing.totalAllowances,
            totalGross: existing.totalGross,
            totalAbsenceDeduction: existing.totalAbsenceDeduction,
            totalSocialInsurance: existing.totalSocialInsurance,
            totalManualDeductions: existing.totalManualDeductions,
            totalNet: existing.totalNet,
          },
          unlinked: [],
          unlinkedSummary: { totalRecords: existing.unlinkedCount || 0, presentRecords: 0, totalHours: 0 },
          warnings: (existing.warnings as any) || [],
          closure: existing,
          isLocked: true,
        });
      }

      const raw = await fetchSalaryClosingRaw(branchId, month);
      const result = computeSalaryClosing(raw);
      res.json({ ...result, closure: existing || null, isLocked });
    } catch (error) {
      console.error("Error computing salary closing preview:", error);
      res.status(500).json({ error: "فشل في حساب معاينة الإغلاق" });
    }
  });

  // اللقطة المحفوظة (إن وُجدت) لفرع/شهر
  app.get("/api/salary-closing", isAuthenticated, requirePermission("salary_closing", "view"), async (req, res) => {
    try {
      const branchId = req.query.branchId as string | undefined;
      const month = req.query.month as string | undefined;
      if (!branchId || branchId === "all") return res.status(400).json({ error: "اختر فرعاً محدداً" });
      if (!isValidMonth(month)) return res.status(400).json({ error: "صيغة الشهر يجب أن تكون YYYY-MM" });
      const hasAccess = await canAccessBranch(req, branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      const closure = await storage.getSalaryClosureByBranchAndMonth(branchId, month);
      if (!closure) return res.json({ closure: null, lines: [] });
      const lines = await storage.getSalaryClosureLines(closure.id);
      res.json({ closure, lines });
    } catch (error) {
      console.error("Error fetching salary closure:", error);
      res.status(500).json({ error: "فشل في جلب اللقطة المحفوظة" });
    }
  });

  // قائمة الإغلاقات (سجل تاريخي)
  app.get("/api/salary-closing/list", isAuthenticated, requirePermission("salary_closing", "view"), async (req, res) => {
    try {
      const allowed = getAllowedBranchIds(req);
      const closures = await storage.listSalaryClosures(allowed);
      res.json(closures);
    } catch (error) {
      console.error("Error listing salary closures:", error);
      res.status(500).json({ error: "فشل في جلب سجل الإغلاقات" });
    }
  });

  // إغلاق الشهر: يعيد الحساب على الخادم ويحفظ لقطة ثابتة ويقفل
  app.post("/api/salary-closing/close", isAuthenticated, requirePermission("salary_closing", "edit"), async (req, res) => {
    try {
      const { branchId, month, acknowledgeWarnings, notes } = req.body || {};
      if (!branchId || branchId === "all") return res.status(400).json({ error: "اختر فرعاً محدداً" });
      if (!isValidMonth(month)) return res.status(400).json({ error: "صيغة الشهر يجب أن تكون YYYY-MM" });
      const hasAccess = await canAccessBranch(req, branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بإغلاق هذا الفرع" });

      const existing = await storage.getSalaryClosureByBranchAndMonth(branchId, month);
      if (existing && existing.status === "closed") {
        return res.status(409).json({ error: "هذا الشهر مغلق بالفعل لهذا الفرع. أعد فتحه أولاً للتعديل." });
      }

      const raw = await fetchSalaryClosingRaw(branchId, month);
      const result = computeSalaryClosing(raw);

      if (result.lines.length === 0) {
        return res.status(400).json({ error: "لا يوجد موظفون فعّالون لهذا الفرع/الشهر." });
      }

      // حماية من الإغلاق الخاطئ: تحذيرات صفر بيانات لموظف نشط تتطلب تأكيداً صريحاً
      const blockingWarnings = result.warnings.filter((w) => w.code === "no_work_at_all");
      if (blockingWarnings.length > 0 && !acknowledgeWarnings) {
        return res.status(422).json({
          error: "توجد تحذيرات تتطلب المراجعة قبل الإغلاق",
          requiresAcknowledgement: true,
          warnings: result.warnings,
        });
      }

      const userId = req.currentUser?.id;
      const userName = currentUserName(req);
      const closurePayload = {
        branchId,
        month,
        status: "closed",
        employeeCount: result.totals.employeeCount,
        totalBase: result.totals.totalBase,
        totalAllowances: result.totals.totalAllowances,
        totalGross: result.totals.totalGross,
        totalAbsenceDeduction: result.totals.totalAbsenceDeduction,
        totalSocialInsurance: result.totals.totalSocialInsurance,
        totalManualDeductions: result.totals.totalManualDeductions,
        totalNet: result.totals.totalNet,
        unlinkedCount: result.unlinkedSummary.totalRecords,
        warningsCount: result.warnings.length,
        warnings: result.warnings as any,
        notes: notes || null,
        closedBy: userId,
        closedByName: userName,
        closedAt: new Date(),
        // مسح بيانات إعادة الفتح عند الإغلاق من جديد
        reopenedBy: null,
        reopenedByName: null,
        reopenedAt: null,
        reopenReason: null,
      };
      const linePayloads = result.lines.map((l) => ({
        branchEmployeeId: l.branchEmployeeId,
        employeeNumber: l.employeeNumber,
        employeeName: l.employeeName,
        jobTitle: l.jobTitle,
        nationality: l.nationality,
        bankName: l.bankName,
        bankAccountNumber: l.bankAccountNumber,
        presentDays: l.presentDays,
        absentDays: l.absentDays,
        offDays: l.offDays,
        scheduledWorkDays: l.scheduledWorkDays,
        scheduledHours: l.scheduledHours,
        lateDays: l.lateDays,
        totalHours: l.totalHours,
        baseSalary: l.baseSalary,
        allowances: l.allowances,
        grossSalary: l.grossSalary,
        dailyRate: l.dailyRate,
        absenceDeduction: l.absenceDeduction,
        socialInsurance: l.socialInsurance,
        manualDeductionsTotal: l.manualDeductionsTotal,
        netSalary: l.netSalary,
        dataSource: l.dataSource,
        noWorkAtAll: l.noWorkAtAll,
        manualDeductions: l.manualDeductions as any,
        presentDates: l.presentDates as any,
        absentDates: l.absentDates as any,
        offDates: l.offDates as any,
      }));

      // إذا كان هناك إغلاق سابق تمت إعادة فتحه، نعيد استخدام نفس الصف (نمنع تعارض المفتاح الفريد)
      let closure;
      if (existing && existing.status === "reopened") {
        closure = await storage.replaceSalaryClosureWithLines(existing.id, closurePayload as any, linePayloads as any);
      } else {
        closure = await storage.createSalaryClosureWithLines(closurePayload as any, linePayloads as any);
      }
      res.status(201).json({ success: true, closure });
    } catch (error: any) {
      console.error("Error closing salary month:", error);
      if (String(error?.message || "").includes("duplicate") || error?.code === "23505") {
        return res.status(409).json({ error: "هذا الشهر مغلق بالفعل لهذا الفرع." });
      }
      res.status(500).json({ error: "فشل في إغلاق الشهر" });
    }
  });

  // إعادة فتح إغلاق (للمدير فقط) مع تسجيل السبب
  app.post("/api/salary-closing/:id/reopen", isAuthenticated, requirePermission("salary_closing", "edit"), async (req, res) => {
    try {
      if (!isUserAdmin(req)) return res.status(403).json({ error: "إعادة الفتح متاحة للمدير فقط" });
      const id = parseInt(req.params.id, 10);
      if (Number.isNaN(id)) return res.status(400).json({ error: "رقم غير صحيح" });
      const { reason } = req.body || {};
      if (!reason || String(reason).trim().length < 3) {
        return res.status(400).json({ error: "يجب إدخال سبب إعادة الفتح" });
      }
      const closure = await storage.getSalaryClosureById(id);
      if (!closure) return res.status(404).json({ error: "الإغلاق غير موجود" });
      const hasAccess = await canAccessBranch(req, closure.branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      const updated = await storage.reopenSalaryClosure(id, {
        reopenedBy: req.currentUser?.id,
        reopenedByName: currentUserName(req),
        reopenReason: String(reason).trim(),
      });
      res.json({ success: true, closure: updated });
    } catch (error) {
      console.error("Error reopening salary closure:", error);
      res.status(500).json({ error: "فشل في إعادة فتح الإغلاق" });
    }
  });

  // ربط سجل حضور يتيم بموظف (قبل الإغلاق) — IDOR-safe
  app.post("/api/salary-closing/link-attendance", isAuthenticated, requirePermission("salary_closing", "edit"), async (req, res) => {
    try {
      const { attendanceId, branchEmployeeId } = req.body || {};
      const aId = parseInt(attendanceId, 10);
      const beId = parseInt(branchEmployeeId, 10);
      if (Number.isNaN(aId) || Number.isNaN(beId)) return res.status(400).json({ error: "بيانات غير صحيحة" });
      const record = await storage.getAttendanceRecord(aId);
      if (!record) return res.status(404).json({ error: "سجل الحضور غير موجود" });
      const employee = await storage.getBranchEmployee(beId);
      if (!employee) return res.status(404).json({ error: "الموظف غير موجود" });
      // يجب أن يكون السجل والموظف في نفس الفرع، وللمستخدم صلاحية على هذا الفرع
      if (record.branchId !== employee.branchId) {
        return res.status(400).json({ error: "الموظف من فرع مختلف عن سجل الحضور" });
      }
      const hasAccess = await canAccessBranch(req, record.branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });
      // منع تعديل الربط على شهر مغلق (تثبيت اللقطة)
      const recDate = (record as any).attendanceDate || (record as any).date;
      const recMonth = typeof recDate === "string" ? recDate.slice(0, 7) : "";
      if (recMonth) {
        const lock = await storage.getSalaryClosureByBranchAndMonth(record.branchId, recMonth);
        if (lock && lock.status === "closed") {
          return res.status(423).json({ error: "هذا الشهر مغلق للرواتب — لا يمكن ربط سجلات الحضور. أعد فتح الإغلاق أولاً." });
        }
      }
      const updated = await storage.updateAttendanceRecord(aId, {
        branchEmployeeId: beId,
        employeeId: employee.linkedUserId || record.employeeId,
      });
      res.json({ success: true, record: updated });
    } catch (error) {
      console.error("Error linking attendance record:", error);
      res.status(500).json({ error: "فشل في ربط سجل الحضور" });
    }
  });

  // ربط مجموعة سجلات حضور بموظف واحد دفعة واحدة (زر "ربط الكل")
  app.post("/api/salary-closing/link-attendance-bulk", isAuthenticated, requirePermission("salary_closing", "edit"), async (req, res) => {
    try {
      const { attendanceIds, branchEmployeeId } = req.body || {};
      const beId = parseInt(branchEmployeeId, 10);
      if (Number.isNaN(beId) || !Array.isArray(attendanceIds) || attendanceIds.length === 0) {
        return res.status(400).json({ error: "بيانات غير صحيحة" });
      }
      const ids = Array.from(
        new Set(attendanceIds.map((x: any) => parseInt(x, 10)).filter((n: number) => !Number.isNaN(n)))
      );
      if (ids.length === 0) return res.status(400).json({ error: "لا توجد سجلات صالحة" });
      const employee = await storage.getBranchEmployee(beId);
      if (!employee) return res.status(404).json({ error: "الموظف غير موجود" });
      const hasAccess = await canAccessBranch(req, employee.branchId);
      if (!hasAccess) return res.status(403).json({ error: "غير مصرح بالوصول لهذا الفرع" });

      let linked = 0;
      const skipped: Array<{ id: number; reason: string }> = [];
      const lockCache = new Map<string, boolean>();
      for (const aId of ids) {
        const record = await storage.getAttendanceRecord(aId);
        if (!record) { skipped.push({ id: aId, reason: "السجل غير موجود" }); continue; }
        if (record.branchId !== employee.branchId) { skipped.push({ id: aId, reason: "فرع مختلف" }); continue; }
        const recDate = (record as any).attendanceDate || (record as any).date;
        const recMonth = typeof recDate === "string" ? recDate.slice(0, 7) : "";
        if (recMonth) {
          const cacheKey = `${record.branchId}|${recMonth}`;
          let locked = lockCache.get(cacheKey);
          if (locked === undefined) {
            const lock = await storage.getSalaryClosureByBranchAndMonth(record.branchId, recMonth);
            locked = !!lock && lock.status === "closed";
            lockCache.set(cacheKey, locked);
          }
          if (locked) { skipped.push({ id: aId, reason: "الشهر مغلق" }); continue; }
        }
        await storage.updateAttendanceRecord(aId, {
          branchEmployeeId: beId,
          employeeId: employee.linkedUserId || record.employeeId,
        });
        linked++;
      }
      res.json({ success: true, linked, skipped });
    } catch (error) {
      console.error("Error bulk linking attendance records:", error);
      res.status(500).json({ error: "فشل في ربط سجلات الحضور" });
    }
  });

  // Shift management bundle - combines multiple queries into one
  app.get("/api/shift-management/bundle", isAuthenticated, requirePermission("shifts", "view"), async (req, res) => {
    try {
      const branchId = req.query.branchId as string;
      const startDate = req.query.startDate as string;
      const endDate = req.query.endDate as string;

      if (!branchId || branchId === "all") {
        return res.json({ shiftProfiles: [], employees: [], schedules: [], attendance: [], weeklyLock: [] });
      }

      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول" });
        }
      }

      const [shiftProfiles, employees, schedules, attendance, weeklyLock] = await Promise.all([
        storage.getBranchShiftProfiles(branchId).catch(() => []),
        storage.getBranchEmployeesByBranch(branchId).then(
          emps => emps.filter((e: any) => e.status === "active")
        ).catch(() => []),
        (startDate && endDate)
          ? storage.getEmployeeSchedulesByBranchAndDateRange(branchId, startDate, endDate).catch(() => [])
          : Promise.resolve([]),
        (startDate && endDate)
          ? storage.getAllAttendanceRecords({ branchId, startDate, endDate }).catch(() => [])
          : Promise.resolve([]),
        (startDate)
          ? db.select().from(weeklyScheduleLocks).where(
              and(
                eq(weeklyScheduleLocks.branchId, branchId),
                eq(weeklyScheduleLocks.weekStartDate, startDate)
              )
            ).catch(() => [])
          : Promise.resolve([]),
      ]);

      res.json({ shiftProfiles, employees, schedules, attendance, weeklyLock });
    } catch (error) {
      console.error("Error fetching shift management bundle:", error);
      res.status(500).json({ error: "فشل في جلب بيانات إدارة الورديات" });
    }
  });

  // Get all branch employees or filter by branch
  app.get("/api/branch-employees", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      // SECURITY: Enforce branch filtering for non-admin users
      const queryBranchId = req.query.branchId as string | undefined;
      const countOnly = req.query.countOnly === 'true';
      // HR is cross-branch by design: HR managers (and hr_management:view) get
      // READ access across all branches on this GET, matching the HR Hub bundle.
      const allowedBranches = hasCrossBranchHrReadAccess(req) ? null : getAllowedBranchIds(req);
      
      // Fast count path - uses cached data or lightweight query
      if (countOnly) {
        const cacheKey = `branch_employees_count:${allowedBranches === null ? 'all' : allowedBranches.join(',')}`;
        const cached = getCachedResponse(cacheKey, 60000);
        if (cached !== null) return res.json(cached);
        
        let employees;
        if (allowedBranches === null) {
          employees = await storage.getAllBranchEmployees();
        } else if (allowedBranches.length > 0) {
          const allEmployees = await Promise.all(
            allowedBranches.map(branchId => storage.getBranchEmployeesByBranch(branchId))
          );
          employees = allEmployees.flat();
        } else {
          return res.json(0);
        }
        const count = employees.filter((e: any) => e.status === 'active').length;
        setCachedResponse(cacheKey, count);
        return res.json(count);
      }
      
      let employees;
      
      // Admin or user with all branches access (allowedBranches === null)
      if (allowedBranches === null) {
        if (queryBranchId) {
          employees = await storage.getBranchEmployeesByBranch(queryBranchId);
        } else {
          employees = await storage.getAllBranchEmployees();
        }
      } else if (allowedBranches.length > 0) {
        // User has access to specific branches
        if (queryBranchId && allowedBranches.includes(queryBranchId)) {
          // Filter by requested branch if user has access
          employees = await storage.getBranchEmployeesByBranch(queryBranchId);
        } else {
          // Get employees from all allowed branches
          const allEmployees = await Promise.all(
            allowedBranches.map(branchId => storage.getBranchEmployeesByBranch(branchId))
          );
          employees = allEmployees.flat();
        }
      } else {
        // No branch access
        return res.json([]);
      }
      
      const statusFilter = req.query.status as string | undefined;
      if (statusFilter) {
        employees = employees.filter((e: any) => e.status === statusFilter);
      }

      res.json(employees);
    } catch (error) {
      console.error("Error fetching branch employees:", error);
      res.status(500).json({ error: "فشل في جلب بيانات الموظفين" });
    }
  });

  // Get branch employees statistics
  app.get("/api/branch-employees/stats", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      // SECURITY: Enforce branch filtering for non-admin users
      const queryBranchId = req.query.branchId as string | undefined;
      // HR cross-branch READ elevation (GET) — see /api/branch-employees above.
      const allowedBranches = hasCrossBranchHrReadAccess(req) ? null : getAllowedBranchIds(req);
      
      // Admin or user with all branches access
      if (allowedBranches === null) {
        const stats = await storage.getBranchEmployeeStats(queryBranchId ?? undefined);
        return res.json(stats);
      }
      
      // User has specific branch access
      if (allowedBranches.length > 0) {
        if (queryBranchId && allowedBranches.includes(queryBranchId)) {
          const stats = await storage.getBranchEmployeeStats(queryBranchId);
          return res.json(stats);
        }
        const branchStatsResults = await Promise.all(
          allowedBranches.map(bid => storage.getBranchEmployeeStats(bid))
        );
        const natMap = new Map<string, number>();
        const jobMap = new Map<string, number>();
        const statusMap = new Map<string, number>();
        let totalEmployees = 0;
        let totalSalaries = 0;
        for (const s of branchStatsResults) {
          totalEmployees += s.totalEmployees || 0;
          totalSalaries += s.totalSalaries || 0;
          for (const x of s.byNationality || []) natMap.set(x.nationality, (natMap.get(x.nationality) || 0) + x.count);
          for (const x of s.byJobTitle || []) jobMap.set(x.jobTitle, (jobMap.get(x.jobTitle) || 0) + x.count);
          for (const x of s.byStatus || []) statusMap.set(x.status, (statusMap.get(x.status) || 0) + x.count);
        }
        return res.json({
          totalEmployees,
          totalSalaries,
          byNationality: Array.from(natMap.entries()).map(([nationality, count]) => ({ nationality, count })),
          byJobTitle: Array.from(jobMap.entries()).map(([jobTitle, count]) => ({ jobTitle, count })),
          byStatus: Array.from(statusMap.entries()).map(([status, count]) => ({ status, count })),
        });
      }
      
      // No access - return empty stats
      res.json({ totalEmployees: 0, totalSalaries: 0, byNationality: [], byJobTitle: [], byStatus: [] });
    } catch (error) {
      console.error("Error fetching branch employee stats:", error);
      res.status(500).json({ error: "فشل في جلب إحصائيات الموظفين" });
    }
  });

  // Get single branch employee
  app.get("/api/branch-employees/:id", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      
      const employee = await storage.getBranchEmployee(id);
      if (!employee) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      
      // SECURITY: Verify branch access for non-admin users.
      // HR is cross-branch by design: HR managers (and hr_management:view) get
      // READ access to records across all branches (GET only).
      if (!isUserAdmin(req) && !hasCrossBranchHrReadAccess(req) && employee.branchId) {
        const hasAccess = await canAccessBranch(req, employee.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بالوصول لهذا الموظف" });
        }
      }
      
      res.json(employee);
    } catch (error) {
      console.error("Error fetching branch employee:", error);
      res.status(500).json({ error: "فشل في جلب بيانات الموظف" });
    }
  });

  // Create branch employee
  app.post("/api/branch-employees", isAuthenticated, requirePermission("branch_employees", "create"), async (req, res) => {
    try {
      const { insertBranchEmployeeSchema } = await import("@shared/schema");
      const parsed = insertBranchEmployeeSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "بيانات الموظف غير صحيحة", details: parsed.error.errors });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req) && parsed.data.branchId) {
        const hasAccess = await canAccessBranch(req, parsed.data.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بإضافة موظف لهذا الفرع" });
        }
      }
      
      const allEmployees = await storage.getAllBranchEmployees();
      const duplicate = allEmployees.find((e: any) => 
        e.employeeName?.trim() === parsed.data.employeeName?.trim() && 
        e.status === "active"
      );
      if (duplicate) {
        return res.status(400).json({ 
          error: `الموظف "${parsed.data.employeeName}" مسجل بالفعل كموظف نشط. يرجى نقله من صفحة الموظفين بدلاً من إضافة سجل جديد.`
        });
      }

      const changedBy = (req as any).currentUser?.id;
      const employee = await storage.createBranchEmployee(parsed.data, changedBy);
      res.status(201).json(employee);
    } catch (error) {
      console.error("Error creating branch employee:", error);
      res.status(500).json({ error: "فشل في إضافة الموظف" });
    }
  });

  // Status history for a branch employee
  app.get("/api/branch-employees/:id/status-history", isAuthenticated, requirePermission("branch_employees", "view"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) return res.status(400).json({ error: "معرف الموظف غير صحيح" });
      const employee = await storage.getBranchEmployee(id);
      if (!employee) return res.status(404).json({ error: "الموظف غير موجود" });
      if (!isUserAdmin(req)) {
        const ok = await canAccessBranch(req, employee.branchId);
        if (!ok) return res.status(403).json({ error: "غير مصرح بعرض سجل هذا الموظف" });
      }
      const history = await storage.getEmployeeStatusHistory(id);
      res.json(history);
    } catch (error) {
      console.error("Error fetching employee status history:", error);
      res.status(500).json({ error: "فشل في جلب سجل حالة الموظف" });
    }
  });

  // Update branch employee
  app.put("/api/branch-employees/:id", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      
      // SECURITY: First fetch employee to check branch access
      const existingEmployee = await storage.getBranchEmployee(id);
      if (!existingEmployee) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      
      // Verify user has access to this employee's current branch
      if (!isUserAdmin(req) && existingEmployee.branchId) {
        const hasAccess = await canAccessBranch(req, existingEmployee.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بتعديل بيانات موظف هذا الفرع" });
        }
      }
      
      const { insertBranchEmployeeSchema } = await import("@shared/schema");
      const parsed = insertBranchEmployeeSchema.partial().safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "بيانات الموظف غير صحيحة", details: parsed.error.errors });
      }
      
      // SECURITY: If changing branch, verify access to new branch too
      if (!isUserAdmin(req) && parsed.data.branchId && parsed.data.branchId !== existingEmployee.branchId) {
        const hasNewBranchAccess = await canAccessBranch(req, parsed.data.branchId);
        if (!hasNewBranchAccess) {
          return res.status(403).json({ error: "غير مصرح بنقل الموظف لهذا الفرع" });
        }
      }
      
      // Capture status change reason if provided (out-of-band field, not in insert schema)
      const statusChangeReason = typeof req.body?.statusChangeReason === "string"
        ? (req.body.statusChangeReason as string).trim() || undefined
        : undefined;
      const changedBy = (req as any).currentUser?.id;
      const employee = await storage.updateBranchEmployee(id, parsed.data, changedBy, statusChangeReason);
      res.json(employee);
    } catch (error) {
      console.error("Error updating branch employee:", error);
      res.status(500).json({ error: "فشل في تحديث بيانات الموظف" });
    }
  });

  // Delete branch employee - مدير النظام فقط
  app.delete("/api/branch-employees/:id", isAuthenticated, requirePermission("branch_employees", "delete"), async (req, res) => {
    try {
      // التحقق من صلاحية مدير النظام فقط
      const userRole = req.currentUser?.role;
      if (userRole !== "admin") {
        return res.status(403).json({ error: "غير مصرح - يمكن لمدير النظام فقط حذف الموظفين" });
      }
      
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      
      const success = await storage.deleteBranchEmployee(id);
      if (!success) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting branch employee:", error);
      res.status(500).json({ error: "فشل في حذف الموظف" });
    }
  });

  // Link branch employee to user account
  app.put("/api/branch-employees/:id/link-user", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });
      
      const { userId } = req.body;
      if (!userId) return res.status(400).json({ error: "معرف المستخدم مطلوب" });
      
      const existingEmp = await storage.getBranchEmployee(id);
      if (!existingEmp) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, existingEmp.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بربط موظف من هذا الفرع" });
        }
      }
      
      if (existingEmp.linkedUserId) {
        return res.status(400).json({ error: "هذا الموظف مرتبط بحساب بالفعل" });
      }
      const alreadyLinked = await storage.getBranchEmployeeByLinkedUserId(userId);
      if (alreadyLinked && alreadyLinked.id !== id) {
        return res.status(400).json({ error: "هذا الحساب مرتبط بموظف آخر بالفعل" });
      }

      const employee = await storage.linkBranchEmployeeToUser(id, userId);
      if (!employee) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      res.json(employee);
    } catch (error) {
      console.error("Error linking branch employee to user:", error);
      res.status(500).json({ error: "فشل في ربط الموظف بالمستخدم" });
    }
  });

  // إنشاء حساب دخول جديد لموظف وربطه به (بوابة الموظف)
  app.post("/api/branch-employees/:id/create-account", isAuthenticated, requirePermission("users", "create"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const { username, password } = req.body;
      if (!username || !password) {
        return res.status(400).json({ error: "اسم المستخدم وكلمة المرور مطلوبان" });
      }
      if (username.length < 3 || username.length > 50) {
        return res.status(400).json({ error: "اسم المستخدم يجب أن يكون بين 3 و 50 حرفاً" });
      }
      if (password.length < 8 || password.length > 128) {
        return res.status(400).json({ error: "كلمة المرور يجب أن تكون بين 8 و 128 حرفاً" });
      }
      if (!/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password)) {
        return res.status(400).json({ error: "كلمة المرور يجب أن تحتوي على حروف كبيرة وصغيرة وأرقام" });
      }

      const employee = await storage.getBranchEmployee(id);
      if (!employee) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      if (employee.linkedUserId) {
        return res.status(400).json({ error: "هذا الموظف مرتبط بحساب بالفعل" });
      }
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, employee.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بإنشاء حساب لموظف من هذا الفرع" });
        }
      }

      const existingUser = await storage.getUserByUsername(username);
      if (existingUser) {
        return res.status(400).json({ error: "اسم المستخدم مسجل مسبقاً" });
      }

      // استنتاج الاسم الأول والأخير من اسم الموظف
      const fullName = (employee.employeeName || "").trim();
      const nameParts = fullName.split(/\s+/);
      const firstName = nameParts[0] || fullName || username;
      const lastName = nameParts.length > 1 ? nameParts.slice(1).join(" ") : "";

      // إنشاء الحساب ومنح الصلاحية والربط بشكل ذري
      const user = await storage.createBranchEmployeeAccount({
        branchEmployeeId: id,
        username,
        password,
        firstName,
        lastName,
        branchId: employee.branchId || null,
      });

      const { password: _pw, ...safeUser } = user as any;
      res.status(201).json({ user: safeUser });
    } catch (error: any) {
      console.error("Error creating employee account:", error);
      if (error?.message === "هذا الموظف مرتبط بحساب بالفعل") {
        return res.status(400).json({ error: error.message });
      }
      res.status(500).json({ error: "فشل في إنشاء حساب الموظف" });
    }
  });

  // إعادة تعيين كلمة مرور حساب الموظف المرتبط
  app.post("/api/branch-employees/:id/reset-password", isAuthenticated, requirePermission("users", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const { password } = req.body;
      if (!password || password.length < 8 || password.length > 128) {
        return res.status(400).json({ error: "كلمة المرور يجب أن تكون بين 8 و 128 حرفاً" });
      }
      if (!/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password)) {
        return res.status(400).json({ error: "كلمة المرور يجب أن تحتوي على حروف كبيرة وصغيرة وأرقام" });
      }

      const employee = await storage.getBranchEmployee(id);
      if (!employee) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      if (!employee.linkedUserId) {
        return res.status(400).json({ error: "هذا الموظف غير مرتبط بحساب" });
      }
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, employee.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح" });
        }
      }

      await storage.updateUser(employee.linkedUserId, { password });
      res.json({ success: true });
    } catch (error) {
      console.error("Error resetting employee password:", error);
      res.status(500).json({ error: "فشل في إعادة تعيين كلمة المرور" });
    }
  });

  // فك ارتباط الموظف بحسابه (لا يحذف الحساب)
  app.post("/api/branch-employees/:id/unlink-user", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) return res.status(400).json({ error: "معرف غير صالح" });

      const employee = await storage.getBranchEmployee(id);
      if (!employee) {
        return res.status(404).json({ error: "الموظف غير موجود" });
      }
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, employee.branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح" });
        }
      }

      const updated = await storage.unlinkBranchEmployeeUser(id);
      res.json(updated);
    } catch (error) {
      console.error("Error unlinking branch employee:", error);
      res.status(500).json({ error: "فشل في فك الارتباط" });
    }
  });

  // ===== Employee Portal Settings (بوابتي) =====
  // Returns booleans for boolean keys and raw strings for value keys (numbers/enums),
  // filling in defaults for any key not yet stored.
  const buildPortalSettingsResponse = (settings: Record<string, string>): Record<string, boolean | string> => {
    const out: Record<string, boolean | string> = {};
    for (const key of Object.values(PORTAL_SETTING_KEYS)) {
      const raw = settings[key] ?? PORTAL_SETTING_DEFAULTS[key] ?? "";
      out[key] = PORTAL_BOOLEAN_KEYS.includes(key) ? raw === "true" : raw;
    }
    return out;
  };

  app.get("/api/admin/portal-settings", isAuthenticated, requirePermission("settings", "view"), async (_req, res) => {
    try {
      const settings = await storage.getAllPortalSettings();
      res.json(buildPortalSettingsResponse(settings));
    } catch (error) {
      console.error("Error getting portal settings:", error);
      res.status(500).json({ error: "فشل في جلب إعدادات البوابة" });
    }
  });

  app.put("/api/admin/portal-settings", isAuthenticated, requirePermission("settings", "edit"), async (req, res) => {
    try {
      const body = req.body as Record<string, unknown>;
      const allowedKeys = Object.values(PORTAL_SETTING_KEYS) as string[];
      const updates: Record<string, string> = {};
      for (const [key, val] of Object.entries(body)) {
        if (!allowedKeys.includes(key)) {
          return res.status(400).json({ error: `مفتاح غير صالح: ${key}` });
        }
        if (key === PORTAL_SETTING_KEYS.MAX_ADVANCE_AMOUNT) {
          const num = Number(val);
          if (!Number.isFinite(num) || num < 0) {
            return res.status(400).json({ error: "الحد الأقصى للسلفة يجب أن يكون رقماً موجباً" });
          }
          updates[key] = String(Math.floor(num));
        } else if (key === PORTAL_SETTING_KEYS.DEFAULT_LANGUAGE) {
          if (val !== "ar" && val !== "en") {
            return res.status(400).json({ error: "اللغة يجب أن تكون ar أو en" });
          }
          updates[key] = val;
        } else {
          updates[key] = val === true || val === "true" ? "true" : "false";
        }
      }
      for (const [key, val] of Object.entries(updates)) {
        await storage.setPortalSetting(key, val);
      }
      const settings = await storage.getAllPortalSettings();
      res.json(buildPortalSettingsResponse(settings));
    } catch (error) {
      console.error("Error updating portal settings:", error);
      res.status(500).json({ error: "فشل في تحديث إعدادات البوابة" });
    }
  });

  // ===== Portal account linking management (ربط الموظفين بالحسابات) =====
  // --- Helpers for matching employees to existing user accounts (phone first, then name) ---
  const normalizePhone = (p?: string | null): string => {
    if (!p) return "";
    let d = String(p).replace(/\D/g, "");
    if (d.startsWith("966")) d = d.slice(3);
    d = d.replace(/^0+/, "");
    return d.length >= 9 ? d.slice(-9) : d;
  };
  const normalizeName = (n?: string | null): string => {
    if (!n) return "";
    return String(n)
      .replace(/[\u064B-\u0652\u0670\u0640]/g, "") // Arabic diacritics + tatweel
      .replace(/[إأآا]/g, "ا")
      .replace(/ى/g, "ي")
      .replace(/ة/g, "ه")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  };
  // Returns a matching user for an employee, or null. matchType: "phone" | "name".
  const matchUserForEmployee = (
    emp: { phoneNumber?: string | null; employeeName?: string | null },
    candidates: { id: string; username: string | null; phone?: string | null; firstName?: string | null; lastName?: string | null }[],
  ): { user: (typeof candidates)[number]; matchType: "phone" | "name" } | null => {
    const empPhone = normalizePhone(emp.phoneNumber);
    if (empPhone && empPhone.length >= 9) {
      const byPhone = candidates.find((u) => normalizePhone(u.phone) === empPhone);
      if (byPhone) return { user: byPhone, matchType: "phone" };
    }
    const empName = normalizeName(emp.employeeName);
    if (empName) {
      const byName = candidates.find((u) => {
        const full = normalizeName(`${u.firstName || ""} ${u.lastName || ""}`);
        return full && full === empName;
      });
      if (byName) return { user: byName, matchType: "name" };
    }
    return null;
  };

  // List employees with their portal-account status, scoped to accessible branches.
  app.get("/api/admin/portal-accounts", isAuthenticated, requirePermission("users", "view"), async (req, res) => {
    try {
      const { branchIds, hasAccess } = getEffectiveBranchFilter(req);
      if (!hasAccess) return res.json([]);
      const [employees, branches] = await Promise.all([
        storage.getAllBranchEmployees(branchIds ? { branchIds } : undefined),
        storage.getAllBranches(),
      ]);
      const branchName = new Map(branches.map((b) => [b.id, b.name]));
      const linkedIds = employees.map((e) => e.linkedUserId).filter(Boolean) as string[];
      const usernameById = new Map<string, string>();
      await Promise.all(
        linkedIds.map(async (uid) => {
          const u = await storage.getUser(uid);
          if (u) usernameById.set(uid, u.username);
        }),
      );
      const rows = employees.map((e) => ({
        id: e.id,
        employeeName: e.employeeName,
        employeeNameEn: e.employeeNameEn,
        branchId: e.branchId,
        branchName: branchName.get(e.branchId) || e.branchId,
        status: e.status,
        hasAccount: !!e.linkedUserId,
        username: e.linkedUserId ? usernameById.get(e.linkedUserId) || null : null,
      }));
      res.json(rows);
    } catch (error: any) {
      console.error("Error listing portal accounts:", error);
      res.status(500).json({ error: "فشل في جلب حالة الحسابات" });
    }
  });

  // Suggest links between unlinked employees and EXISTING user accounts (phone first, then name).
  app.get("/api/admin/portal-accounts/suggestions", isAuthenticated, requirePermission("users", "view"), async (req, res) => {
    try {
      const { branchIds, hasAccess } = getEffectiveBranchFilter(req);
      if (!hasAccess) return res.json([]);
      const [employees, allEmployees, branches, users] = await Promise.all([
        storage.getAllBranchEmployees(branchIds ? { branchIds } : undefined),
        storage.getAllBranchEmployees(), // global, to exclude users linked in ANY branch
        storage.getAllBranches(),
        storage.getAllUsers(),
      ]);
      const branchName = new Map(branches.map((b) => [b.id, b.name]));
      // Candidate users = not linked to ANY employee globally, AND within the requester's branch scope.
      const linkedUserIds = new Set(
        allEmployees.map((e) => e.linkedUserId).filter(Boolean) as string[],
      );
      const allowedBranches = branchIds ? new Set(branchIds) : null; // null = admin/all
      const candidates = users.filter(
        (u) =>
          u.id &&
          !linkedUserIds.has(u.id) &&
          (allowedBranches ? !!u.branchId && allowedBranches.has(u.branchId) : true),
      );
      const claimed = new Set<string>(); // avoid suggesting the same user for two employees
      const suggestions: any[] = [];
      for (const emp of employees) {
        if (emp.linkedUserId) continue; // already linked
        if (emp.status !== "active") continue; // اقترح فقط الموظفين النشطين
        const pool = candidates.filter((u) => !claimed.has(u.id));
        const match = matchUserForEmployee(emp, pool as any);
        if (!match) continue;
        claimed.add(match.user.id);
        suggestions.push({
          employeeId: emp.id,
          employeeName: emp.employeeName,
          employeeNameEn: emp.employeeNameEn,
          branchId: emp.branchId,
          branchName: branchName.get(emp.branchId) || emp.branchId,
          userId: match.user.id,
          username: match.user.username,
          userFullName: `${match.user.firstName || ""} ${match.user.lastName || ""}`.trim(),
          matchType: match.matchType,
        });
      }
      res.json(suggestions);
    } catch (error: any) {
      console.error("Error building portal-account suggestions:", error);
      res.status(500).json({ error: "فشل في جلب اقتراحات الربط" });
    }
  });

  // Confirm and apply selected employee↔user links (admin reviewed).
  app.post("/api/admin/portal-accounts/confirm-links", isAuthenticated, requirePermission("branch_employees", "edit"), async (req, res) => {
    try {
      const links: { employeeId: number; userId: string }[] = Array.isArray(req.body?.links)
        ? req.body.links
            .map((l: any) => ({ employeeId: parseInt(l?.employeeId, 10), userId: String(l?.userId || "") }))
            .filter((l: any) => !isNaN(l.employeeId) && l.userId)
        : [];
      if (links.length === 0) {
        return res.status(400).json({ error: "لم يتم تحديد أي ارتباط" });
      }
      const linked: { employeeId: number; userId: string }[] = [];
      const skipped: { employeeId: number; reason: string }[] = [];
      for (const { employeeId, userId } of links) {
        const emp = await storage.getBranchEmployee(employeeId);
        if (!emp) { skipped.push({ employeeId, reason: "الموظف غير موجود" }); continue; }
        if (emp.status !== "active") { skipped.push({ employeeId, reason: "موظف غير نشط" }); continue; }
        if (emp.linkedUserId) { skipped.push({ employeeId, reason: "مرتبط بحساب بالفعل" }); continue; }
        if (!isUserAdmin(req)) {
          const ok = await canAccessBranch(req, emp.branchId);
          if (!ok) { skipped.push({ employeeId, reason: "غير مصرح" }); continue; }
        }
        const user = await storage.getUser(userId);
        if (!user) { skipped.push({ employeeId, reason: "الحساب غير موجود" }); continue; }
        // SECURITY: a branch-limited operator may only link to a user within their own branch scope.
        if (!isUserAdmin(req)) {
          if (!user.branchId || !(await canAccessBranch(req, user.branchId))) {
            skipped.push({ employeeId, reason: "الحساب خارج نطاق صلاحيتك" });
            continue;
          }
        }
        const alreadyLinked = await storage.getBranchEmployeeByLinkedUserId(userId);
        if (alreadyLinked && alreadyLinked.id !== employeeId) {
          skipped.push({ employeeId, reason: "الحساب مرتبط بموظف آخر" });
          continue;
        }
        try {
          const result = await storage.linkBranchEmployeeToUser(employeeId, userId);
          if (!result) { skipped.push({ employeeId, reason: "تعذّر الربط (تم ربطه للتو)" }); continue; }
          linked.push({ employeeId, userId });
        } catch (e: any) {
          skipped.push({ employeeId, reason: e?.message || "فشل الربط" });
        }
      }
      res.json({ linked, skipped });
    } catch (error: any) {
      console.error("Error confirming portal-account links:", error);
      res.status(500).json({ error: "فشل في تنفيذ الربط" });
    }
  });

  // Bulk-generate portal login accounts for selected employees that don't have one.
  app.post("/api/admin/portal-accounts/bulk-generate", isAuthenticated, requirePermission("users", "create"), async (req, res) => {
    try {
      const ids: number[] = Array.isArray(req.body?.employeeIds)
        ? req.body.employeeIds.map((n: any) => parseInt(n, 10)).filter((n: number) => !isNaN(n))
        : [];
      if (ids.length === 0) {
        return res.status(400).json({ error: "لم يتم تحديد أي موظف" });
      }
      const pick = (s: string): string => s[randomInt(s.length)];
      const genPassword = (): string => {
        const U = "ABCDEFGHJKLMNPQRSTUVWXYZ", L = "abcdefghijkmnpqrstuvwxyz", D = "23456789";
        const all = U + L + D;
        const chars = [pick(U), pick(L), pick(D)];
        for (let i = 0; i < 7; i++) chars.push(pick(all));
        // Fisher-Yates shuffle using crypto RNG
        for (let i = chars.length - 1; i > 0; i--) {
          const j = randomInt(i + 1);
          [chars[i], chars[j]] = [chars[j], chars[i]];
        }
        return chars.join("");
      };
      const genUsername = async (empId: number): Promise<string> => {
        let candidate = `emp${empId}`;
        if (!(await storage.getUserByUsername(candidate))) return candidate;
        for (let i = 0; i < 20; i++) {
          candidate = `emp${empId}${100 + randomInt(900)}`;
          if (!(await storage.getUserByUsername(candidate))) return candidate;
        }
        return `emp${empId}${Date.now().toString().slice(-5)}`;
      };

      // Load existing accounts once to prevent creating a duplicate when a matching user already exists.
      const allEmployees = await storage.getAllBranchEmployees();
      const allUsers = await storage.getAllUsers();
      const linkedUserIds = new Set(allEmployees.map((e) => e.linkedUserId).filter(Boolean) as string[]);
      const unlinkedUsers = allUsers.filter((u) => u.id && !linkedUserIds.has(u.id));

      const created: { id: number; employeeName: string; username: string; password: string }[] = [];
      const skipped: { id: number; reason: string }[] = [];
      for (const id of ids) {
        const employee = await storage.getBranchEmployee(id);
        if (!employee) { skipped.push({ id, reason: "غير موجود" }); continue; }
        if (employee.status !== "active") { skipped.push({ id, reason: "موظف غير نشط" }); continue; }
        if (employee.linkedUserId) { skipped.push({ id, reason: "مرتبط بحساب بالفعل" }); continue; }
        if (!isUserAdmin(req)) {
          const ok = await canAccessBranch(req, employee.branchId);
          if (!ok) { skipped.push({ id, reason: "غير مصرح" }); continue; }
        }
        // No-duplicate rule: if an existing user account matches this employee, link it instead.
        const existingMatch = matchUserForEmployee(employee, unlinkedUsers as any);
        if (existingMatch) {
          skipped.push({ id, reason: "يوجد حساب مطابق — اربطه بدلاً من الإنشاء" });
          continue;
        }
        const username = await genUsername(id);
        const password = genPassword();
        const fullName = (employee.employeeName || "").trim();
        const nameParts = fullName.split(/\s+/);
        const firstName = nameParts[0] || fullName || username;
        const lastName = nameParts.length > 1 ? nameParts.slice(1).join(" ") : "";
        try {
          await storage.createBranchEmployeeAccount({
            branchEmployeeId: id,
            username,
            password,
            firstName,
            lastName,
            branchId: employee.branchId || null,
          });
          created.push({ id, employeeName: employee.employeeName, username, password });
        } catch (e: any) {
          skipped.push({ id, reason: e?.message || "فشل الإنشاء" });
        }
      }
      res.status(201).json({ created, skipped });
    } catch (error: any) {
      console.error("Error bulk-generating portal accounts:", error);
      res.status(500).json({ error: "فشل في توليد الحسابات" });
    }
  });

