  app.post("/api/warehouse/material-transfers", isAuthenticated, requirePermission("warehouse", "create"), async (req, res) => {
    try {
      const user = req.currentUser;
      const { items, ...transferData } = req.body;
      
      // SECURITY: Apply branch filter
      const branchFilter = getEffectiveBranchFilter(req, transferData.sourceBranchId);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "لا يمكنك إنشاء تحويل من فرع غير فرعك" });
      }
      
      const transferNumber = await storage.generateMaterialTransferNumber();
      
      const transfer = await storage.createMaterialTransfer({
        ...transferData,
        transferNumber,
        createdBy: user?.id,
        createdByName: [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.username
      }, items || []);
      
      res.status(201).json(transfer);
    } catch (error) {
      console.error("Error creating material transfer:", error);
      res.status(500).json({ error: "فشل في إنشاء التحويل" });
    }
  });

  app.put("/api/warehouse/material-transfers/:id/status", isAuthenticated, requirePermission("warehouse", "edit"), async (req, res) => {
    try {
      const user = req.currentUser;
      const { status, receiverSignature, ...additionalData } = req.body;
      
      if (!['pending', 'approved', 'rejected', 'in_transit', 'delivered', 'cancelled'].includes(status)) {
        return res.status(400).json({ error: "حالة غير صالحة" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const existingTransfer = await storage.getMaterialTransferWithItems(parseInt(req.params.id));
        if (existingTransfer) {
          const sourceAccess = await canAccessBranch(req, existingTransfer.transfer.sourceBranchId || '');
          const destAccess = await canAccessBranch(req, existingTransfer.transfer.destinationBranchId || '');
          if (!sourceAccess && !destAccess) {
            return res.status(403).json({ error: "غير مصرح بتعديل حالة هذا التحويل" });
          }
        }
      }
      
      const updateData: any = { ...additionalData };
      
      if (status === 'in_transit') {
        updateData.departureTime = new Date();
      } else if (status === 'delivered') {
        updateData.arrivalTime = new Date();
        updateData.receivedBy = user?.id;
        updateData.receivedByName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.username;
        if (receiverSignature) {
          updateData.receiverSignature = receiverSignature;
        }
      }
      
      let transfer;
      
      // When delivered, use atomic transaction for status + stock + logs
      if (status === 'delivered') {
        transfer = await storage.deliverMaterialTransferWithStockUpdate(
          parseInt(req.params.id),
          updateData,
          user?.id
        );
      } else {
        transfer = await storage.updateMaterialTransferStatus(
          parseInt(req.params.id),
          status,
          updateData
        );
      }
      
      if (!transfer) {
        return res.status(404).json({ error: "التحويل غير موجود" });
      }
      
      // Create notification for the destination branch
      try {
        const notifType = status === "in_transit" ? "transfer_started" : 
                         status === "delivered" ? "transfer_delivered" : "transfer_cancelled";
        const titleAr = status === "in_transit" ? `شحنة في الطريق: ${transfer.transferNumber}` :
                       status === "delivered" ? `تم استلام شحنة: ${transfer.transferNumber}` :
                       `تم إلغاء التحويل: ${transfer.transferNumber}`;
        const titleEn = status === "in_transit" ? `Shipment In Transit: ${transfer.transferNumber}` :
                       status === "delivered" ? `Shipment Delivered: ${transfer.transferNumber}` :
                       `Transfer Cancelled: ${transfer.transferNumber}`;
        const bodyAr = status === "in_transit" ? "الشحنة في الطريق إليكم" :
                      status === "delivered" ? "تم استلام الشحنة بنجاح" :
                      "تم إلغاء التحويل";
        const bodyEn = status === "in_transit" ? "Shipment is on its way to you" :
                      status === "delivered" ? "Shipment was successfully delivered" :
                      "Transfer was cancelled";
        
        await storage.createWarehouseNotification({
          type: notifType,
          title: titleAr,
          titleEn: titleEn,
          body: bodyAr,
          bodyEn: bodyEn,
          branchId: transfer.destinationBranchId,
          targetBranchId: transfer.sourceBranchId,
          entityType: "transfer",
          entityId: transfer.id,
          priority: status === "in_transit" ? "high" : "normal",
        });
      } catch (e) { console.error("Failed to create notification:", e); }
      
      res.json(transfer);
    } catch (error) {
      console.error("Error updating transfer status:", error);
      res.status(500).json({ error: "فشل في تحديث حالة التحويل" });
    }
  });

  // Modify transfer quantities by warehouse manager (before dispatch only)
  app.post("/api/warehouse/material-transfers/:id/modify-quantities", isAuthenticated, requirePermission("warehouse", "edit"), async (req, res) => {
    try {
      const user = req.currentUser;
      const { modifications } = req.body;
      
      // modifications: [{ itemId: number, newQuantity: number, modificationNotes?: string }]
      if (!modifications || !Array.isArray(modifications)) {
        return res.status(400).json({ error: "يجب توفير بيانات التعديل" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const existingTransfer = await storage.getMaterialTransferWithItems(parseInt(req.params.id));
        if (existingTransfer) {
          const hasAccess = await canAccessBranch(req, existingTransfer.transfer.sourceBranchId || '');
          if (!hasAccess) {
            return res.status(403).json({ error: "غير مصرح بتعديل كميات هذا التحويل" });
          }
        }
      }
      
      // Validate all quantities are positive
      for (const mod of modifications) {
        if (mod.newQuantity < 0) {
          return res.status(400).json({ error: "الكمية يجب أن تكون رقم موجب" });
        }
      }
      
      const transfer = await storage.modifyTransferQuantities(
        parseInt(req.params.id),
        modifications,
        user?.id || '',
        [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.username || ''
      );
      
      // Create notification about quantity modification
      try {
        await storage.createWarehouseNotification({
          type: "transfer_modified",
          title: `تم تعديل كميات: ${transfer.transferNumber}`,
          titleEn: `Quantities Modified: ${transfer.transferNumber}`,
          body: `تم تعديل بعض الكميات من قبل مسؤول المستودع: ${[user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.username}`,
          bodyEn: `Some quantities were modified by warehouse manager: ${[user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.username}`,
          branchId: transfer.sourceBranchId || undefined,
          targetBranchId: transfer.destinationBranchId,
          entityType: "transfer",
          entityId: transfer.id,
          priority: "normal",
        });
      } catch (e) { console.error("Failed to create notification:", e); }
      
      res.json(transfer);
    } catch (error: any) {
      console.error("Error modifying transfer quantities:", error);
      console.error("Quantity adjustment error:", error); res.status(400).json({ error: "فشل في تعديل الكميات" });
    }
  });

  // Confirm delivery with received quantities for each item
  app.post("/api/warehouse/material-transfers/:id/confirm-delivery", isAuthenticated, requirePermission("warehouse", "edit"), async (req, res) => {
    try {
      const user = req.currentUser;
      const { receivedItems, receiverSignature, deliveryNotes } = req.body;
      
      // receivedItems: [{ itemId: number, receivedQuantity: number, discrepancyNotes?: string }]
      if (!receivedItems || !Array.isArray(receivedItems)) {
        return res.status(400).json({ error: "يجب توفير بيانات الاستلام" });
      }
      
      // SECURITY: Verify branch access for non-admin users (only destination branch can confirm)
      if (!isUserAdmin(req)) {
        const existingTransfer = await storage.getMaterialTransferWithItems(parseInt(req.params.id));
        if (existingTransfer) {
          const hasAccess = await canAccessBranch(req, existingTransfer.transfer.destinationBranchId || '');
          if (!hasAccess) {
            return res.status(403).json({ error: "فقط الفرع المستلم يمكنه تأكيد الاستلام" });
          }
        }
      }
      
      const transfer = await storage.confirmMaterialTransferDelivery(
        parseInt(req.params.id),
        receivedItems,
        {
          receivedBy: user?.id ?? undefined,
          receivedByName: [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.username || undefined,
          receiverSignature,
          deliveryNotes
        },
        user?.id ?? undefined
      );
      
      if (!transfer) {
        return res.status(404).json({ error: "التحويل غير موجود" });
      }
      
      // Create notification for delivery confirmation
      try {
        await storage.createWarehouseNotification({
          type: "transfer_delivered",
          title: `تم تأكيد استلام: ${transfer.transferNumber}`,
          titleEn: `Delivery Confirmed: ${transfer.transferNumber}`,
          body: transfer.hasDiscrepancy ? "تم الاستلام مع وجود فروقات في الكميات" : "تم استلام الشحنة كاملة بنجاح",
          bodyEn: transfer.hasDiscrepancy ? "Delivery confirmed with quantity discrepancies" : "Shipment received in full successfully",
          branchId: transfer.sourceBranchId || undefined,
          targetBranchId: transfer.destinationBranchId,
          entityType: "transfer",
          entityId: transfer.id,
          priority: transfer.hasDiscrepancy ? "high" : "normal",
        });
      } catch (e) { console.error("Failed to create notification:", e); }
      
      res.json(transfer);
    } catch (error) {
      console.error("Error confirming delivery:", error);
      res.status(500).json({ error: "فشل في تأكيد الاستلام" });
    }
  });

