  app.post("/api/purchasing/requests", isAuthenticated, requirePermission("warehouse", "create"), async (req, res) => {
    try {
      const purchasingRequestSchema = z.object({
        branchId: z.string(),
        priority: z.string().default("normal"),
        vendorName: z.string().optional(),
        notes: z.string().optional(),
        items: z.array(z.object({
          itemId: z.number(),
          itemName: z.string(),
          quantityRequested: z.union([z.string(), z.number()]),
          availableQuantity: z.union([z.string(), z.number()]).optional(),
          unit: z.string().default("unit"),
          estimatedUnitCost: z.union([z.string(), z.number()]).optional(),
        })).optional(),
      });

      const parseResult = purchasingRequestSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "بيانات غير صالحة", details: parseResult.error.errors });
      }

      const user = req.currentUser;
      const { items, ...requestData } = parseResult.data;
      
      const requestNumber = await storage.generatePurchasingRequestNumber();
      
      // Map frontend field names to database field names
      const mappedItems = (items || []).map(item => ({
        itemId: item.itemId,
        itemName: item.itemName,
        unit: item.unit,
        requestedQuantity: Number(item.quantityRequested) || 0,
        approvedQuantity: Number(item.availableQuantity) || 0, // Store availableQuantity as approvedQuantity
        unitPrice: item.estimatedUnitCost ? String(item.estimatedUnitCost) : null,
      }));
      
      // Calculate total estimated cost from items
      const totalEstimatedCost = mappedItems.reduce((sum, item) => {
        const qty = item.requestedQuantity || 0;
        const price = item.unitPrice ? parseFloat(item.unitPrice) : 0;
        return sum + (qty * price);
      }, 0);
      
      const request = await storage.createPurchasingRequest(
        { 
          ...requestData, 
          requestNumber, 
          requestedBy: user?.id, 
          requestedByName: user?.username,
          totalEstimatedCost: totalEstimatedCost > 0 ? String(totalEstimatedCost) : null 
        },
        mappedItems
      );
      
      res.json(request);
    } catch (error) {
      console.error("Error creating purchasing request:", error);
      res.status(500).json({ error: "فشل في إنشاء طلب المشتريات" });
    }
  });

