  // General-purpose file upload endpoint - Uses Supabase Storage
  app.post("/api/uploads", uploadRateLimiter, isAuthenticated, async (req, res) => {
    try {
      const multer = (await import("multer")).default;
      const path = await import("path");
      const { uploadToSupabase, isSupabaseAvailable } = await import("./supabase-storage");

      if (!isSupabaseAvailable()) {
        return res.status(503).json({ error: "خدمة التخزين غير متاحة حالياً. يرجى التحقق من إعدادات Supabase." });
      }

      const allowedTypes = [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "application/vnd.ms-powerpoint",
        "application/vnd.openxmlformats-officedocument.presentationml.presentation",
        "image/jpeg",
        "image/png",
        "image/gif",
        "image/webp",
        "text/plain",
        "text/csv",
        "application/zip",
        "application/x-rar-compressed",
      ];

      const blockedExtensions = ['.exe', '.bat', '.cmd', '.sh', '.ps1', '.vbs', '.js', '.msi', '.dll', '.scr', '.com'];

      const upload = multer({
        storage: multer.memoryStorage(),
        limits: { fileSize: 50 * 1024 * 1024 },
        fileFilter: (_req, file, cb) => {
          if (!allowedTypes.includes(file.mimetype)) {
            cb(new Error("نوع الملف غير مسموح") as any, false);
            return;
          }
          const ext = path.extname(file.originalname).toLowerCase();
          if (blockedExtensions.includes(ext)) {
            cb(new Error("امتداد الملف محظور لأسباب أمنية") as any, false);
            return;
          }
          const sanitizedName = file.originalname.replace(/[^a-zA-Z0-9\u0600-\u06FF._-]/g, '_');
          file.originalname = sanitizedName;
          cb(null, true);
        },
      });

      upload.single("file")(req, res, async (err: any) => {
        if (err) {
          console.error("Upload error:", err);
          if (err.code === "LIMIT_FILE_SIZE") {
            return res.status(400).json({ error: "حجم الملف يتجاوز الحد المسموح (50MB)" });
          }
          return res.status(400).json({ error: err.message || "فشل في رفع الملف" });
        }

        const file = (req as any).file;
        if (!file) {
          return res.status(400).json({ error: "لم يتم تحديد ملف للرفع" });
        }

        try {
          const folder = (typeof req.query.folder === 'string' ? req.query.folder : 'general').replace(/[^a-zA-Z0-9_-]/g, '_');
          const ext = path.extname(file.originalname).toLowerCase().replace(".", "");
          const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
          const objectName = `${folder}/${uniqueSuffix}.${ext}`;

          const supabaseResult = await uploadToSupabase(file.buffer, objectName, file.mimetype);
          if (!supabaseResult) {
            throw new Error("Supabase upload failed");
          }

          // CRITICAL: `uploadToSupabase` sanitizes the filename (replaces '/'
          // with '_' and appends timestamp + random suffix to guarantee
          // uniqueness) before sending it to Supabase. Always use the
          // returned `path` — using the requested `objectName` here saves a
          // path that doesn't exist in storage and causes broken images.
          const storedPath = supabaseResult.path;
          console.log("File uploaded to Supabase Storage:", { requested: objectName, stored: storedPath });

          res.json({
            fileName: file.originalname,
            fileType: ext,
            fileSize: file.size,
            filePath: storedPath,
            mimeType: file.mimetype,
            downloadUrl: `/api/uploads/file/${storedPath}`,
          });
        } catch (uploadError) {
          console.error("Storage upload error:", uploadError);
          res.status(500).json({ error: "فشل في رفع الملف إلى التخزين السحابي" });
        }
      });
    } catch (error) {
      console.error("Error uploading file:", error);
      res.status(500).json({ error: "فشل في رفع الملف" });
    }
  });

  // Serve general uploaded files (authenticated)
  app.get("/api/uploads/file/*", isAuthenticated, async (req, res) => {
    try {
      const { downloadFromSupabase, isSupabaseAvailable } = await import("./supabase-storage");

      if (!isSupabaseAvailable()) {
        return res.status(503).json({ error: "خدمة التخزين غير متاحة حالياً" });
      }
      const pathModule = await import("path");

      const rawPath = req.params[0];
      if (!rawPath || rawPath.includes('..') || rawPath.includes('\0')) {
        return res.status(400).json({ error: "اسم ملف غير صالح" });
      }

      const filename = rawPath.split('/').map((p: string) => pathModule.basename(p)).join('/');

      let result = await downloadFromSupabase(filename);

      // RECOVERY for legacy rows: rows uploaded before the storedPath fix
      // saved `filePath` with the original folder layout (e.g.
      // `cashier-journals/4/123-456.jpg`) but the actual object in Supabase
      // was stored as `cashier-journals_4_123-456_<TS>_<RAND>.jpg`. When the
      // direct lookup fails AND the path contains slashes, try to locate the
      // real object by listing the bucket with the sanitized prefix.
      if (!result && filename.includes('/')) {
        try {
          const { findLegacyMatch } = await import("./supabase-storage");
          const ext = filename.split('.').pop()?.toLowerCase() || '';
          const sanitizedBase = filename
            .replace(/\.[^/.]+$/, '')
            .replace(/[^a-zA-Z0-9\u0600-\u06FF._-]/g, '_');
          const recovered = await findLegacyMatch(sanitizedBase, ext);
          if (recovered) {
            console.log("[uploads/file] recovered legacy path", { requested: filename, recovered });
            result = await downloadFromSupabase(recovered);
          }
        } catch (recoverErr) {
          console.warn("[uploads/file] legacy recovery failed", recoverErr);
        }
      }

      if (!result) {
        return res.status(404).json({ error: "الملف غير موجود" });
      }

      const arrayBuffer = await result.data.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      res.set({
        "Content-Type": result.mimeType || "application/octet-stream",
        "Content-Length": buffer.length.toString(),
        "Content-Disposition": "inline",
        "Cache-Control": "private, max-age=3600",
      });

      res.send(buffer);
    } catch (error) {
      console.error("Error serving uploaded file:", error);
      res.status(500).json({ error: "فشل في جلب الملف" });
    }
  });

  // Upload Document File - Uses Supabase Storage
  app.post("/api/documents/upload", isAuthenticated, requirePermission("documents", "create"), async (req, res) => {
    try {
      const multer = (await import("multer")).default;
      const path = await import("path");
      const crypto = await import("crypto");
      const { uploadToSupabase } = await import("./supabase-storage");

      const allowedTypes = [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "application/vnd.ms-powerpoint",
        "application/vnd.openxmlformats-officedocument.presentationml.presentation",
        "image/jpeg",
        "image/png",
        "image/gif",
        "image/webp",
        "text/plain",
        "text/csv",
        "application/zip",
        "application/x-rar-compressed",
      ];

      // Blocked extensions for security
      const blockedExtensions = ['.exe', '.bat', '.cmd', '.sh', '.ps1', '.vbs', '.js', '.msi', '.dll', '.scr', '.com'];
      
      const upload = multer({
        storage: multer.memoryStorage(),
        limits: { fileSize: 50 * 1024 * 1024 }, // 50MB max
        fileFilter: (_req, file, cb) => {
          // Check MIME type
          if (!allowedTypes.includes(file.mimetype)) {
            cb(new Error("نوع الملف غير مسموح") as any, false);
            return;
          }
          
          // Check for blocked extensions (security)
          const ext = path.extname(file.originalname).toLowerCase();
          if (blockedExtensions.includes(ext)) {
            cb(new Error("امتداد الملف محظور لأسباب أمنية") as any, false);
            return;
          }
          
          // Sanitize filename to prevent path traversal
          const sanitizedName = file.originalname.replace(/[^a-zA-Z0-9\u0600-\u06FF._-]/g, '_');
          file.originalname = sanitizedName;
          
          cb(null, true);
        },
      });

      upload.single("file")(req, res, async (err: any) => {
        if (err) {
          console.error("Upload error:", err);
          if (err.code === "LIMIT_FILE_SIZE") {
            return res.status(400).json({ error: "حجم الملف يتجاوز الحد المسموح (50MB)" });
          }
          return res.status(400).json({ error: err.message || "فشل في رفع الملف" });
        }

        const file = (req as any).file;
        if (!file) {
          return res.status(400).json({ error: "لم يتم تحديد ملف للرفع" });
        }

        try {
          // Calculate file checksum
          const checksum = crypto.createHash("md5").update(file.buffer).digest("hex");

          // Extract file type from extension
          const ext = path.extname(file.originalname).toLowerCase().replace(".", "");
          
          // Generate unique filename
          const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
          const objectName = `doc-${uniqueSuffix}.${ext}`;
          
          const supabaseResult = await uploadToSupabase(file.buffer, objectName, file.mimetype);
          if (!supabaseResult) {
            throw new Error("Supabase upload failed");
          }
          // Use the actual stored path (uploadToSupabase sanitizes + suffixes
          // the filename). Storing `objectName` instead causes 404 on read.
          const filePath = supabaseResult.path;
          console.log("File uploaded to Supabase Storage:", { requested: objectName, stored: filePath });

          res.json({
            fileName: file.originalname,
            fileType: ext,
            fileSize: file.size,
            filePath: filePath,
            mimeType: file.mimetype,
            checksum: checksum,
          });
        } catch (uploadError) {
          console.error("Storage upload error:", uploadError);
          res.status(500).json({ error: "فشل في رفع الملف إلى التخزين السحابي" });
        }
      });
    } catch (error) {
      console.error("Error uploading document:", error);
      res.status(500).json({ error: "فشل في رفع الملف" });
    }
  });

  // Serve uploaded files (authenticated) - From Object Storage
  app.get("/api/documents/file/:filename", isAuthenticated, requirePermission("documents", "view"), async (req, res) => {
    try {
      const { downloadFromSupabase } = await import("./supabase-storage");
      const pathModule = await import("path");
      const filename = pathModule.basename(req.params.filename);
      if (!filename || filename === '.' || filename === '..' || filename.includes('\0')) {
        return res.status(400).json({ error: "اسم ملف غير صالح" });
      }
      
      // Download from Supabase Storage
      const result = await downloadFromSupabase(filename);
      if (result) {
        const arrayBuffer = await result.data.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);
        
        res.set({
          "Content-Type": result.mimeType || "application/octet-stream",
          "Content-Length": buffer.length.toString(),
          "Content-Disposition": "inline",
          "X-Frame-Options": "SAMEORIGIN",
          "Cache-Control": "private, max-age=3600",
        });
        
        res.send(buffer);
        return;
      }
      
      // Fallback to local storage for old files
      const path = await import("path");
      const fs = await import("fs");
      const filePath = path.join("./uploads/documents", filename);
      const resolvedPath = path.resolve(filePath);
      const uploadsDir = path.resolve("./uploads/documents");
      if (!resolvedPath.startsWith(uploadsDir)) {
        return res.status(400).json({ error: "مسار ملف غير صالح" });
      }
      
      if (fs.existsSync(resolvedPath)) {
        return res.sendFile(resolvedPath);
      }
      
      return res.status(404).json({ error: "الملف غير موجود" });
    } catch (error) {
      console.error("Error serving file:", error);
      res.status(500).json({ error: "فشل في جلب الملف" });
    }
  });

  // Serve shared files (public access via share link) - From Object Storage
  app.get("/api/documents/shared-file/:shareLink/:filename", apiRateLimiter, async (req, res) => {
    try {
      const shareLink = req.params.shareLink;
      if (!shareLink || !/^[a-f0-9]{32}$/.test(shareLink)) {
        return res.status(400).json({ error: "رابط مشاركة غير صالح" });
      }
      
      const pathModule = await import("path");
      const safeFilename = pathModule.basename(req.params.filename);
      if (!safeFilename || safeFilename === '.' || safeFilename === '..' || safeFilename.includes('\0')) {
        return res.status(400).json({ error: "اسم ملف غير صالح" });
      }
      
      const share = await storage.getDocumentShareByLink(shareLink);
      if (!share || !share.isActive) {
        return res.status(403).json({ error: "رابط المشاركة غير صالح أو غير نشط" });
      }
      
      if (share.expiresAt && new Date(share.expiresAt) < new Date()) {
        return res.status(403).json({ error: "انتهت صلاحية رابط المشاركة" });
      }
      
      const doc = await storage.getDocument(share.documentId);
      if (!doc) {
        return res.status(404).json({ error: "الوثيقة غير موجودة" });
      }
      
      const expectedFilename = doc.filePath.split("/").pop();
      if (safeFilename !== expectedFilename) {
        return res.status(403).json({ error: "غير مصرح بالوصول لهذا الملف" });
      }
      
      const { downloadFromSupabase } = await import("./supabase-storage");
      
      // Try Supabase Storage first
      const supabaseResult = await downloadFromSupabase(safeFilename);
      if (supabaseResult) {
        const arrayBuffer = await supabaseResult.data.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);
        
        res.set({
          "Content-Type": supabaseResult.mimeType || "application/octet-stream",
          "Content-Length": buffer.length.toString(),
          "Content-Disposition": "inline",
          "Cache-Control": "private, max-age=3600",
        });
        
        res.send(buffer);
        return;
      }
      
      // Fallback to local storage for old files
      const path = await import("path");
      const fs = await import("fs");
      const filePath = path.join("./uploads/documents", safeFilename);
      const resolvedPath = path.resolve(filePath);
      const uploadsDir = path.resolve("./uploads/documents");
      if (!resolvedPath.startsWith(uploadsDir)) {
        return res.status(400).json({ error: "مسار ملف غير صالح" });
      }
      
      if (fs.existsSync(resolvedPath)) {
        return res.sendFile(resolvedPath);
      }
      
      return res.status(404).json({ error: "الملف غير موجود" });
    } catch (error) {
      console.error("Error serving shared file:", error);
      res.status(500).json({ error: "فشل في جلب الملف" });
    }
  });

  // Public share link access (no auth required) - uses POST for password security
  app.post("/api/documents/share/:shareLink", authRateLimiter, async (req, res) => {
    try {
      const shareLink = req.params.shareLink;
      if (!shareLink || !/^[a-f0-9]{32}$/.test(shareLink)) {
        return res.status(400).json({ error: "رابط مشاركة غير صالح" });
      }
      const share = await storage.getDocumentShareByLink(shareLink);
      if (!share) {
        return res.status(404).json({ error: "رابط المشاركة غير صالح" });
      }

      if (!share.isActive) {
        return res.status(403).json({ error: "رابط المشاركة غير نشط" });
      }

      if (share.expiresAt && new Date(share.expiresAt) < new Date()) {
        return res.status(403).json({ error: "انتهت صلاحية رابط المشاركة" });
      }

      if (share.maxAccessCount && (share.accessCount ?? 0) >= share.maxAccessCount) {
        return res.status(403).json({ error: "تم تجاوز الحد الأقصى للوصول" });
      }

      // Check password if required
      if (share.sharePassword) {
        const providedPassword = req.body?.password as string;
        if (!providedPassword) {
          return res.status(401).json({ 
            error: "هذا الرابط محمي بكلمة مرور",
            requiresPassword: true 
          });
        }
        // Use timing-safe comparison to prevent timing attacks
        const crypto = await import("crypto");
        const providedHash = crypto.createHash('sha256').update(providedPassword).digest('hex');
        const storedHash = share.sharePassword.length === 64 ? share.sharePassword : crypto.createHash('sha256').update(share.sharePassword).digest('hex');
        
        if (!crypto.timingSafeEqual(Buffer.from(providedHash), Buffer.from(storedHash))) {
          return res.status(401).json({ 
            error: "كلمة المرور غير صحيحة",
            requiresPassword: true 
          });
        }
      }

      // Increment access count
      await storage.incrementShareAccessCount(share.id);

      // Get document
      const doc = await storage.getDocument(share.documentId);
      if (!doc) {
        return res.status(404).json({ error: "الوثيقة غير موجودة" });
      }

      // Log access
      await storage.logDocumentAccess({
        documentId: doc.id,
        action: 'view',
        actionDetails: `الوصول عبر رابط المشاركة: ${share.shareLink}`,
      });

      res.json({
        document: {
          id: doc.id,
          title: doc.title,
          description: doc.description,
          fileName: doc.fileName,
          fileType: doc.fileType,
          fileSize: doc.fileSize,
          mimeType: doc.mimeType,
          filePath: doc.filePath,
          accessLevel: doc.accessLevel,
          currentVersion: doc.currentVersion,
          createdAt: doc.createdAt,
        },
        permission: share.permission,
        canDownload: share.permission !== 'view',
        expiresAt: share.expiresAt,
        accessCount: share.accessCount,
        maxAccessCount: share.maxAccessCount,
      });
    } catch (error) {
      console.error("Error accessing share:", error);
      res.status(500).json({ error: "فشل في الوصول للمشاركة" });
    }
  });

