  // Get branch shifts
  app.get("/api/branch-shifts", isAuthenticated, requirePermission("branch_closure", "view"), async (req, res) => {
    try {
      const { branchId, date, status } = req.query;
      let conditions = [];
      
      // SECURITY: Apply branch filter
      const branchFilter = getEffectiveBranchFilter(req, branchId as string | undefined);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      if (branchFilter.singleBranchId) {
        conditions.push(eq(branchShifts.branchId, branchFilter.singleBranchId));
      } else if (branchId) {
        conditions.push(eq(branchShifts.branchId, branchId as string));
      }
      
      if (date) conditions.push(eq(branchShifts.shiftDate, date as string));
      if (status) conditions.push(eq(branchShifts.status, status as string));
      
      const shifts = conditions.length > 0
        ? await db.select().from(branchShifts).where(and(...conditions)).orderBy(desc(branchShifts.shiftDate))
        : await db.select().from(branchShifts).orderBy(desc(branchShifts.shiftDate));
      
      res.json(shifts);
    } catch (error) {
      console.error("Error fetching branch shifts:", error);
      res.status(500).json({ error: "فشل في جلب سجل الشفتات" });
    }
  });

